    public void displayNextSetOfFlights(ExtentTest logInfo,String Origin, String Destination, int segmentIndex, int departuredate)
    {
        String command ;

        try {
            //A PTYLAX 10NOV-CM

            String airline = mPassengers.get(getDriverID()).get(0).getAirline(segmentIndex);

            String DateFormatted = gl.plusDaysFromTodayNew(departuredate);
            LocalDateTime departureDate = DateUtil.formatToLocalDateTime(DateFormatted, "10:10");
            String departureDateFormatted = DateUtil.formatDateToSharesDateFormat(departureDate.toLocalDate());

            if (airline.equalsIgnoreCase("CM")) {
                command = "A " + Origin + Destination + " " + departureDateFormatted;
            } else if (airline.equalsIgnoreCase("UA")) {
                command = "A " + Origin + Destination + " " + departureDateFormatted + "-" + "UA";
            } else if (airline.equalsIgnoreCase("Redemption")) {
                command = "A " + Origin + Destination + " " + departureDateFormatted + "/" + "R";
            } else if (airline.equalsIgnoreCase("TK")) {
                command = "A " + Origin + Destination + " " + departureDateFormatted;
            }else if (airline.equalsIgnoreCase("IB")) {
                command = "A " + Origin + Destination + " " + departureDateFormatted + "-" + "IB";
            }else if (airline.equalsIgnoreCase("G3")) {
                command = "A " + Origin + Destination + " " + departureDateFormatted + "-" + "G3";
            }  else if (airline.equalsIgnoreCase("BA")) {
                command = "A " + Origin + Destination + " " + departureDateFormatted + "-" + "BA";
            } else if (airline.equalsIgnoreCase("LH")) {
                command = "A " + Origin + Destination + " " + departureDateFormatted + "-" + "LH";
            } else {
                command = "A " + Origin + Destination + " " + departureDateFormatted;
            }

            gl.logCommand(logInfo, command);
            gl.sendCmdValidateResponse(command, logInfo);

            String response = isharesPageObjects2.SHARES_RESPONSE.getText();
            gl.checkForErrors(command,response,logInfo);

            gl.logCommand(logInfo, "A*");
            gl.sendCmdValidateResponse("A*", logInfo);

            response = isharesPageObjects2.SHARES_RESPONSE.getText();
            gl.checkForErrors(command,response,logInfo);

            flightIndex.put(getDriverID(), getFlightPositionsForValidMarriedSegment(response, segmentIndex));
            System.out.println(flightIndex.get(getDriverID()));

        } catch (AssertionError | Exception e) {

            ExtentReportListener.testStepHandle("FAIL", getDriver(), logInfo, e);
            Assert.fail("This step failed.. so stopping...");
        }
    }

    public void openFlight(ExtentTest logInfo, String FlightNo, String departureDate, String OriginCity) {
        try {


            isharesPageObjects2.FORMSIZE_DROPDOWN.click();
            isharesPageObjects2.FORMSIZE_SELECT2.click();
            gl.waitForProfileLoad();

            String command = "6:*A" + FlightNo + "/" + departureDate + OriginCity;
            gl.logCommand(logInfo, command);
            gl.sendCmdForForm2ValidateResponse(command, logInfo);

            if(isharesPageObjects2.SHARES_RESPONSE.getText().contains("UNABL TO PROCESS-CODE SHARE FLIGHT"))
            {
                //For UA CODE SHARE FLIGHTS
                logInfo.info(MarkupHelper.createLabel("UNABL TO PROCESS-CODE SHARE FLIGHT : \n CODE SHARE FLIGHT : " + FlightNo +" CANT BE OPENED", ExtentColor.BLACK));
            }
            else if(isharesPageObjects2.SHARES_RESPONSE.getText().contains("SHIP ASSIGNED"))
            {
                Assert.assertTrue(isharesPageObjects2.SHARES_RESPONSE.getText().contains("SHIP ASSIGNED"));
                logInfo.pass(MarkupHelper.createLabel("SHIP ALREADY ASSIGNED FOR : " + FlightNo, ExtentColor.GREEN));
            }
            else
            {

                String response = isharesPageObjects2.SHARES_RESPONSE.getText();
                int eqp = response.indexOf(FlightNo, response.indexOf("EQP"));
                String EqpNumber = response.substring(eqp + 4, eqp + 10).trim();

                String command2 = "6:I*F" + EqpNumber;
                gl.logCommand(logInfo, command2);
                gl.sendCmdForForm2ValidateResponse(command2, logInfo);

                String responseForFleet = isharesPageObjects2.SHARES_RESPONSE.getText();
                fleetNumber.put(getDriverID(), getFleetNumbers(responseForFleet));

                String FleetNumber = fleetNumbers.get(1);
                System.out.println("Flight ship index " + FleetNumber);

                String command3 = "6:CA" + departureDate + "\n" + FlightNo + OriginCity + FleetNumber;

                isharesPageObjects2.FORMSIZE_SELECT2_TEXTAREA.click();

                gl.logCommand(logInfo, command3);
                gl.copyCmdToClipboardAndPaste(command3, isharesPageObjects2.FORMSIZE_SELECT2_TEXTAREA);

                isharesPageObjects2.SEND_ISHARES.click();
                gl.waitForProfileLoad();
                logInfo.addScreenCaptureFromBase64String(getBase64(getDriver()), "Screenshot");
                response = isharesPageObjects2.SHARES_RESPONSE.getText();
                gl.logResponse(logInfo, response);
                Assert.assertTrue(response.contains("SHIP ASSIGNED"));
            }


        } catch (AssertionError | Exception e) {

            ExtentReportListener.testStepHandle("FAIL", getDriver(), logInfo, e);
            Assert.fail("This step failed.. so stopping...");

        }

    }

    public void openFlight(ExtentTest logInfo) {
        try {
            Passenger pax = mPassengers.get(getDriverID()).get(0);
            String FlightNo = pax.getSegmentFlight(0);
            String departureDate = gl.sharesFormatDateFromGUI(pax.getSegmentDate(0));
            String OriginCity = pax.getSegmentOriginCity(0);

            isharesPageObjects2.FORMSIZE_DROPDOWN.click();
            isharesPageObjects2.FORMSIZE_SELECT2.click();
            gl.waitForProfileLoad();

            String command = "6:*A" + FlightNo + "/" + departureDate + OriginCity;
            gl.logCommand(logInfo, command);
            gl.sendCmdForForm2ValidateResponse(command, logInfo);

            if(isharesPageObjects2.SHARES_RESPONSE.getText().contains("UNABL TO PROCESS-CODE SHARE FLIGHT"))
            {
                //For UA CODE SHARE FLIGHTS
                logInfo.info(MarkupHelper.createLabel("UNABL TO PROCESS-CODE SHARE FLIGHT : \n CODE SHARE FLIGHT : " + FlightNo +" CANT BE OPENED", ExtentColor.BLACK));
            }
            else if(isharesPageObjects2.SHARES_RESPONSE.getText().contains("SHIP ASSIGNED"))
            {
                Assert.assertTrue(isharesPageObjects2.SHARES_RESPONSE.getText().contains("SHIP ASSIGNED"));
                logInfo.pass(MarkupHelper.createLabel("SHIP ALREADY ASSIGNED FOR : " + FlightNo, ExtentColor.GREEN));
            }
            else
            {
                String response = isharesPageObjects2.SHARES_RESPONSE.getText();
                int eqp = response.indexOf(FlightNo, response.indexOf("EQP"));
                String EqpNumber = response.substring(eqp + 4, eqp + 10).trim();

                String command2 = "6:I*F" + EqpNumber;
                gl.logCommand(logInfo, command2);
                gl.sendCmdForForm2ValidateResponse(command2, logInfo);

                String responseForFleet = isharesPageObjects2.SHARES_RESPONSE.getText();

                fleetNumber.put(getDriverID(), getFleetNumbers(responseForFleet));
                String FleetNumber = fleetNumbers.get(1);

                System.out.println("Flight ship index " + FleetNumber);

                String command3 = "6:CA" + departureDate + "\n" + FlightNo + OriginCity + FleetNumber;
                gl.logCommand(logInfo, command3);
                isharesPageObjects2.FORMSIZE_SELECT2_TEXTAREA.click();
                gl.copyCmdToClipboardAndPaste(command3, isharesPageObjects2.FORMSIZE_SELECT2_TEXTAREA);
                isharesPageObjects2.SEND_ISHARES.click();
                gl.waitForProfileLoad();

                response = isharesPageObjects2.SHARES_RESPONSE.getText();
                gl.logResponse(logInfo, response);
                logInfo.addScreenCaptureFromBase64String(getBase64(getDriver()), "Screenshot");

                Assert.assertTrue(response.contains("SHIP ASSIGNED"));

                logInfo.pass(MarkupHelper.createLabel("SHIP ASSIGNED SUCCESSFULLY FOR : " + FlightNo, ExtentColor.GREEN));
            }

            isharesPageObjects2.FORMSIZE_DROPDOWN.click();
            isharesPageObjects2.FORMSIZE_SELECT1.click();

        } catch (AssertionError | Exception e) {

            ExtentReportListener.testStepHandle("FAIL", getDriver(), logInfo, e);
            Assert.fail("This step failed.. so stopping...");

        }
    }

    public List<String> getFleetNumbers(String responseText) {

        // Split the response into lines
        String[] lines = responseText.split("\n");

        String fourDigitRegex = "\\s?(\\d{4})";
        // Compile the regex for 4-digit numbers
        Pattern fourDigitPattern = Pattern.compile(fourDigitRegex);


        for (int i = 0; i < lines.length; i++) {
            Matcher matcher = fourDigitPattern.matcher(lines[i]);
            while (matcher.find())
            {
                String numberLeft;
                if(matcher.group(1).contains(" "))
                    numberLeft = matcher.group(1).substring(1);
                else
                    numberLeft = matcher.group(1);

                fleetNumbers.add(numberLeft);
                System.out.println("4-digit Number" + numberLeft + " on line " + (i + 1));
            }
        }
        return fleetNumbers;
    }

