    public void displaySeatsAvailabilityForFlightsDifferentFormat(ExtentTest logInfo, String Origin, String Destination, int segmentNo, int departuredate) {
        String command;
        try {
            String airline = mPassengers.get(getDriverID()).get(0).getAirline(0);

            String DateFormatted = gl.plusDaysFromTodayNew(departuredate);
            LocalDateTime departureDate = DateUtil.formatToLocalDateTime(DateFormatted, "10:10");
            String departureDateFormatted = DateUtil.formatDateToSharesDateFormat(departureDate.toLocalDate());

            for (int i = 0; i < mPassengers.get(getDriverID()).size(); i++) {
                mPassengers.get(getDriverID()).get(i).setSegmentOriginCity(segmentNo, Origin);
                mPassengers.get(getDriverID()).get(i).setSegmentDestinationCity(segmentNo, Destination);
                mPassengers.get(getDriverID()).get(0).setSegmentDate(segmentNo, departuredate);
            }

            if (airline.equalsIgnoreCase("CM")) {
                command = "A " + departureDateFormatted + " " + Origin + Destination + "-CM";
            } else if (airline.equalsIgnoreCase("UA")) {
                command = "A " + Origin + Destination + " " + departureDateFormatted + "-" + "UA";
            } else if (airline.equalsIgnoreCase("Redemption")) {
                command = "A " + Origin + Destination + " " + departureDateFormatted + "/" + "R";
            } else if (airline.equalsIgnoreCase("A")) {
                command = "A " + departureDateFormatted + " " + Origin + Destination + "-A";
            } else if (airline.equalsIgnoreCase("C-A")) {
                command = "A " + departureDateFormatted + " " + Origin + Destination + " $C-A";
            } else if (airline.equalsIgnoreCase("$M")) {
                command = "A " + Origin + Destination + " $M";
            } else if (airline.equalsIgnoreCase("AA/CM/DL")) {          //A 28JUN PTYORD $Y-AA/CM/DL
                command = "A " + departureDateFormatted + " " + Origin + Destination + " $" + mPassengers.get(getDriverID()).get(0).getCOS() + "-AA/CM/DL";
            } else if (airline.equalsIgnoreCase("CM/UA")) {          //A 29DEC PTYLAX 800A $M-CM/UA
                command = "A " + departureDateFormatted + " " + Origin + Destination + " $" + mPassengers.get(getDriverID()).get(0).getCOS() + "-CM/UA";
            } else if (airline.equalsIgnoreCase("$*")) {          //A 28JUN LAXPTY 800A $*M
                command = "A " + departureDateFormatted + " " + Origin + Destination + "800A $*" + mPassengers.get(getDriverID()).get(0).getCOS();
            } else if (airline.equalsIgnoreCase("$C-CM/UA")) {          //A 29JUN LAXPTY5P-UA/CM
                command = "A " + departureDateFormatted + " " + Origin + Destination + "$C-CM/UA";
            } else if (airline.equalsIgnoreCase("UA/CM")) {          //A 29JUN LAXPTY5P-UA/CM
                command = "A " + departureDateFormatted + " " + Origin + Destination + " 5P-UA/CM";
            } else if (airline.equalsIgnoreCase("R")) {          //A 27JUL PTYLAX/R
                command = "A " + departureDateFormatted + " " + Origin + Destination + "/R";
            } else if (airline.equalsIgnoreCase("TK")) {
                command = "A " + Origin + Destination + " " + departureDateFormatted;
            } else if (airline.equalsIgnoreCase("AA")) {          //A PTYLAX 27JUL - AA
                command = "A " + Origin + Destination + " " + departureDateFormatted + " - AA";
            } else if (airline.equalsIgnoreCase("AV")) {          //A PTYLAX 27JUL - AV
                command = "A " + Origin + Destination + " " + departureDateFormatted + " - AV";
            }else if (airline.equalsIgnoreCase("No Airline")) {          //A PTYLAX
                command = "A " + Origin + Destination;
            }else if (airline.equalsIgnoreCase("$COS")) {          // A PTYBOG $A
                command = "A " + Origin + Destination + " $" + mPassengers.get(getDriverID()).get(0).getCOS();
            }else if (airline.equalsIgnoreCase("DateAnd$COS")) {          // A PTYBOG 29SEP $F
                command = "A " + Origin + Destination + " " + departureDateFormatted + " $" + mPassengers.get(getDriverID()).get(0).getCOS();
            }else if (airline.equalsIgnoreCase("$COSAndCO")) {    // A PTYIAH $Y-CO
                command = "A " + Origin + Destination + " " + departureDateFormatted + " $" + mPassengers.get(getDriverID()).get(0).getCOS() + "-CO";
            }else if (airline.equalsIgnoreCase("1A-CM/UA")) {          // A25SEPPTYIAH1A-CM/UA
                command = "A" + departureDateFormatted + Origin + Destination + "1A-CM/UA";
            }
            else {
                command = "A " + departureDateFormatted + " " + Origin + Destination;
            }

            gl.logCommand(logInfo, command);
            gl.sendCmdValidateResponse(command, logInfo);

            String response = isharesPageObjects2.SHARES_RESPONSE.getText();
            gl.checkForErrors(command,response,logInfo);

        } catch (AssertionError | Exception e) {

            ExtentReportListener.testStepHandle("FAIL", getDriver(), logInfo, e);
            Assert.fail("This step failed.. so stopping...");
        }
    }

