    public void searchFlightAvailabilityForSegmentWithDifferentFlight(ExtentTest logInfo, String Origin, String Destination)
    {
        try {

            String COS = mPassengers.get(getDriverID()).get(0).getCOS();
            int totalpax = mPassengers.get(getDriverID()).size();
            String airline = mPassengers.get(getDriverID()).get(0).getAirline(1);
            boolean flightBooked=false;
            int initialDepartureDate = mPassengers.get(getDriverID()).get(0).getSegmentDate(1);  //Getting the departure Date based on feature file input
            int departureEndDate = initialDepartureDate + 5;

            String oldFlight = mOldFlightNumber.get(getDriverID());
            System.out.println("OLD FLIGHT: "+oldFlight);

            int departuredate = initialDepartureDate; // Reset departure date for each class and destination

            DepartureDate:  // Iterate through date range
            while(departuredate <= departureEndDate)
            {
                displaySeatsAvailabilityForDifferentFlights(logInfo, Origin, Destination, 1, departuredate);

                Flight:          // Loop for flights
                for (int j = 1; j <= flightIndex.get(getDriverID()).size(); j++)
                {
                    String command ;
                    command = "N" + totalpax + COS + flightIndex.get(getDriverID()).get(j - 1);  //N2Y1

                    gl.logCommand(logInfo, command);
                    gl.sendCmdValidateResponse(command, logInfo);

                    String response = isharesPageObjects2.SHARES_RESPONSE.getText();
                    gl.checkForErrors(command,response,logInfo);

                    if( (response.contains("ETKT ELIGIBLE") || response.contains("ADV PAX FLT ARRIVES TERMINAL") ||
                            response.contains("SS" + totalpax) || response.contains("NN" + totalpax)) && !oldFlight.equalsIgnoreCase(response.substring(6, 10).trim()))
                    {
                        System.out.println("Flight Found !! New Flight Number: " + response.substring(6, 10));

                        // Assign flight details to passengers
                        for (Passenger pax : mPassengers.get(getDriverID())) {
                            pax.setSegmentFlight(1, response.substring(6, 10).trim());
                            pax.setSegmentDate(1, departuredate);
                            pax.setAirline(1, airline);
                            pax.setCOS(COS);
                        }

                        flightBooked=true;
                        break Flight; // Exit as soon as a flight is booked
                    }
                    else {
                        gl.ignoreTRNS(logInfo);
                        displaySeatsAvailabilityForDifferentFlights(logInfo, Origin, Destination, 1, departuredate);
                    }
                }
                // Move to the next day
                departuredate++;

                if (flightBooked) {
                    break; // Exit date loop if all days are checked
                }
            }
        } catch (AssertionError | Exception e) {

            ExtentReportListener.testStepHandle("FAIL", getDriver(), logInfo, e);
            Assert.fail("This step failed.. so stopping...");
        }
    }

    public void searchFlightAvailabilityForFirstSegForWaitlistPax(ExtentTest logInfo, String Origin, String Destination) {
        try {

            int totalpax = mPassengers.get(getDriverID()).size();
            String airline = mPassengers.get(getDriverID()).get(0).getAirline(0);
            int initialDepartureDate = mPassengers.get(getDriverID()).get(0).getSegmentDate(0); // Store the initial departure date
            boolean flightFound=false;
            int departureEndDate = initialDepartureDate + 5;

            String[] destinationCities = {"YYZ", "EZE", "JFK"};

            // Include primary destination first, then fallback destinations
            String[] allDestinations = new String[destinationCities.length + 1];
            allDestinations[0] = Destination;
            System.arraycopy(destinationCities, 0, allDestinations, 1, destinationCities.length);

            Destinations:
            for (String currentDestination : allDestinations)
            {
                int departuredate = initialDepartureDate; // Reset departure date for each class and destination

                DepartureDate:
                while (departuredate <= departureEndDate)
                {
                    displaySeatsAvailabilityForFlightsForWaitListPax(logInfo, Origin, currentDestination, 0, departuredate);
                    Map<String,List<String>> waitListFlights = enterVIXtoGetWaitlistFlightsAndClasses(logInfo,departuredate);

                    Flight:
                    for (Map.Entry<String,List<String>> flights: waitListFlights.entrySet()) {

                        logInfo.info(MarkupHelper.createLabel("The WaitList Classes are: "+flights.getValue()+" for Flight index "+flights.getKey(), ExtentColor.BLACK));
                        ClassOfService:
                        for (String tCOS : flights.getValue())
                        {
                            String command = "N" + totalpax + tCOS + flights.getKey();  //N2Y1

                            gl.logCommand(logInfo, command);
                            gl.sendCmdValidateResponse(command, logInfo);

                            String response = isharesPageObjects2.SHARES_RESPONSE.getText();
                            gl.checkForErrors(command, response, logInfo);

                            if (response.contains("ETKT ELIGIBLE") && (response.contains("PD") || response.contains("PC")))
                            {
                                // Assign flight details to passengers
                                for (Passenger pax : mPassengers.get(getDriverID())) {
                                    pax.setSegmentFlight(0, response.substring(6, 10).trim());
                                    pax.setSegmentDate(0, departuredate);
                                    pax.setAirline(0, airline);
                                    pax.setCOS(tCOS);

                                    int len = response.split("\n")[0].split(" ").length;

                                    if (airline.equalsIgnoreCase("CM")) {
                                        pax.setSegmentDepartureTime(0, response.split("\n")[0].split(" ")[len - 3]);
                                        if (pax.getSegmentDepartureTime(0).isEmpty()) {
                                            pax.setSegmentDepartureTime(0, response.split("\n")[0].split(" ")[len - 2]);
                                        }
                                        pax.setSegmentArrivalTime(0, response.split("\n")[0].split(" ")[len - 1]);
                                    } else {
                                        pax.setSegmentDepartureTime(0, response.split("\n")[0].split(" ")[len - 3]);
                                        pax.setSegmentArrivalTime(0, response.split("\n")[0].split(" ")[len - 1].split("/")[0]);
                                    }
                                }

                                flightFound=true;
                                break Destinations; // Exit as soon as a flight is booked

                            }
                            else {
                                gl.ignoreTRNS(logInfo);
                                displaySeatsAvailabilityForFlightsForWaitListPax(logInfo, Origin, currentDestination, 0, departuredate);
                            }
                        }

                    }

                    // Move to the next day
                    departuredate++;
                }
            }

            if(!flightFound)
                logInfo.info(MarkupHelper.createLabel("No Waitlist seats available for any destination within the specified range.", ExtentColor.RED));


        } catch (AssertionError | Exception e) {
            ExtentReportListener.testStepHandle("FAIL", getDriver(), logInfo, e);
            Assert.fail("This step failed.. so stopping...");
        }
    }

