    public void bookSpecificFlightforSingleSegment(ExtentTest logInfo, String flightNum, String segmentIndex) {
        try {
            // 036020MAYPTYLAX NN2
            Passenger pax = mPassengers.get(getDriverID()).get(0);

            String flight;

            if (flightNum.length() == 4)
                flight = flightNum;
            else if (flightNum.length() == 3)
                flight = "0" + flightNum;
            else
                flight = "00" + flightNum;

            String StartDate = gl.sharesFormatDateFromGUI(pax.getSegmentDate(Integer.parseInt(segmentIndex)));
            String OriginCity = pax.getSegmentOriginCity(Integer.parseInt(segmentIndex));
            String DestinationCity = pax.getSegmentDestinationCity(Integer.parseInt(segmentIndex));
            int totalPax = mPassengers.get(getDriverID()).size();

            String command = flight + pax.getCOS() + StartDate + OriginCity + DestinationCity + " " + "NN" + totalPax;
            gl.logCommand(logInfo, command);
            gl.sendCmdValidateResponse(command, "ETKT ELIGIBLE", logInfo);

            String response = isharesPageObjects2.SHARES_RESPONSE.getText();
            gl.checkForErrors(command,response,logInfo);


        } catch (AssertionError | Exception e) {
            ExtentReportListener.testStepHandle("FAIL", getDriver(), logInfo, e);
            Assert.fail("This step failed.. so stopping...");
        }
    }

    public void srchFlightAvailability(ExtentTest logInfo, String origin, String destination) {
        try {
//          A 20MAY PTYLAX
            Passenger pax = mPassengers.get(getDriverID()).get(0);

            String StartDate = gl.sharesFormatDateFromGUI(pax.getSegmentDate(0));

            String command = "A " + StartDate + " " + origin + destination;
            gl.logCommand(logInfo, command);
            gl.sendCmdValidateResponse(command, StartDate, logInfo);

            gl.checkForErrors(command,isharesPageObjects2.SHARES_RESPONSE.getText(),logInfo);


        } catch (AssertionError | Exception e) {
            ExtentReportListener.testStepHandle("FAIL", getDriver(), logInfo, e);
            Assert.fail("This step failed.. so stopping...");
        }
    }

    public void differentTypesOfFlightAvailabilitySearch(ExtentTest logInfo, String commandType, String segmentIndex) {
        String command ;

        try {
            //A 30APR HNLLAX
            //A 28JUN PTYLAX 800A
            //A LAXORD 28JUN 8A
            //A 28OCT ORD 800A
            //A HNL
            //A LAXHNL
            //A HNL A
            //A 28JUN LAX A
            //A TH PTY ORD
            //A PTY LAX TH

            String airline = mPassengers.get(getDriverID()).get(0).getAirline(0);
            String Origin = mPassengers.get(getDriverID()).get(0).getSegmentOriginCity(Integer.parseInt(segmentIndex));
            String Destination = mPassengers.get(getDriverID()).get(0).getSegmentDestinationCity(Integer.parseInt(segmentIndex));
            String departureDateFormatted = gl.sharesFormatDateFromGUI(mPassengers.get(getDriverID()).get(0).getSegmentDate(Integer.parseInt(segmentIndex)));

            if (airline.equalsIgnoreCase("800AWithSpace")) {
                command = "A " + departureDateFormatted + " " + Origin + Destination + " " + "800A";
            } else if (airline.equalsIgnoreCase("8A")) {
                command = "A " + Origin + Destination + " " + departureDateFormatted + "8A";
            } else if (airline.equalsIgnoreCase("800AWithoutSpace")) {
                command = "A " + departureDateFormatted + " " + Destination + "800A";
            } else if (airline.equalsIgnoreCase("A")) {
                command = "A " + departureDateFormatted + " " + Destination + " A";
            } else if (airline.equalsIgnoreCase("THBeforeMarket")) {
                command = "A " + " " + "TH" + " " + Origin + " " + Destination;
            } else if (airline.equalsIgnoreCase("THAfterMarket")) {
                command = "A " + " " + Origin + " " + Destination + " " + "TH";
            } else if (airline.equalsIgnoreCase("CMWithSpace")) {
                command = "A " + Origin;
            } else if (airline.equalsIgnoreCase("CMWithoutSpace")) {
                command = "A " + Origin + Destination;
            } else if (airline.equalsIgnoreCase("AWithSpace")) {
                command = "A " + Origin;
            } else if (airline.equalsIgnoreCase("FRAfterMarket")) {
                command = "A " + " " + Origin + " " + Destination + " " + "FR";
            } else if (airline.equalsIgnoreCase("AC")) {
                command = "AC " + " " + Origin;
            } else if (airline.equalsIgnoreCase("R")) {          //A 27JUL PTYLAX/R
                command = "A " + departureDateFormatted + " " + Origin + Destination + "/R";
            } else if (airline.equalsIgnoreCase("S")) {          //S LAXIAH 15DEC
                command = "S " + Origin + Destination + " " + departureDateFormatted;
            } else if (airline.equalsIgnoreCase("7A/R")) {          //A15DECPTYLHR7A/R
                command = "A" + departureDateFormatted + Origin + Destination + "7A/R";
            } else if (airline.equalsIgnoreCase("8AWithoutSpace")) {
                command = "A" + Origin + Destination + "" + departureDateFormatted + "8A";
            } else if (airline.equalsIgnoreCase("A_Origin_A")) {
                command = "A " + Origin + " A";
            } else if (airline.equalsIgnoreCase("MoreThan09Pax")) {
                command = "A " + Origin + Destination + " " + departureDateFormatted;
            } else if (airline.equalsIgnoreCase("DisplayFlight")) {
                command = "A " + mPassengers.get(getDriverID()).get(0).getSegmentFlight(0) + "/" +departureDateFormatted + " " + Origin + Destination;
            } else {
                command = "A " + departureDateFormatted + " " + Origin + Destination;
            }


            if (airline.equalsIgnoreCase("MoreThan09Pax")) {
                gl.logCommand(logInfo, command);
                gl.sendCmdValidateResponse(command, logInfo);

                gl.checkForErrors(command,isharesPageObjects2.SHARES_RESPONSE.getText(),logInfo);

                gl.logCommand(logInfo, "N11Y1");
                gl.sendCmdValidateResponse("N11Y1", "GREATER THAN 09", logInfo);

                gl.checkForErrors(command,isharesPageObjects2.SHARES_RESPONSE.getText(),logInfo);


            } else if (airline.equalsIgnoreCase("DisplayFlight")) {

                gl.logCommand(logInfo, command);
                gl.sendCmdValidateResponse(command, logInfo);

                gl.checkForErrors(command,isharesPageObjects2.SHARES_RESPONSE.getText(),logInfo);

                gl.logCommand(logInfo, "N8Y1");
                gl.sendCmdValidateResponse("N8Y1", "ETKT ELIGIBLE", logInfo);

                gl.checkForErrors(command,isharesPageObjects2.SHARES_RESPONSE.getText(),logInfo);

            } else {
                gl.logCommand(logInfo, command);
                gl.sendCmdValidateResponse(command, logInfo);

                if (!isharesPageObjects2.SHARES_RESPONSE.getText().contains("NO MORE FOR DISPLAY"))
                    gl.checkForErrors(command,isharesPageObjects2.SHARES_RESPONSE.getText(),logInfo);

            }

        } catch (AssertionError | Exception e) {

            ExtentReportListener.testStepHandle("FAIL", getDriver(), logInfo, e);
            Assert.fail("This step failed.. so stopping...");
        }
    }

    public void searchavailabilityInNativeShares(ExtentTest logInfo, String origin, String destination) {
        try {
            boolean flightFound=false;
            String COS = mPassengers.get(getDriverID()).get(0).getCOS();
            int totalpax = mPassengers.get(getDriverID()).size();
            String airline = mPassengers.get(getDriverID()).get(0).getAirline(0);
            int initialDepartureDate = mPassengers.get(getDriverID()).get(0).getSegmentDate(0); // Store the initial departure date

            int departureEndDate = initialDepartureDate + 5;

            String[] economyClass = {"Y", "H", "B", "M"};
            String[] businessClass = {"C", "D", "J", "R"};
            String[] destinationCities = {"MIA", "HAV", "MEX"};

            // Include primary destination first, then fallback destinations
            String[] allDestinations = new String[destinationCities.length + 1];
            allDestinations[0] = destination;
            System.arraycopy(destinationCities, 0, allDestinations, 1, destinationCities.length);

            if (COS.contains("Y") || COS.contains("B") || COS.contains("H") || COS.contains("M") ||
                    COS.contains("W") || COS.contains("K") || COS.contains("Q") ||
                    COS.contains("E") || COS.contains("F"))
            {

                Destinations:
                for (String currentDestination : allDestinations) // Iterate through destinations
                {
                    int departuredate = initialDepartureDate; // Reset departure date for each class and destination
                    DepartureDate:
                    while (departuredate <= departureEndDate) // Iterate through date range
                    {
                        displaySeatsAvailabilityForFlightsNativeShares(logInfo, origin, currentDestination, 0, departuredate);
                        Flight:
                        for (int j = 1; j <= flightIndex.get(getDriverID()).size(); j++)  // Loop for flights
                        {
                            ClassOfService:
                            for (String tcos : economyClass)  // Iterate through all classes in businessClass
                            {
                                COS = tcos;
                                String command;
                                command = "N" + totalpax + COS + flightIndex.get(getDriverID()).get(j - 1);  //N2Y1

                                logInfo.info( command);
                                sendCmdToNativeSharesValidateResponse(command);

                                String response = isharesPageObjects2.NATIVE_SHARES_RESPONSE_VALIDATE_LINE3.getText();
                                gl.checkForErrors(command, response, logInfo);
                                if ((!response.contains("SEGMENT LISTED"))&&(!response.contains("HL" + totalpax))) {
                                    if ((response.contains("ETKT ELIGIBLE") || response.contains("ADV PAX FLT ARRIVES TERMINAL") ||
                                            response.contains("SS" + totalpax) || response.contains("NN" + totalpax))) {
                                        logInfo.addScreenCaptureFromBase64String(getBase64(getDriver()), "Screenshot");

                                        //Extract Flight details
                                        Pattern pattern = Pattern.compile("\\b(\\d+)[A-Z]\\b");
                                        Matcher matcher = pattern.matcher(response);
                                        String flightNumber = "";
                                        if (matcher.find()) {
                                            flightNumber = matcher.group(1);  // Captures only the digits (e.g., "273")
                                            System.out.println(flightNumber);
                                        } else {
                                            System.out.println("No match found.");
                                        }
                                        // Assign flight details to passengers
                                        for (Passenger pax : mPassengers.get(getDriverID())) {
                                            pax.setSegmentFlight(0, flightNumber);
                                            pax.setSegmentDate(0, departuredate);
                                            pax.setAirline(0, airline);
                                            pax.setCOS(COS);
                                            pax.setSegmentDestinationCity(0, currentDestination);

                                            int len = response.split("\n")[0].split(" ").length;

                                            if (airline.equalsIgnoreCase("CM")) {
                                                pax.setSegmentDepartureTime(0, response.split("\n")[0].split(" ")[len - 3]);
                                                if (pax.getSegmentDepartureTime(0).isEmpty()) {
                                                    pax.setSegmentDepartureTime(0, response.split("\n")[0].split(" ")[len - 2]);
                                                }
                                                pax.setSegmentArrivalTime(0, response.split("\n")[0].split(" ")[len - 1]);
                                            } else {
                                                pax.setSegmentDepartureTime(0, response.split("\n")[0].split(" ")[len - 3]);
                                                pax.setSegmentArrivalTime(0, response.split("\n")[0].split(" ")[len - 1].split("/")[0]);
                                            }
                                        }

                                        flightFound = true;
                                        break Destinations; // Exit as soon as a flight is booked
                                    }
                                }
                                else
//                                    gl.clickElement(isharesPageObjects2.NATIVE_SHARES_CLEAR_ALL);
                                    displaySeatsAvailabilityForFlightsNativeShares(logInfo, origin, currentDestination, 0, departuredate);
                            }
                        }

                        // Move to the next day
                        departuredate++;

                        if (departuredate > departureEndDate) {
                            break; // Exit date loop if all days are checked
                        }

                    }// end of while
                }// end of Destinations for loop
            }
            else if (COS.contains("C") || COS.contains("J") || COS.contains("D") || COS.contains("R"))
            {

                Destinations:
                for (String currentDestination : allDestinations) // Iterate through destinations
                {
                    int departuredate = initialDepartureDate; // Reset departure date for each class and destination
                    DepartureDate:
                    while (departuredate <= departureEndDate) // Iterate through date range
                    {
                        displaySeatsAvailabilityForFlightsNativeShares(logInfo, origin, currentDestination, 0, departuredate);
                        Flight:
                        for (int j = 1; j <= flightIndex.get(getDriverID()).size(); j++)  // Loop for flights
                        {
                            ClassOfService:
                            for (String tcos : businessClass)  // Iterate through all classes in businessClass
                            {
                                COS = tcos;
                                String command;
                                command = "N" + totalpax + COS + flightIndex.get(getDriverID()).get(j - 1);  //N2Y1

                                logInfo.info( command);
                                sendCmdToNativeSharesValidateResponse(command);

                                String response = isharesPageObjects2.NATIVE_SHARES_RESPONSE_VALIDATE_LINE3.getText();
                                gl.checkForErrors(command, response, logInfo);
                                if((!response.contains("SEGMENT LISTED"))&&(!response.contains("HL" + totalpax))) {
                                    if ((response.contains("ETKT ELIGIBLE") || response.contains("ADV PAX FLT ARRIVES TERMINAL") ||
                                            response.contains("SS" + totalpax) || response.contains("NN" + totalpax))) {
                                        logInfo.addScreenCaptureFromBase64String(getBase64(getDriver()), "Screenshot");

                                        //Extract Flight details
                                        Pattern pattern = Pattern.compile("\\b(\\d+)[A-Z]\\b");
                                        Matcher matcher = pattern.matcher(response);
                                        String flightNumber = "";
                                        if (matcher.find()) {
                                            flightNumber = matcher.group(1);  // Captures only the digits (e.g., "273")
                                            System.out.println(flightNumber);
                                        } else {
                                            System.out.println("No match found.");
                                        }
                                        // Assign flight details to passengers
                                        for (Passenger pax : mPassengers.get(getDriverID())) {
                                            pax.setSegmentFlight(0, flightNumber);
                                            pax.setSegmentDate(0, departuredate);
                                            pax.setAirline(0, airline);
                                            pax.setCOS(COS);
                                            pax.setSegmentDestinationCity(0, currentDestination);

                                            int len = response.split("\n")[0].split(" ").length;

                                            if (airline.equalsIgnoreCase("CM")) {
                                                pax.setSegmentDepartureTime(0, response.split("\n")[0].split(" ")[len - 3]);
                                                if (pax.getSegmentDepartureTime(0).isEmpty()) {
                                                    pax.setSegmentDepartureTime(0, response.split("\n")[0].split(" ")[len - 2]);
                                                }
                                                pax.setSegmentArrivalTime(0, response.split("\n")[0].split(" ")[len - 1]);
                                            } else {
                                                pax.setSegmentDepartureTime(0, response.split("\n")[0].split(" ")[len - 3]);
                                                pax.setSegmentArrivalTime(0, response.split("\n")[0].split(" ")[len - 1].split("/")[0]);
                                            }

                                        }

                                        flightFound = true;
                                        break Destinations; // Exit as soon as a flight is booked
                                    }
                                }
                                else
                                    displaySeatsAvailabilityForFlightsNativeShares(logInfo, origin, currentDestination, 0, departuredate);
                            }
                        }
                        // Move to the next day
                        departuredate++;

                        if (departuredate > departureEndDate) {
                            break; // Exit date loop if all days are checked
                        }

                    }// end of while
                }// end of Destinations for loop
            }

            if(!flightFound)
            {
                logInfo.info(MarkupHelper.createLabel("No seats available for any destination within the specified range.", ExtentColor.RED));
                mFailureDescription.put(getDriverID(),"No seats available for any destination within the specified range.");
                Assert.fail();
            }

        } catch (AssertionError | Exception e) {

            ExtentReportListener.testStepHandle("FAIL", getDriver(), logInfo, e);
            Assert.fail("This step failed.. so stopping...");
        }
    }

    public Map<String,List<String>> enterVIXtoGetWaitlistFlightsAndClasses(ExtentTest logInfo,int days)
    {
        Map<String,List<String>> flightIndexAndClasses = new HashMap<>();
        try
        {
            for (int j = 0; j <flightIndex.get(getDriverID()).size(); j++)
            {
                String[] temp = flightIndex.get(getDriverID()).get(j).split("#");
                String index = temp[0];
                String flightNumber = temp[1];

                String command = "VIX"+flightNumber+"/"+ gl.plusDaysFromTodayForVIXCommand(days);
                gl.logCommand(logInfo,command);
                gl.sendCmdValidateResponse(command,"SEATS AVAILABLE MATRIX", logInfo);

                String response = isharesPageObjects2.SHARES_RESPONSE.getText();
                String[] responseAsRows =response.split("\n");

                String waitListRegex = "([A-Z])"+"  "+"(?:-|0)(\\d{2})WL";
                Pattern waitListPattern = Pattern.compile(waitListRegex);
                boolean hasWaitlistSeats=false;
                List<String> COS = new ArrayList<>();

                for(String rows: responseAsRows)
                {
                    Matcher matcher = waitListPattern.matcher(rows);
                    if(matcher.find())
                    {
                        hasWaitlistSeats=true;
                        matcher = waitListPattern.matcher(rows);
                        while(matcher.find())
                        {
                            COS.add(matcher.group(1));
                        }
                    }
                }

                if(hasWaitlistSeats)
                    flightIndexAndClasses.put(index,COS);

            }
        }
        catch (AssertionError | Exception e) {
            ExtentReportListener.testStepHandle("FAIL", getDriver(), logInfo, e);
            Assert.fail("This step failed.. so stopping...");
        }

        return flightIndexAndClasses;
    }

