    public List<String> getReorderedPaxList_CorporatePNR(ExtentTest logInfo, String response) {
        List<String> Names = new ArrayList<>();
        List<String> UpdatedNames = new ArrayList<>(); //UpdatedNames is containing the changed order of pax
        Map<String, String> paxIndexes = new HashMap<>();

        try {
            String[] rawResponse = response.split("\n");

            for (int i = 3; i < rawResponse.length; i++)//Loop to extract Raw Unedited Names from application
            {
                if (!rawResponse[i].contains("/") || rawResponse[i].contains("FONE")) {
                    break;
                }
                String[] temp = rawResponse[i].split(" ");
                for (int j = 1; j < temp.length; j++) {
                    if (temp[j].contains("INS") && !temp[j].contains(".C") && temp[j].contains("*")) {
                        temp[j] = temp[j].substring(1, temp[j].indexOf("*"));
                        Names.add(temp[j]);
                        paxIndexes.put(temp[j], temp[j - 1].replace(".", ""));
                    } else if (temp[j].contains("INF") && !temp[j].contains(".C")&& temp[j].contains("*")) {
                        String x = temp[j].substring(temp[j].indexOf("-"));
                        temp[j] = x.split("/")[0];
                        Names.add(temp[j]);
                        paxIndexes.put(temp[j], temp[j - 1].replace(".", ""));
                    } else if (temp[j].contains("CHD") && !temp[j].contains(".C")&& temp[j].contains("*")) {
                        temp[j] = temp[j].substring(1, temp[j].indexOf("*"));
                        Names.add(temp[j]);
                        paxIndexes.put(temp[j], temp[j - 1].replace(".", ""));
                    } else if (temp[j].contains("/") && !temp[j].contains("/UA") && !temp[j].contains(".C")) {
                        temp[j] = temp[j].substring(1);
                        Names.add(temp[j]);
                        paxIndexes.put(temp[j], temp[j - 1].replace(".", ""));
                    }
                }
            }

            System.out.println("Raw Names Taken from iShares application : " + Names);
            System.out.println("Indexes of the Names stored : " + paxIndexes);

//            Storing all the first Names in sequential order according to application
            for (int i = 0; i < Names.size(); i++) {
                if (Names.get(i).contains("INF")) //For Infant Pax
                {
                    UpdatedNames.add(Names.get(i).replace("INF", "").trim().replace("-", ""));
                    addIndexToPax(Names.get(i).replace("INF", "").trim().replace("-", ""), paxIndexes.get(Names.get(i)));
                } else //For Other Normal Pax like ADT,CHD,INS
                {
                    UpdatedNames.add(Names.get(i).split("/")[0].replace("1", ""));
                    addIndexToPax(Names.get(i).split("/")[0].replace("1", ""), paxIndexes.get(Names.get(i)));

                }
            }
        } catch (AssertionError | Exception e) {
            ExtentReportListener.testStepHandle("FAIL", getDriver(), logInfo, e);
            Assert.fail("This step failed.. so stopping...");
        }

        return UpdatedNames;
    }

    public List<String> getReorderedPaxList_JumpSeatPaxPNR(ExtentTest logInfo, String response) {
        List<String> Names = new ArrayList<>();
        List<String> UpdatedNames = new ArrayList<>(); //UpdatedNames is containing the changed order of pax
        Map<String, String> paxIndexes = new HashMap<>();

        try {
            String[] rawResponse = response.split("\n");

            for (int i = 3; i < rawResponse.length; i++)//Loop to extract Raw Unedited Names from application
            {
                if (!rawResponse[i].contains("/") || rawResponse[i].contains("FONE")) {
                    break;
                }
                String[] temp = rawResponse[i].split(" ");
                for (int j = 1; j < temp.length; j++) {
                    if (temp[j].contains("/") && !temp[j].contains("/UA") && temp[j].contains(".W")) {
                        String name = "";
                        for (int k = 1; k < temp[j].split("/").length; k++) {
                            name = name + "/" + temp[j].split("/")[k];
                        }
                        Names.add(name.substring(1));
                        paxIndexes.put(name.substring(1), temp[j].substring(0, 1));
                    }
                }
            }

            System.out.println("Raw Names Taken from iShares application : " + Names);
            System.out.println("Indexes of the Names stored : " + paxIndexes);

//            Storing all the first Names in sequential order according to application
            for (int i = 0; i < Names.size(); i++) {
                UpdatedNames.add(Names.get(i).split("/")[0].replace("1", ""));
                addIndexToPax(Names.get(i).split("/")[0].replace("1", ""), paxIndexes.get(Names.get(i)));
            }

        } catch (AssertionError | Exception e) {
            ExtentReportListener.testStepHandle("FAIL", getDriver(), logInfo, e);
            Assert.fail("This step failed.. so stopping...");
        }

        return UpdatedNames;
    }

