    public void addIndexToPax(String name, String index) {
        int paxIndex = Integer.parseInt(index);
        for (Passenger pax : mPassengers.get(getDriverID())) {
            if (pax.getfName().equalsIgnoreCase(name) || pax.getlName().equalsIgnoreCase(name)) {
                pax.setIndexOfPax(paxIndex);
                break;
            }
        }
    }

    public void enter_ER(ExtentTest logInfo) {
        try {

            gl.logCommand(logInfo, "ER");
            gl.sendCmdValidateResponse("ER", logInfo);

            String response = isharesPageObjects2.SHARES_RESPONSE.getText();

            if (response.contains("RCVD")) {

                List<String> UpdatedNames; //UpdatedNames is containing the changed order of pax

                if (mPassengers.get(getDriverID()).get(0).getIsGroupPNR() && mPassengers.get(getDriverID()).get(0).getIsSameSurname())
                    UpdatedNames = getReorderedPaxList_GroupPNR_SameSurnamePNR(logInfo, response);
                else if (mPassengers.get(getDriverID()).get(0).getIsCorporatePNR() && mPassengers.get(getDriverID()).get(0).getIsSameSurname())
                    UpdatedNames = getReorderedPaxList_CorporatePNR_SameSurnamePNR(logInfo, response);
                else if (mPassengers.get(getDriverID()).get(0).getIsGroupPNR())
                    UpdatedNames = getReorderedPaxList_GroupPNR(logInfo, response);
                else if (mPassengers.get(getDriverID()).get(0).getIsSameSurname())
                    UpdatedNames = getReorderedPaxList_SameSurnamePNR(logInfo, response);
                else if (mPassengers.get(getDriverID()).get(0).getIsNRPS() || mPassengers.get(getDriverID()).get(0).getIsNRSA())
                    UpdatedNames = getReorderedPaxList_NRPS_NRSA_PNR(logInfo, response);
                else if (mPassengers.get(getDriverID()).get(mPassengers.get(getDriverID()).size() - 1).getIsFQTV())
                    UpdatedNames = getReorderedPaxList_FQTVPNR(logInfo, response);
                else if (mPassengers.get(getDriverID()).get(0).getIsCorporatePNR())
                    UpdatedNames = getReorderedPaxList_CorporatePNR(logInfo, response);
                else if (mPassengers.get(getDriverID()).get(0).getIsJumpSeatPax())
                    UpdatedNames = getReorderedPaxList_JumpSeatPaxPNR(logInfo, response);
                else if (mPassengers.get(getDriverID()).get(0).getIsSameSurnameCorporatePNR())
                    UpdatedNames = getReorderedPaxList_SameSurnameCorporatePNR(logInfo, response);
                else if (mPassengers.get(getDriverID()).get(0).getIsSameSurnameGroupPNR())
                    UpdatedNames = getReorderedPaxList_SameSurnameGroupPNR(logInfo, response);
                else
                    UpdatedNames = getReorderedPaxList_NormalPNR(logInfo, response);

                for (Passenger pax : mPassengers.get(getDriverID())) {
                    System.out.println("LNAME/FNAME : " + pax.getFullName() + " --> INDEX: " + pax.getIndexOfPax());
                }

                Assert.assertTrue(response.contains("RCVD"));

                String PNR = response.substring(0, 6);
                sortPassengerList(UpdatedNames, PNR, logInfo);

            }
        } catch (AssertionError | Exception e) {
            ExtentReportListener.testStepHandle("FAIL", getDriver(), logInfo, e);
            Assert.fail("This step failed.. so stopping...");
        }

    }

    public void searchFlightAvailabilityForSpecialPNRDifferentFlight(ExtentTest logInfo, String Origin, String Destination) {
        int endFlt = 3;

        try {
            Passenger pax = mPassengers.get(getDriverID()).get(0);
            String COS = mPassengers.get(getDriverID()).get(0).getCOS();
            int totalpax = mPassengers.get(getDriverID()).size();
            String airline = mPassengers.get(getDriverID()).get(0).getAirline(0);
            int departuredate = mPassengers.get(getDriverID()).get(0).getSegmentDate(0);  //Getting the departure Date based on feature file input
            String flight = pax.getSegmentFlight(0);

            displaySeatsAvailabilityForFlights(logInfo, Origin, Destination, 1, departuredate);  //Passing 0 for 1st Segment

            for (int j = 1; j <= flightIndex.get(getDriverID()).size(); j++) { // Loop for flights

                String command = null;
                Passenger passenger = mPassengers.get(getDriverID()).get(0);

                if (passenger.getpnrType().equalsIgnoreCase("Group")) {
                    command = "N" + totalpax + COS + flightIndex.get(getDriverID()).get(j - 1) + "GNN"; //N2Y1
                } else if (passenger.getpnrType().equalsIgnoreCase("NRSA")) {
                    command = "N" + totalpax + COS + flightIndex.get(getDriverID()).get(j - 1) + "MM";
                } else if (passenger.getpnrType().equalsIgnoreCase("WaitList")) {
                    command = "N" + totalpax + COS + flightIndex.get(getDriverID()).get(j - 1) + "PD";
                } else if (passenger.getpnrType().equalsIgnoreCase("NRPS")) {
                    command = "N" + totalpax + COS + flightIndex.get(getDriverID()).get(j - 1) + "PNN";
                }

                gl.logCommand(logInfo, command);
                gl.sendCmdValidateResponse(command, logInfo);

                String response = isharesPageObjects2.SHARES_RESPONSE.getText();
                gl.checkForErrors(command,response,logInfo);

                if (response.contains("ETKT ELIGIBLE") || response.contains("UNITED AIRLINES") ||
                        response.contains("ADV PAX FLT ARRIVES TERMINAL") || response.contains("SS" + mPassengers.get(getDriverID()).size())) {

                    if (!flight.equalsIgnoreCase(response.substring(6, 10))) {
                        for (Passenger pax1 : mPassengers.get(getDriverID())) {
                            pax1.setSegmentFlight(1, response.substring(6, 10).trim());
                            pax1.setSegmentDate(1, departuredate);
                            pax1.setAirline(1, airline);
                            pax1.setCOS(COS);
                        }

                        int len = response.split("\n")[0].split(" ").length;

                        if (airline.equalsIgnoreCase("CM")) {
                            pax.setSegmentDepartureTime(0, response.split("\n")[0].split(" ")[len - 3]);
                            pax.setSegmentArrivalTime(0, response.split("\n")[0].split(" ")[len - 1]);
                        } else {
                            pax.setSegmentDepartureTime(0, response.split("\n")[0].split(" ")[len - 3]);
                            pax.setSegmentArrivalTime(0, response.split("\n")[0].split(" ")[len - 1].split("/")[0]);
                        }

                        break;
                    }
                }else if (j == endFlt)  //This is for the case when on a single day no more flights are to check
                {
                    j = 1;

                    if (departuredate <= departuredate + 5)
                        departuredate++;
                    else
                        break;

                }
                displaySeatsAvailabilityForFlights(logInfo, Origin, Destination, 0, departuredate);
            }
        } catch (AssertionError | Exception e) {

            ExtentReportListener.testStepHandle("FAIL", getDriver(), logInfo, e);
            Assert.fail("This step failed.. so stopping...");
        }
    }

    public void sortPassengerList(List<String> UpdatedNames, String PNR, ExtentTest logInfo) {
//        NOTE: When we use add(index, value) of arraylist it doesn't replace, but instead it shifts the values back and inserts in that ith place the new value
        ArrayList<Passenger> pax = mPassengers.get(getDriverID());

        ArrayList<Passenger> shuffledList = new ArrayList<>();

        for (int i = 0; i < UpdatedNames.size(); i++) {
            String name = UpdatedNames.get(i);

            for (int j = 0; j < pax.size(); j++) {
                String PaxLName = pax.get(j).getlName();
                String PaxFName = pax.get(j).getfName();

                if (name.equalsIgnoreCase(PaxFName) || name.equalsIgnoreCase(PaxLName)) {
                    shuffledList.add(pax.get(j));
                    break;
                }

            }
        }

//        NOTE: If we are storing the same arraylist in 2 different HashMaps, if we call that arraylist using one hashmap and change the values, then the other hashmaps arraylist will also be changed, because we are storing the same arraylist, so both the hashmaps are referring to same arraylist
        mPassengers.put(getDriverID(), shuffledList);

        System.out.println("The Shuffled Passenger List(FNAME/LNAME) is : ");

        for (int i = 0; i < mPassengers.get(getDriverID()).size(); i++) {
            System.out.println(mPassengers.get(getDriverID()).get(i).getFullName());
            logInfo.pass((i + 1) + ": " + mPassengers.get(getDriverID()).get(i).getPaxType() + "-> " + mPassengers.get(getDriverID()).get(i).getFullName());

            mPassengers.get(getDriverID()).get(i).setPnr(PNR); //Setting PNR for each pax

        }
    }

