    public String returnSequenceNumber(ExtentTest logInfo, String response) {
        String sequenceNumber = null;
        try {
            String[] rows = response.split("\n");

            for (int i = 0; i < rows.length; i++) {
                if (rows[i].contains("SEQ NBR")) {
                    String[] text = rows[i].split(" ");
                    if (text.length == 6)
                        sequenceNumber = text[5];
                    else
                        sequenceNumber = text[4];
                    break;
                }
            }
            System.out.println("Sequence Number: " + sequenceNumber);

        } catch (AssertionError | Exception e) {
            ExtentReportListener.testStepHandle("FAIL", getDriver(), logInfo, e);
            Assert.fail("This step failed.. so stopping...");
        }
        return sequenceNumber;
    }

