    public void checkinOfGoShowPNRAgainAndValidateTheError(ExtentTest logInfo)
    {
        try {
            gl.waitForProfileLoad();
            Passenger pax = mPassengers.get(getDriverID()).get(0);
            String origin = pax.getSegmentOriginCity(0);
            String response = mText.get(getDriverID());
            String PNR = null;

            for(int i = 0; i < response.split("\n").length; i++){
                if(response.split("\n")[i].contains(pax.getfName())){
                    String temp[] = response.split("\n")[i].split(" ");
                    int index = response.split("\n")[i].indexOf(pax.getSegmentDestinationCity(0));
                    PNR = response.split("\n")[i].substring(index + 3, index + 10).trim();
                    System.out.println("PNR: " + PNR);
                    break;
                }
            }

            gl.logCommand(logInfo, "*" + PNR);
            gl.sendCmdValidateResponse("*" + PNR, "GO SHOW PNR", logInfo);

            gl.ignoreTRNS(logInfo);

            isharesPageObjects2.FORMSIZE_DROPDOWN.click();
            isharesPageObjects2.FORMSIZE_SELECT24.click();
            //        6:NM243/06MARPTY-2RYAN/MRA/MRS.F/BOG
            //        B0
            String cmd = null;
            if (pax.getPaxType().equalsIgnoreCase("ADT"))
            {
                cmd = "6:NM" + mPassengers.get(getDriverID()).get(0).getSegmentFlight(0)
                        + "/" + gl.sharesFormatDateFromGUI(mPassengers.get(getDriverID()).get(0).getSegmentDate(0))
                        + origin + "-" + pax.getfName()
                        + "/" + pax.getlName() + "." + pax.getCOS() + "/" + pax.getSegmentDestinationCity(0)
                        + "\n" + "B0";
            }
            gl.logCommand(logInfo, cmd);
            System.out.println(cmd);
            gl.copyCmdToClipboardAndPaste(cmd, isharesPageObjects2.FORMSIZE_SELECT2_TEXTAREA);
            logInfo.addScreenCaptureFromBase64String(getBase64(getDriver()), "Screenshot");

            isharesPageObjects2.SEND_ISHARES.click();
            gl.waitForProfileLoad();
            logInfo.addScreenCaptureFromBase64String(getBase64(getDriver()), "Screenshot");

            response = isharesPageObjects2.SHARES_RESPONSE.getText();
            Assert.assertTrue(response.contains("GOSHOW RESTRICTED, PNR EXISTS- RECLOC"));

        } catch (AssertionError | Exception e) {
            ExtentReportListener.testStepHandle("FAIL", getDriver(), logInfo, e);
            Assert.fail("This step failed.. so stopping...");
        }
    }

