    public String add_SecondaryADC_SpecificOrigin(String IncompleteADCInfo) {   //for origin cities like SFO
        String[] S1 = IncompleteADCInfo.split("\n");
        String baseCommand = S1[0] + "\n" + S1[1] + "\n" + S1[2];

        String docType = "P" + generateBlankSpace(1) + "* DOCUMENT TYPE";
        String docNumber = "234567" + generateBlankSpace(6) + "* DOCUMENT NUMBER";
        String countryIssuance = "USA" + generateBlankSpace(3) + "* COUNTRY OF ISSUANCE";
        String expDate = "280210" + generateBlankSpace(6) + "* EXPIRATION DATE";  //YYMMDD

        String ADCinfo = baseCommand;
        ADCinfo = ADCinfo + (IncompleteADCInfo.contains("DOCUMENT TYPE") ? ("\n" + docType) : "");
        ADCinfo = ADCinfo + (IncompleteADCInfo.contains("DOCUMENT NUMBER") ? ("\n" + docNumber) : "");
        ADCinfo = ADCinfo + (IncompleteADCInfo.contains("COUNTRY OF ISSUANCE") ? ("\n" + countryIssuance) : "");
        ADCinfo = ADCinfo + (IncompleteADCInfo.contains("EXPIRATION DATE") ? ("\n" + expDate) : "");
        ADCinfo = ADCinfo + (IncompleteADCInfo.contains("SCR") ? ("\n" + "SCR:") : "");
        ADCinfo = ADCinfo + (IncompleteADCInfo.contains("DOCTYPE:") ? ("\n" + "DOCTYPE: A-ALIEN CARD C-PERM RES CARD B-BORDER CARD") : "");
        ADCinfo = ADCinfo + (IncompleteADCInfo.contains("DOCTYPE:") ? ("\n" + "N-NATZTION CERT M-MILITARY ID T-REFUGE REENTY P-PASSPORT") : "");

        return ADCinfo;
    }

    public String reformSecondaryADC_SpecificOrigin() { //for origin cities like SFO
        String MissingADCInfo;
        String baseCommand;
        String[] S1;

        if (globalConstants.testEnv.equalsIgnoreCase("sharesCURL")) {
            MissingADCInfo = isharesPageObjects2.SHARES_RESPONSE.getText();
            S1 = MissingADCInfo.split("\n");
            baseCommand = S1[1].substring(1) + "\n" + S1[2] + "\n" + S1[3];
        } else {
            MissingADCInfo = isharesPageObjects2.INPUT_TEXT_AREA_ROWS24.getText();
            S1 = MissingADCInfo.split("\n");
            baseCommand = S1[0] + "\n" + S1[1] + "\n" + S1[2];
        }
        String docType = "P" + generateBlankSpace(1) + "* DOCUMENT TYPE";
        String docNumber = "234567" + generateBlankSpace(6) + "* DOCUMENT NUMBER";
        String countryIssuance = "USA" + generateBlankSpace(3) + "* COUNTRY OF ISSUANCE";
        String expDate = "280210" + generateBlankSpace(6) + "* EXPIRATION DATE";  //YYMMDD

//        ******** BACKUP SET *********
        String docType1 = "P" + generateBlankSpace(1) + "* DOCUMENT TYPE";
        String docNumber1 = "237856" + generateBlankSpace(6) + "* DOCUMENT NUMBER";
        String countryIssuance1 = "MX" + generateBlankSpace(2) + "* COUNTRY OF ISSUANCE";
        String expDate1 = "250210" + generateBlankSpace(6) + "* EXPIRATION DATE";  //YYMMDD

        docType = (S1[3].contains("?") ? docType1 : docType);
        docNumber = (S1[4].contains("?") ? docNumber1 : docNumber);
        countryIssuance = (S1[5].contains("?") ? countryIssuance1 : countryIssuance);
        expDate = (S1[6].contains("?") || S1[10].contains("YYMMDD") ? expDate1 : expDate);

        String ADCinfo = baseCommand;
        ADCinfo = ADCinfo + (MissingADCInfo.contains("DOCUMENT TYPE") ? ("\n" + docType) : "");
        ADCinfo = ADCinfo + (MissingADCInfo.contains("DOCUMENT NUMBER") ? ("\n" + docNumber) : "");
        ADCinfo = ADCinfo + (MissingADCInfo.contains("COUNTRY OF ISSUANCE") ? ("\n" + countryIssuance) : "");
        ADCinfo = ADCinfo + (MissingADCInfo.contains("EXPIRATION DATE") ? ("\n" + expDate) : "");
        ADCinfo = ADCinfo + (MissingADCInfo.contains("SCR") ? ("\n" + "SCR:") : "");
        ADCinfo = ADCinfo + (MissingADCInfo.contains("DOCTYPE:") ? ("\n" + "DOCTYPE: A-ALIEN CARD C-PERM RES CARD B-BORDER CARD") : "");
        ADCinfo = ADCinfo + (MissingADCInfo.contains("DOCTYPE:") ? ("\n" + "N-NATZTION CERT M-MILITARY ID T-REFUGE REENTY P-PASSPORT") : "");
        return ADCinfo;

    }


