    public void searchFlightAvailabilityForSpecialPNRForFifthSeg(ExtentTest logInfo, String Origin, String Destination) {

        String COS = mPassengers.get(getDriverID()).get(0).getCOS();
        int totalpax = mPassengers.get(getDriverID()).size();
        String airline = mPassengers.get(getDriverID()).get(0).getAirline(4);
        int initialDepartureDate = mPassengers.get(getDriverID()).get(0).getSegmentDate(4);  //Getting the departure Date based on feature file input
        int lastSegmentDate = mPassengers.get(getDriverID()).get(0).getSegmentDate(3);

        while (initialDepartureDate <= lastSegmentDate) {
            initialDepartureDate++;
        }

        int departureEndDate = initialDepartureDate + 5;

        String[] economyClass = {"B", "H", "Y", "M"};
        String[] businessClass = {"C", "D", "J", "R"};
        String[] destinationCities = {"MIA", "HAV", "MEX"};

        // Include primary destination first, then fallback destinations
        String[] allDestinations = new String[destinationCities.length + 1];
        allDestinations[0] = Destination;
        System.arraycopy(destinationCities, 0, allDestinations, 1, destinationCities.length);

        if (COS.contains("Y") || COS.contains("B") || COS.contains("H") || COS.contains("M") || COS.contains("W") || COS.contains("K") || COS.contains("Q")) {

            Destinations:
            for (String currentDestination : allDestinations) // Iterate through destinations
            {
                int departuredate = initialDepartureDate; // Reset departure date for each class and destination
                DepartureDate:
                while (departuredate <= departureEndDate) // Iterate through date range
                {
                    displaySeatsAvailabilityForFlights(logInfo, Origin, currentDestination, 3, departuredate);
                    Flight:
                    for (int j = 1; j <= flightIndex.get(getDriverID()).size(); j++)  // Loop for flights
                    {
                        ClassOfService:
                        for (String tcos : economyClass)  // Iterate through all classes in businessClass
                        {
                            if (!mPassengers.get(getDriverID()).get(0).getpnrType().contains("Waitlist")) {
                                COS = tcos;
                            }

                            String command = null;
                            Passenger passenger = mPassengers.get(getDriverID()).get(0);
                            if (passenger.getpnrType().equalsIgnoreCase("Group")) {
                                command = "N" + totalpax + COS + flightIndex.get(getDriverID()).get(j - 1) + "GNN"; //N2Y1
                            } else if (passenger.getpnrType().equalsIgnoreCase("NRSA")) {
                                command = "N" + totalpax + COS + flightIndex.get(getDriverID()).get(j - 1) + "MM";
                            } else if (passenger.getpnrType().equalsIgnoreCase("WaitList")) {
                                command = "N" + totalpax + COS + flightIndex.get(getDriverID()).get(j - 1) + "PD";
                            } else if (passenger.getpnrType().equalsIgnoreCase("NRPS")) {
                                command = "N" + totalpax + COS + flightIndex.get(getDriverID()).get(j - 1) + "PNN";
                            } else if (passenger.getpnrType().equalsIgnoreCase("WaitList-C")) {
                                command = "N" + totalpax + COS + flightIndex.get(getDriverID()).get(j - 1) + "PC";
                            } else if (passenger.getpnrType().equalsIgnoreCase("WaitList-A")) {
                                command = "N" + totalpax + COS + flightIndex.get(getDriverID()).get(j - 1) + "PA";
                            } else if (passenger.getpnrType().equalsIgnoreCase("WaitList-B")) {
                                command = "N" + totalpax + COS + flightIndex.get(getDriverID()).get(j - 1) + "PB";
                            }else if (passenger.getpnrType().equalsIgnoreCase("Corporate")) {
                                command = "N" + totalpax + COS + flightIndex.get(getDriverID()).get(j - 1) + "GNN";
                            }else if (passenger.getpnrType().equalsIgnoreCase("PartialPNR")) {
                                command = "N" + totalpax + COS + flightIndex.get(getDriverID()).get(j - 1) + "QF";
                            }else if (passenger.getpnrType().equalsIgnoreCase("IGPA")) {
                                command = "N" + totalpax + COS + flightIndex.get(getDriverID()).get(j - 1) + "IGPA";
                            }

                            gl.logCommand(logInfo, command);
                            gl.sendCmdValidateResponse(command, logInfo);

                            String response = isharesPageObjects2.SHARES_RESPONSE.getText();
                            gl.checkForErrors(command,response,logInfo);

                            if (response.contains("ETKT ELIGIBLE") || response.contains("ADV PAX FLT ARRIVES TERMINAL") ||
                                    response.contains("SS" + totalpax) || response.contains("NN" + totalpax)) {

                                // Assign flight details to passengers
                                for (Passenger pax : mPassengers.get(getDriverID())) {
                                    pax.setSegmentFlight(4, response.substring(6, 10).trim());
                                    pax.setSegmentDate(4, departuredate);
                                    pax.setAirline(4, airline);
                                    pax.setCOS(COS);
                                    pax.setSegmentDestinationCity(4,currentDestination);

                                    int len = response.split("\n")[0].split(" ").length;

                                    if (airline.equalsIgnoreCase("CM")) {
                                        pax.setSegmentDepartureTime(4, response.split("\n")[0].split(" ")[len - 3]);
                                        if (pax.getSegmentDepartureTime(4).isEmpty()) {
                                            pax.setSegmentDepartureTime(4, response.split("\n")[0].split(" ")[len - 2]);
                                        }
                                        pax.setSegmentArrivalTime(4, response.split("\n")[0].split(" ")[len - 1]);
                                    } else {
                                        pax.setSegmentDepartureTime(4, response.split("\n")[0].split(" ")[len - 3]);
                                        pax.setSegmentArrivalTime(4, response.split("\n")[0].split(" ")[len - 1].split("/")[0]);
                                    }

                                }

                                break Destinations; // Exit as soon as a flight is booked
                            }
                            else
                                displaySeatsAvailabilityForFlights(logInfo, Origin, currentDestination, 4, departuredate);
                        }
                    }

                    // Move to the next day
                    departuredate++;

                    if (departuredate > departureEndDate) {
                        break; // Exit date loop if all days are checked
                    }

                }// end of while
            }// end of Destinations for loop

        } else if (COS.contains("C") || COS.contains("J") || COS.contains("R") || COS.contains("D")) {

            Destinations:
            for (String currentDestination : allDestinations) // Iterate through destinations
            {
                int departuredate = initialDepartureDate; // Reset departure date for each class and destination
                DepartureDate:
                while (departuredate <= departureEndDate) // Iterate through date range
                {
                    displaySeatsAvailabilityForFlights(logInfo, Origin, currentDestination, 4, departuredate);
                    Flight:
                    for (int j = 1; j <= flightIndex.get(getDriverID()).size(); j++)  // Loop for flights
                    {
                        ClassOfService:
                        for (String tcos : businessClass)  // Iterate through all classes in businessClass
                        {
                            if (!mPassengers.get(getDriverID()).get(0).getpnrType().contains("Waitlist")) {
                                COS = tcos;
                            }

                            String command = null;
                            Passenger passenger = mPassengers.get(getDriverID()).get(0);
                            if (passenger.getpnrType().equalsIgnoreCase("Group")) {
                                command = "N" + totalpax + COS + flightIndex.get(getDriverID()).get(j - 1) + "GNN"; //N2Y1
                            } else if (passenger.getpnrType().equalsIgnoreCase("NRSA")) {
                                command = "N" + totalpax + COS + flightIndex.get(getDriverID()).get(j - 1) + "MM";
                            } else if (passenger.getpnrType().equalsIgnoreCase("WaitList")) {
                                command = "N" + totalpax + COS + flightIndex.get(getDriverID()).get(j - 1) + "PD";
                            } else if (passenger.getpnrType().equalsIgnoreCase("NRPS")) {
                                command = "N" + totalpax + COS + flightIndex.get(getDriverID()).get(j - 1) + "PNN";
                            } else if (passenger.getpnrType().equalsIgnoreCase("WaitList-C")) {
                                command = "N" + totalpax + COS + flightIndex.get(getDriverID()).get(j - 1) + "PC";
                            } else if (passenger.getpnrType().equalsIgnoreCase("WaitList-A")) {
                                command = "N" + totalpax + COS + flightIndex.get(getDriverID()).get(j - 1) + "PA";
                            } else if (passenger.getpnrType().equalsIgnoreCase("WaitList-B")) {
                                command = "N" + totalpax + COS + flightIndex.get(getDriverID()).get(j - 1) + "PB";
                            }else if (passenger.getpnrType().equalsIgnoreCase("Corporate")) {
                                command = "N" + totalpax + COS + flightIndex.get(getDriverID()).get(j - 1) + "GNN";
                            }else if (passenger.getpnrType().equalsIgnoreCase("PartialPNR")) {
                                command = "N" + totalpax + COS + flightIndex.get(getDriverID()).get(j - 1) + "QF";
                            }else if (passenger.getpnrType().equalsIgnoreCase("IGPA")) {
                                command = "N" + totalpax + COS + flightIndex.get(getDriverID()).get(j - 1) + "IGPA";
                            }

                            gl.logCommand(logInfo, command);
                            gl.sendCmdValidateResponse(command, logInfo);

                            String response = isharesPageObjects2.SHARES_RESPONSE.getText();
                            gl.checkForErrors(command,response,logInfo);

                            if (response.contains("ETKT ELIGIBLE") || response.contains("ADV PAX FLT ARRIVES TERMINAL") ||
                                    response.contains("SS" + totalpax) || response.contains("NN" + totalpax)) {

                                // Assign flight details to passengers
                                for (Passenger pax : mPassengers.get(getDriverID())) {
                                    pax.setSegmentFlight(4, response.substring(6, 10).trim());
                                    pax.setSegmentDate(4, departuredate);
                                    pax.setAirline(4, airline);
                                    pax.setCOS(COS);
                                    pax.setSegmentDestinationCity(4,currentDestination);

                                    int len = response.split("\n")[0].split(" ").length;

                                    if (airline.equalsIgnoreCase("CM")) {
                                        pax.setSegmentDepartureTime(4, response.split("\n")[0].split(" ")[len - 3]);
                                        if (pax.getSegmentDepartureTime(4).isEmpty()) {
                                            pax.setSegmentDepartureTime(4, response.split("\n")[0].split(" ")[len - 2]);
                                        }
                                        pax.setSegmentArrivalTime(4, response.split("\n")[0].split(" ")[len - 1]);
                                    } else {
                                        pax.setSegmentDepartureTime(4, response.split("\n")[0].split(" ")[len - 3]);
                                        pax.setSegmentArrivalTime(4, response.split("\n")[0].split(" ")[len - 1].split("/")[0]);
                                    }

                                }
                                break Destinations; // Exit as soon as a flight is booked
                            }
                            else
                                displaySeatsAvailabilityForFlights(logInfo, Origin, currentDestination, 4, departuredate);
                        }
                    }

                    // Move to the next day
                    departuredate++;

                    if (departuredate > departureEndDate) {
                        break; // Exit date loop if all days are checked
                    }

                }// end of while
            }// end of Destinations for loop

        } else {
            logInfo.info(MarkupHelper.createLabel("No seats available for any destination within the specified range.", ExtentColor.RED));
            mFailureDescription.put(getDriverID(),"No seats available for any destination within the specified range.");
            Assert.fail();
        }
    }

