    public void displayPNIS(ExtentTest logInfo) {
        try {
//                   6:ZH489/10OCTPTY-KIM/TOM/MOM
            ArrayList<Passenger> pax = mPassengers.get(getDriverID());
            String date = gl.sharesFormatDateFromGUI(pax.get(0).getSegmentDate(0));

            for (Passenger value : pax) {
                if (value.getPaxType().equalsIgnoreCase("INF")) {

                    String displayPNIS = "6:ZH" + pax.get(0).getSegmentFlight(0) + "/" + date + pax.get(0).getSegmentOriginCity(0)
                            + "-" + value.getAccompaniedPaxDetails().getfName() + "/" + value.getAccompaniedPaxDetails().getlName();
                    gl.logCommand(logInfo, displayPNIS);
                    gl.sendCmdValidateResponse(displayPNIS, value.getfName(), pax.get(0).getPnr(), logInfo);

                    logInfo.pass("I display PNIS");
                } else {
                    String displayPNIS = "6:ZH" + pax.get(0).getSegmentFlight(0) + "/" + date + pax.get(0).getSegmentOriginCity(0)
                            + "-" + value.getfName() + "/" + value.getlName();
                    gl.logCommand(logInfo, displayPNIS);
                    gl.sendCmdValidateResponse(displayPNIS, value.getfName(), pax.get(0).getPnr(), logInfo);
                }
            }

            String response = isharesPageObjects2.SHARES_RESPONSE.getText();
            Passenger passenger = mPassengers.get(getDriverID()).get(0);

            //***********Multiple item error*************//
            if (response.contains("MULTIPLE ITEMS")) {
                //Capturing ID for the PNR
                int index = response.indexOf(passenger.getPnr());
                String indexVal = response.substring((index - 27), (index - 24)).trim();
                String displayPNIS = "6:ZH" + pax.get(0).getSegmentFlight(0) + "/" + date + pax.get(0).getSegmentOriginCity(0)
                        + "-" + indexVal;
                gl.logCommand(logInfo, displayPNIS);
                gl.sendCmdValidateResponse(displayPNIS, "MULTIPLE ITEMS",pax.get(0).getfName(), pax.get(0).getPnr(), logInfo);

                isharesPageObjects2.SEND_ISHARES.click();
                gl.waitForProfileLoad();
                logInfo.addScreenCaptureFromBase64String(getBase64(getDriver()), "Screenshot");
            }

        } catch (AssertionError | Exception e) {

            ExtentReportListener.testStepHandle("FAIL", getDriver(), logInfo, e);
            Assert.fail("This step failed.. so stopping...");
        }
    }



