    public void addManualFareQuoteWithoutPayment(ExtentTest logInfo) {
        try {

            List<Integer> adtPaxIndexes = new ArrayList<>();
            List<Integer> chdPaxIndexes = new ArrayList<>();
            List<Integer> insPaxIndexes = new ArrayList<>();
            List<Integer> infPaxIndexes = new ArrayList<>();
            List<Integer> nrpsPaxIndexes = new ArrayList<>();
            List<Integer> nrsaPaxIndexes = new ArrayList<>();

            if (mPassengers.get(getDriverID()).get(0).getIsCorporatePNR() || mPassengers.get(getDriverID()).get(0).getIsGroupPNR()) {

                for (int i = 0; i < mPassengers.get(getDriverID()).size(); i++) {
                    if (mPassengers.get(getDriverID()).get(i).getPaxType().equalsIgnoreCase("ADT") || mPassengers.get(getDriverID()).get(i).getPaxType().equalsIgnoreCase("FQTV"))
                        adtPaxIndexes.add(i + 2);
                    else if (mPassengers.get(getDriverID()).get(i).getPaxType().equalsIgnoreCase("CHD"))
                        chdPaxIndexes.add(i + 2);
                    else if (mPassengers.get(getDriverID()).get(i).getPaxType().equalsIgnoreCase("INS"))
                        insPaxIndexes.add(i + 2);
                    else if (mPassengers.get(getDriverID()).get(i).getPaxType().equalsIgnoreCase("NRPS"))
                        nrpsPaxIndexes.add(i + 2);
                    else if (mPassengers.get(getDriverID()).get(i).getPaxType().equalsIgnoreCase("NRSA"))
                        nrsaPaxIndexes.add(i + 2);
                    else {
                        infPaxIndexes.add(i + 2);
                        adtPaxIndexes.add(i + 2);
                    }
                }
            } else {
                for (int i = 0; i < mPassengers.get(getDriverID()).size(); i++) {
                    if (mPassengers.get(getDriverID()).get(i).getPaxType().equalsIgnoreCase("ADT") || mPassengers.get(getDriverID()).get(i).getPaxType().equalsIgnoreCase("FQTV"))
                        adtPaxIndexes.add(i + 1);
                    else if (mPassengers.get(getDriverID()).get(i).getPaxType().equalsIgnoreCase("CHD"))
                        chdPaxIndexes.add(i + 1);
                    else if (mPassengers.get(getDriverID()).get(i).getPaxType().equalsIgnoreCase("INS"))
                        insPaxIndexes.add(i + 1);
                    else if (mPassengers.get(getDriverID()).get(i).getPaxType().equalsIgnoreCase("NRPS"))
                        nrpsPaxIndexes.add(i + 1);
                    else if (mPassengers.get(getDriverID()).get(i).getPaxType().equalsIgnoreCase("NRSA"))
                        nrsaPaxIndexes.add(i + 1);
                    else {
                        infPaxIndexes.add(i + 1);
                        adtPaxIndexes.add(i + 1);
                    }
                }
            }

            if (adtPaxIndexes.size() > 0)
                addQuoteForADT(logInfo, adtPaxIndexes);
            if (chdPaxIndexes.size() > 0)
                addQuoteForCHD(logInfo, chdPaxIndexes);
            if (insPaxIndexes.size() > 0)
                addQuoteForIns(logInfo, insPaxIndexes);
            if (infPaxIndexes.size() > 0)
                addQuoteForInf(logInfo, infPaxIndexes);
            if (nrpsPaxIndexes.size() > 0)
                addQuoteForADT(logInfo, nrpsPaxIndexes);
            if (nrsaPaxIndexes.size() > 0)
                addQuoteForADT(logInfo, nrsaPaxIndexes);

        } catch (AssertionError | Exception e) {

            ExtentReportListener.testStepHandle("FAIL", getDriver(), logInfo, e);
            Assert.fail("This step failed.. so stopping...");
        }
    }

    public void addManualFareQuote(ExtentTest logInfo, String payment) {
        try {

            List<Integer> adtPaxIndexes = new ArrayList<>();
            List<Integer> chdPaxIndexes = new ArrayList<>();
            List<Integer> insPaxIndexes = new ArrayList<>();
            List<Integer> infPaxIndexes = new ArrayList<>();
            List<Integer> nrpsPaxIndexes = new ArrayList<>();
            List<Integer> nrsaPaxIndexes = new ArrayList<>();

            if (mPassengers.get(getDriverID()).get(0).getIsCorporatePNR() || mPassengers.get(getDriverID()).get(0).getIsGroupPNR()) {

                for (int i = 0; i < mPassengers.get(getDriverID()).size(); i++) {
                    if (mPassengers.get(getDriverID()).get(i).getPaxType().equalsIgnoreCase("ADT") || mPassengers.get(getDriverID()).get(i).getPaxType().equalsIgnoreCase("FQTV"))
                        adtPaxIndexes.add(i + 2);
                    else if (mPassengers.get(getDriverID()).get(i).getPaxType().equalsIgnoreCase("CHD"))
                        chdPaxIndexes.add(i + 2);
                    else if (mPassengers.get(getDriverID()).get(i).getPaxType().equalsIgnoreCase("INS"))
                        insPaxIndexes.add(i + 2);
                    else if (mPassengers.get(getDriverID()).get(i).getPaxType().equalsIgnoreCase("NRPS"))
                        nrpsPaxIndexes.add(i + 2);
                    else if (mPassengers.get(getDriverID()).get(i).getPaxType().equalsIgnoreCase("NRSA"))
                        nrsaPaxIndexes.add(i + 2);
                    else {
                        infPaxIndexes.add(i + 2);
                        adtPaxIndexes.add(i + 2);
                    }
                }
            } else {
                for (int i = 0; i < mPassengers.get(getDriverID()).size(); i++) {
                    if (mPassengers.get(getDriverID()).get(i).getPaxType().equalsIgnoreCase("ADT") || mPassengers.get(getDriverID()).get(i).getPaxType().equalsIgnoreCase("FQTV"))
                        adtPaxIndexes.add(i + 1);
                    else if (mPassengers.get(getDriverID()).get(i).getPaxType().equalsIgnoreCase("CHD"))
                        chdPaxIndexes.add(i + 1);
                    else if (mPassengers.get(getDriverID()).get(i).getPaxType().equalsIgnoreCase("INS"))
                        insPaxIndexes.add(i + 1);
                    else if (mPassengers.get(getDriverID()).get(i).getPaxType().equalsIgnoreCase("NRPS"))
                        nrpsPaxIndexes.add(i + 1);
                    else if (mPassengers.get(getDriverID()).get(i).getPaxType().equalsIgnoreCase("NRSA"))
                        nrsaPaxIndexes.add(i + 1);
                    else {
                        infPaxIndexes.add(i + 1);
                        adtPaxIndexes.add(i + 1);
                    }
                }
            }

            if (adtPaxIndexes.size() > 0)
                addQuoteForADT(logInfo, adtPaxIndexes);
            if (chdPaxIndexes.size() > 0)
                addQuoteForCHD(logInfo, chdPaxIndexes);
            if (insPaxIndexes.size() > 0)
                addQuoteForIns(logInfo, insPaxIndexes);
            if (infPaxIndexes.size() > 0)
                addQuoteForInf(logInfo, infPaxIndexes);
            if (nrpsPaxIndexes.size() > 0)
                addQuoteForADT(logInfo, nrpsPaxIndexes);
            if (nrsaPaxIndexes.size() > 0)
                addQuoteForADT(logInfo, nrsaPaxIndexes);

//            ##### NO OF FARE QUOTES #####
            int noOfFareQuotes = (adtPaxIndexes.size() / 5) + (chdPaxIndexes.size() / 5) + (insPaxIndexes.size() / 5) + (infPaxIndexes.size() / 5) + (nrpsPaxIndexes.size() / 5) + (nrsaPaxIndexes.size() / 5);

            if (adtPaxIndexes.size() % 5 != 0)
                noOfFareQuotes++;
            if (chdPaxIndexes.size() % 5 != 0)
                noOfFareQuotes++;
            if (insPaxIndexes.size() % 5 != 0)
                noOfFareQuotes++;
            if (infPaxIndexes.size() % 5 != 0)
                noOfFareQuotes++;
            if (nrpsPaxIndexes.size() % 5 != 0)
                noOfFareQuotes++;
            if (nrsaPaxIndexes.size() % 5 != 0)
                noOfFareQuotes++;


            for (int i = 0; i < noOfFareQuotes; i++) {
                makePaymentForManualQuote(logInfo, payment, i + 1);
            }

        } catch (AssertionError | Exception e) {

            ExtentReportListener.testStepHandle("FAIL", getDriver(), logInfo, e);
            Assert.fail("This step failed.. so stopping...");
        }
    }

