    public String GDSPnrTotalSegmentsHK(String TotalSegments, String TotalPax) {
        String GDSPnrTotalSegments = "";
        Passenger pax = mPassengers.get(getDriverID()).get(0);

        //        CM0360Y20SEPPTYLAXNN1
        if (TotalSegments.equalsIgnoreCase("1")) {
            GDSPnrTotalSegments = pax.getAirline(0) + pax.getSegmentFlight(0)
                    + pax.getCOS() + gl.sharesFormatDateFromGUI(pax.getSegmentDate(0))
                    + pax.getSegmentOriginCity(0) + pax.getSegmentDestinationCity(0) + "HK" + TotalPax;
        } else if (TotalSegments.equalsIgnoreCase("2")) {
            String GDSPnrTotalSegments1 = pax.getAirline(0) + pax.getSegmentFlight(0)
                    + pax.getCOS() + gl.sharesFormatDateFromGUI(pax.getSegmentDate(0))
                    + pax.getSegmentOriginCity(0) + pax.getSegmentDestinationCity(0) + "HK" + TotalPax + "\n";

            String GDSPnrTotalSegments2 = pax.getAirline(1) + pax.getSegmentFlight(1)
                    + pax.getCOS() + gl.sharesFormatDateFromGUI(pax.getSegmentDate(1))
                    + pax.getSegmentOriginCity(1) + pax.getSegmentDestinationCity(1) + "HK" + TotalPax;
            GDSPnrTotalSegments = GDSPnrTotalSegments1 + GDSPnrTotalSegments2;
        }
        boolean CHDPax = false;

        for (int i = 0; i < mPassengers.get(getDriverID()).size(); i++) {
            if (mPassengers.get(getDriverID()).get(i).getPaxType().equalsIgnoreCase("CHD")
                    || mPassengers.get(getDriverID()).get(i).getPaxType().equalsIgnoreCase("INF")
                    || mPassengers.get(getDriverID()).get(i).getPaxType().equalsIgnoreCase("INS")) {
                GDSPnrAddPaxSSR();
                CHDPax = true;
                break;
            }
        }
        if (CHDPax) {
            System.out.println("GDSPnrTotalSegments " + GDSPnrTotalSegments);
            return GDSPnrTotalSegments + GDSPnrAddPaxSSR();
        } else {
            System.out.println("GDSPnrTotalSegments " + GDSPnrTotalSegments);
            return GDSPnrTotalSegments;
        }
    }

