    public void addQuoteForSameSurnamePax(ExtentTest logInfo, List<Integer> sameSurnamePaxIndexes) {
        try {
            int groupOf_5_Pax = sameSurnamePaxIndexes.size() / 5;       //Group indicates group of 5;
            int remainingPax = sameSurnamePaxIndexes.size() % 5;    //Remaining indicates extra pax remaining that need to be fare quoted
            int paxStart = 0;
            int paxIndex=1;
            String command;

//         FC#CCALC FARE END#N5.1/6.1/7.1/8.1/9.1#YUSD2012.45/XT118.60#-Y1#E1PANELTY
            while ((groupOf_5_Pax--) != 0) {
                command = "FC|CCALC FARE END|N";

                for (int i = paxStart; i < paxStart + 5; i++) {
                    command = command + sameSurnamePaxIndexes.get(i) + "."+paxIndex++ + "/";
                }

                command = command.substring(0, command.length() - 1) + "|YUSD2012.45/XT118.60|-Y1|E1PANELTY";
                System.out.println("FareQuote Command for ADT: " + command);

                gl.logCommand(logInfo, command);
                gl.sendCmdValidateResponse(command, "*", logInfo);

                paxStart = paxStart + 5;

                enter_FF_ToFileFareQuote(logInfo);
            }


            if (remainingPax > 0) {
                command = "FC|CCALC FARE END|N";

                for (int i = paxStart; i < (paxStart + remainingPax); i++) {
                    command = command + sameSurnamePaxIndexes.get(i) + "."+paxIndex++ + "/";
                }

                command = command.substring(0, command.length() - 1) + "|YUSD2012.45/XT118.60|-Y1|E1PANELTY";
                System.out.println("FareQuote Command for ADT: " + command);

                gl.logCommand(logInfo, command);
                gl.sendCmdValidateResponse(command, "*", logInfo);

                enter_FF_ToFileFareQuote(logInfo);
            }

        } catch (AssertionError | Exception e) {
            ExtentReportListener.testStepHandle("FAIL", getDriver(), logInfo, e);
            Assert.fail("This step failed.. so stopping...");
        }
    }


