    public void checkInReentryWithUpgrade(ExtentTest logInfo) throws IOException {
        try {
//                 6:360/22DECPTY-PIAZZA$PR1#U
            Passenger pax = mPassengers.get(getDriverID()).get(0);
            String date = gl.sharesFormatDateFromGUI(pax.getSegmentDate(0));

            for (int i = 0; i < pax.getfName().length(); i++) {
                String checkInReentryWithUpgrade = "6:" + pax.getSegmentFlight(0) + "/" + date + pax.getSegmentOriginCity(0)
                        + "-" + pax.getfName() + "$PR1|U";
                gl.logCommand(logInfo, checkInReentryWithUpgrade);
                gl.sendCmdValidateResponse(checkInReentryWithUpgrade, "ADDED TO C/CABIN STBY LIST", "SEATS ASSIGNED", "UPGRADE CODE NOT ALLOWED FOR NRPS","MULTIPLE ITEMS", logInfo);
                String response = isharesPageObjects2.SHARES_RESPONSE.getText();

                if (response.contains("MULTIPLE ITEMS")) {
                    logInfo.addScreenCaptureFromBase64String(getBase64(getDriver()), "Screenshot");
                    String response1 = isharesPageObjects2.SHARES_RESPONSE.getText();

                    //Capturing ID for the PNR
                    int index = response1.indexOf(mPassengers.get(getDriverID()).get(0).getPnr());
                    String indexVal = response1.substring((index - 27), (index - 24)).trim();

                    String MultiListCmd = "6:LK-" + indexVal+"$PR1#U"; // Selected pax with ID
                    gl.logCommand(logInfo, MultiListCmd);
                    gl.sendCmdValidateResponse(MultiListCmd, "ADDED TO C/CABIN STBY LIST", "SEATS ASSIGNED", "UPGRADE CODE NOT ALLOWED FOR NRPS", logInfo);
                }
            }

        } catch (AssertionError | Exception e) {

            ExtentReportListener.testStepHandle("FAIL", getDriver(), logInfo, e);
            Assert.fail("This step failed.. so stopping...");
        }
    }


