    public void checkTTYPNR(ExtentTest logInfo, String uniquePnr) {

        gl.ignoreTRNS(logInfo);
        Passenger pax = mPassengers.get(getDriverID()).get(0);
        pax.setUniqueTTYPnr(uniquePnr);
        gl.logCommand(logInfo, "*ER-" + uniquePnr);
        gl.sendCmdValidateResponse("*ER-" + uniquePnr, pax.getfName(),uniquePnr,"NO MATCH FOUND", logInfo);
        logInfo.pass("I retrieve PNR for TTY message");

// These below codes are removed , as we are dealing with Unique PNR and not with passenger PNR
        String response = isharesPageObjects2.SHARES_RESPONSE.getText();
        String pnr = response.substring(0, 6);
        pax.setPnr(pnr);
//
        gl.logCommand(logInfo, "*" + pax.getPnr());
        gl.sendCmdValidateResponse("*" + pax.getPnr(), pax.getlName(), pax.getfName(),pax.getPnr(), logInfo);
        logInfo.pass("I retrieve PNR for TTY message");

    }

    public String GDSPnrAddPaxSSR() {

        String GDSPnrAddPaxSSR = "";
        Passenger pax ;

        for (int i = 0; i < mPassengers.get(getDriverID()).size(); i++) {

            pax = mPassengers.get(getDriverID()).get(i);

            if (pax.getPaxType().equalsIgnoreCase("CHD")) {
                //SSRCHLDYYNN1-1DEMO/JIM
                GDSPnrAddPaxSSR = GDSPnrAddPaxSSR + "\n" + "SSRCHLDYYNN1" + "-" + pax.getfName() + "/" + pax.getlName();

            } else if(pax.getPaxType().equalsIgnoreCase("INS")) {

                for(int j=0;j<mPassengers.get(getDriverID()).get(0).getTotalSegments();j++) {
                    //  SSRINFTCMNN1PTYMDE0835Y26SEP-1TIM/JIL.03SEP21 OCCUPYING SEAT
                    GDSPnrAddPaxSSR = GDSPnrAddPaxSSR + "\n" + "SSRINFTCMNN1" +
                            pax.getSegmentOriginCity(j) + pax.getSegmentDestinationCity(j)
                            + pax.getSegmentFlight(j) + pax.getCOS()
                            + gl.sharesFormatDateFromGUI(pax.getSegmentDate(j))
                            + "-1" + pax.getfName() + "/" + pax.getlName()
                            + "." + gl.plusDaysFromTodayNew(-200).replaceAll("-", "") + " OCCUPYING SEAT";
                }

            } else if (pax.getPaxType().equalsIgnoreCase("INF")) {

                for(int j=0;j<mPassengers.get(getDriverID()).get(0).getTotalSegments();j++)
                {
                    //  SSRINFTCMNN1PTYLAX787Y10DEC-1ADT/ONE.ADT/INF.19MAR24
                    GDSPnrAddPaxSSR = GDSPnrAddPaxSSR + "\n" + "SSRINFTCMNN1" +
                            pax.getSegmentOriginCity(j) + pax.getSegmentDestinationCity(j)
                            + pax.getSegmentFlight(j) + pax.getCOS()
                            + gl.sharesFormatDateFromGUI(pax.getSegmentDate(j))
                            + "-1" + pax.getAccompaniedPaxDetails().getfName() + "/" + pax.getAccompaniedPaxDetails().getlName()
                            + "." + pax.getAccompaniedPaxDetails().getfName() + "/" + pax.getlName() + "."
                            + gl.plusDaysFromTodayNew(-200).replaceAll("-", "");
                }

            }
        }
        System.out.println("GDSPnrTotalPax " + GDSPnrAddPaxSSR);
        return GDSPnrAddPaxSSR;
    }




