    public void TTYMessageBasicAirlinePnrArrivalDepart(ExtentTest logInfo, String SystemType) {
        try {

            //            Y
            //            PTYRMCM
            //           .MUCRM1A 251335
            //            MUC1A SUSUSQ
            //            1JHON/KIM
            //            CM120Y12APRPTYMEXNN1/0911 1208 BR

            Passenger pax = mPassengers.get(getDriverID()).get(0);

            String ArraivalFlightTime = pax.getSegmentArrivalTime(0).replaceAll("[a-zA-Z]", "");
            String DepartFlightTime = pax.getSegmentDepartureTime(0).replaceAll("[a-zA-Z]", "");

            if (DepartFlightTime.length() == 3) {
                DepartFlightTime = "0" + pax.getSegmentDepartureTime(0).replaceAll("[a-zA-Z]", "");
            }
            if (ArraivalFlightTime.length() == 3) {
                ArraivalFlightTime = "0" + pax.getSegmentArrivalTime(0).replaceAll("[a-zA-Z]", "");
            }

            String Line2 = null;   //PTYRMCM
            if (globalConstants.testEnv.equalsIgnoreCase("sharesURL")) {
                Line2 = "PTYRMCM";
            } else {
                Line2 = "CLTYSCM";
            }

            String UniquePnr = GenerateUniquePnr(logInfo);
            String SegmentData = null;
            SegmentData = pax.getAirline(0) + pax.getSegmentFlight(0)
                    + pax.getCOS() + gl.sharesFormatDateFromGUI(pax.getSegmentDate(0))
                    + pax.getSegmentOriginCity(0) + pax.getSegmentDestinationCity(0) + "NN" + mPassengers.get(getDriverID()).size()
                    + "/" + DepartFlightTime + " " + ArraivalFlightTime + " " + "BR";

            String BasicAirlinePnr = "Y" + "\n" +
                    Line2 + "\n" +
                    ".MUCRM1" + SystemType + " 251335" + "\n" +
                    "MUC1" + SystemType + " " + UniquePnr + "\n" +
                    GDSPnrTotalPax() + SegmentData;

            isharesPageObjects2.FORMSIZE_DROPDOWN.click();
            isharesPageObjects2.FORMSIZE_SELECT24.click();

            gl.logCommand(logInfo, BasicAirlinePnr);
            System.out.println("BaseCommand " + BasicAirlinePnr);
            gl.copyCmdToClipboardAndPaste(BasicAirlinePnr, isharesPageObjects2.FORMSIZE_SELECT2_TEXTAREA);

            isharesPageObjects2.SEND_ISHARES.click();
            logInfo.pass("I passed TTY message");
            logInfo.addScreenCaptureFromBase64String(getBase64(getDriver()), "Screenshot");
            gl.waitForProfileLoad();
            String response = isharesPageObjects2.SHARES_RESPONSE.getText();
            gl.logResponse(logInfo, response);
            Assert.assertTrue(response.contains("MESSAGE ACCEPTED") || response.contains("SYS ACC MSG"));

            isharesPageObjects2.FORMSIZE_DROPDOWN.click();
            isharesPageObjects2.FORMSIZE_SELECT1.click();

            checkTTYPNR(logInfo, UniquePnr);

            logInfo.pass("I enter TTY message to generate PNR");
            logInfo.addScreenCaptureFromBase64String(getBase64(getDriver()), "Screenshot");

        } catch (AssertionError | Exception e) {

            ExtentReportListener.testStepHandle("FAIL", getDriver(), logInfo, e);
            Assert.fail("This step failed.. so stopping...");
        }
    }


