    public void addQuoteForADTForManualStoredFare(ExtentTest logInfo, List<Integer> adtPaxIndexes) {
        try {
            int groupOf_5_Pax = adtPaxIndexes.size() / 5;       //Group indicates group of 5;
            int remainingPax = adtPaxIndexes.size() % 5;    //Remaining indicates extra pax remaining that need to be fare quoted
            int paxStart = 0;
            String command;

            while ((groupOf_5_Pax--) != 0) {
                command = "FC|CCALC FARE END|";

                command = command.substring(0, command.length() - 1) + "|YUSD2012.45/XT118.60|-Y1|E1PANELTY";
                System.out.println("FareQuote Command for ADT: " + command);

                gl.logCommand(logInfo, command);
                gl.sendCmdValidateResponse(command, "*", logInfo);

                paxStart = paxStart + 5;

            }
            if (remainingPax > 0) {
                command = "FC|CCALC FARE END|YUSD2012.45/XT118.60|-Y1|E1PANELTY";
                System.out.println("FareQuote Command for ADT: " + command);

                gl.logCommand(logInfo, command);
                gl.sendCmdValidateResponse(command, "*", logInfo);
            }
        } catch (AssertionError | Exception e) {
            ExtentReportListener.testStepHandle("FAIL", getDriver(), logInfo, e);
            Assert.fail("This step failed.. so stopping...");
        }
    }

