    public void addAuxilliaryService(ExtentTest logInfo, String serviceIdentifier, String actionCode, String passengerNumber, String additionalInfo, String segmentNo) {

        //            /ATX PC NN3 MRYMCE 19AUG-GOLDEN STATE AIR
        //Where,
        //
        /// Action Identifier for Auxiliary Service Segments
        //ATX Service Identifier
        //PC Airline Code (to take action on requested service)
        //NN3 Action Code followed by Number in Party
        //MRYMCE Board/Offpoint
        //19AUG Day/Month
        //-GOLDEN STATE AIR Additional information as required, preceded by a hyphen, e.g., name of vendor, type aircraft, etc.

        try {
            Passenger pax = mPassengers.get(getDriverID()).get(0);

            String boardpt = pax.getSegmentOriginCity(Integer.parseInt(segmentNo) - 1);
            String offpt = pax.getSegmentDestinationCity(Integer.parseInt(segmentNo) - 1);
            String date = gl.sharesFormatDateFromGUI(pax.getSegmentDate(Integer.parseInt(segmentNo) - 1));

//       0ATX PC NN3 MRYMCE 19AUG-GOLDEN STATE AIR
            String command = "0" + serviceIdentifier + " " + pax.getAirline(0) + " " + actionCode + passengerNumber + " " + boardpt + offpt + " " + date +
                    "-" + additionalInfo;
            gl.logCommand(logInfo, command);
            gl.sendCmdValidateResponse(command, date, additionalInfo, logInfo);


//            6P*
            command = "6P";
            gl.logCommand(logInfo, command);
            gl.sendCmdValidateResponse(command, "6P *", logInfo);

//            ER
            command = "ER";
            gl.logCommand(logInfo, command);
            gl.sendCmdValidateResponse(command, boardpt + offpt + "/" + additionalInfo, logInfo);


        } catch (AssertionError | Exception e) {
            ExtentReportListener.testStepHandle("FAIL", getDriver(), logInfo, e);
            Assert.fail("This step failed.. so stopping...");
        }

    }


