    public void TTYMessageToModifyFlight(ExtentTest logInfo, String FlightModificationType, String SystemType) {
        try {
//            Y
//            PTYRMCM
//            .MUCRM1A 251335
//            FAM
//            2N493/05MAR#PTY/FX

            Passenger pax = mPassengers.get(getDriverID()).get(0);
            String flight = pax.getSegmentFlight(0);
            String date = gl.sharesFormatDateFromGUI(pax.getSegmentDate(0));
            String origin = pax.getSegmentOriginCity(0);
            String destination = pax.getSegmentDestinationCity(0);

            String ArrivalFlightTime = pax.getSegmentArrivalTime(0);
            String DepartFlightTime = pax.getSegmentDepartureTime(0);

            if (DepartFlightTime.length() == 4) {
                DepartFlightTime = "0" + pax.getSegmentDepartureTime(0);
            }
            if (ArrivalFlightTime.length() == 4) {
                ArrivalFlightTime = "0" + pax.getSegmentArrivalTime(0);
            }


            String Line2 = null;   //PTYRMCM
            if (globalConstants.testEnv.equalsIgnoreCase("sharesURL")) {
                Line2 = "PTYRMCM";
            } else {
//                Line2 = "CLTYSCM";
                Line2 = "PTYRMCM";
            }

            String SegmentData = null;
            if (FlightModificationType.equalsIgnoreCase("CancelAirport")) {
                //2N0876/07MAY#PTY/FX
                SegmentData = "2N" + flight + "/" + date + "|" + origin + "/FX";
            } else if (FlightModificationType.equalsIgnoreCase("CancelAirportWithMessage")) {
                //  2N360/07MAY#PTY/FX FLIGHT CANCEL
                SegmentData = "2N" + flight + "/" + date + "|" + origin + "/FX FLIGHT CANCEL";
            } else if (FlightModificationType.equalsIgnoreCase("DecisionAirportWithMessage")) {
                //  2D360/07MAY#PTY/2F - DELAY DUE TO RAIN
                SegmentData = "2D" + flight + "/" + date + "|" + origin + "/2F - DELAY DUE TO RAIN";
            } else if (FlightModificationType.equalsIgnoreCase("ForcastAirportWithMessage")) {
                //  2F360/07MAY#PTY/2F - DELAY DUE TO RAIN
                SegmentData = "2F" + flight + "/" + date + "|" + origin + "/2F - DELAY DUE TO RAIN";
            } else if (FlightModificationType.equalsIgnoreCase("AirReturnEntry")) {
                //  2P360/07MAY RR PTY 1130A GATE RETURN EXAMPLE
                SegmentData = "2P" + flight + "/" + date + " RR " + origin + " " + ArrivalFlightTime + " GATE RETURN";
            } else if (FlightModificationType.equalsIgnoreCase("TeleTypeEntry")) {
                //  2P 116/30APR IN MEX 135P
                SegmentData = "2P" + flight + "/" + date + " IN " + destination + " " + ArrivalFlightTime;
            } else if (FlightModificationType.equalsIgnoreCase("ReplaceAirReturnRule")) {
                //  2P 116/30APR OUT MEX 135P
                SegmentData = "2P" + flight + "/" + date + " OUT " + origin + " " + ArrivalFlightTime;
            } else if (FlightModificationType.equalsIgnoreCase("TeleTypeProgressOut")) {
                //  2P493/07MAY OUT PTY 926A L00.01
                SegmentData = "2P" + flight + "/" + date + " OUT " + origin + " " + ArrivalFlightTime + "L00.01";
            } else if (FlightModificationType.equalsIgnoreCase("ExclusiveFlightProgressType")) {
                //  2P837/29NOV ETD BOG 0458A
                SegmentData = "2P" + flight + "/" + date + " ETD " + origin + " " + DepartFlightTime;
            } else if (FlightModificationType.equalsIgnoreCase("ExclusiveFlightProgressTypeOFF")) {
                //  2P837/29NOV OFF PTY 0656A
                SegmentData = "2P" + flight + "/" + date + " OFF " + origin + " " + DepartFlightTime;
            } else if (FlightModificationType.equalsIgnoreCase("DeleteSegment")) {
                // 2X 200/20SEP
                SegmentData = "2X" + " " + flight + "/" + date;
            } else if (FlightModificationType.equalsIgnoreCase("RemoveRestriction")) {
                // 2R 106/08MAR
                SegmentData = "2R" + " " + flight + "/" + date;
            } else if (FlightModificationType.equalsIgnoreCase("CancelAirportWithMessageForL")) {
                //  2N395/05MAR#SCL/LX CANCEL
                SegmentData = "2N" + flight + "/" + date + "|" + origin + "/LX CANCEL";
            } else if (FlightModificationType.equalsIgnoreCase("NewOriginFlagStop")) {
                //  2S260/09JULPTY-O/754A/1257PLAX
                SegmentData = "2S" + flight + "/" + date + origin + "-O" + "/" + DepartFlightTime + "/" + ArrivalFlightTime + destination;
            }

            String BasicAirlinePnr = "Y" + "\n" +
                    Line2 + "\n" +
                    ".MUCRM1" + SystemType + "\n" +
                    "FAM" + "\n" +
                    SegmentData;

            isharesPageObjects2.FORMSIZE_DROPDOWN.click();
            isharesPageObjects2.FORMSIZE_SELECT24.click();

            gl.logCommand(logInfo, BasicAirlinePnr);
            System.out.println("BaseCommand " + BasicAirlinePnr);
            gl.copyCmdToClipboardAndPaste(BasicAirlinePnr, isharesPageObjects2.FORMSIZE_SELECT2_TEXTAREA);

            isharesPageObjects2.SEND_ISHARES.click();
            logInfo.pass("I passed TTY message");
            logInfo.addScreenCaptureFromBase64String(getBase64(getDriver()), "Screenshot");
            gl.waitForProfileLoad();

            String response = isharesPageObjects2.SHARES_RESPONSE.getText();
            gl.logResponse(logInfo, response);
            Assert.assertTrue(response.contains("MESSAGE ACCEPTED") || response.contains("SYS ACC MSG"));

            isharesPageObjects2.FORMSIZE_DROPDOWN.click();
            isharesPageObjects2.FORMSIZE_SELECT1.click();

            logInfo.pass("I enter TTY message to modify flight");
            logInfo.addScreenCaptureFromBase64String(getBase64(getDriver()), "Screenshot");

        } catch (AssertionError | Exception e) {

            ExtentReportListener.testStepHandle("FAIL", getDriver(), logInfo, e);
            Assert.fail("This step failed.. so stopping...");
        }
    }

    public void checkFlightStatus(ExtentTest logInfo, String StatusType) {

        try {
            Passenger pax = mPassengers.get(getDriverID()).get(0);
            String flight = pax.getSegmentFlight(0);
            String Date = gl.sharesFormatDateFromGUI(pax.getSegmentDate(0));
            String OriginCity = pax.getSegmentOriginCity(0);

            if (StatusType.equalsIgnoreCase("OnTime")) {
                //    2360
                String checkFlightStatus = "2" + flight;
                gl.logCommand(logInfo, checkFlightStatus);
                gl.sendCmdValidateResponse(checkFlightStatus, "ON-TIME", logInfo);
            } else if (StatusType.equalsIgnoreCase("CancelAirport")) {
                //     2360/09MAY
                String checkFlightStatus = "2" + flight + "/" + Date;
                gl.logCommand(logInfo, checkFlightStatus);
                gl.sendCmdValidateResponse(checkFlightStatus, "/FX", logInfo);
            } else if (StatusType.equalsIgnoreCase("CancelAirportWithMessage")) {
                //     2360/09MAY
                String checkFlightStatus = "2" + flight + "/" + Date;
                gl.logCommand(logInfo, checkFlightStatus);
                gl.sendCmdValidateResponse(checkFlightStatus, "FX FLIGHT CANCEL", logInfo);
            } else if (StatusType.equalsIgnoreCase("CancelAirportWithMessageForL")) {
                //     2360/09MAY
                String checkFlightStatus = "2" + flight + "/" + Date;
                gl.logCommand(logInfo, checkFlightStatus);
                gl.sendCmdValidateResponse(checkFlightStatus, "LX FLIGHT CANCEL", "LX CANCEL", logInfo);
            } else if (StatusType.equalsIgnoreCase("ForcastAirportWithMessage")
                    || StatusType.equalsIgnoreCase("DecisionAirportWithMessage")) {
                //    2360/09MAY
                String checkFlightStatus = "2" + flight + "/" + Date;
                gl.logCommand(logInfo, checkFlightStatus);
                gl.sendCmdValidateResponse(checkFlightStatus, "DELAY DUE TO RAIN", logInfo);
            } else if (StatusType.equalsIgnoreCase("OnTimeWithDate")) {
                //    2360/08MAY
                String checkFlightStatus = "2" + flight + "/" + Date;
                gl.logCommand(logInfo, checkFlightStatus);
                gl.sendCmdValidateResponse(checkFlightStatus, "ON-TIME", logInfo);
            } else if (StatusType.equalsIgnoreCase("OnTimeWithDateAndOrigin")) {
                //    2360/09MAYPTY
                String checkFlightStatus = "2" + flight + "/" + Date + OriginCity;
                gl.logCommand(logInfo, checkFlightStatus);
                gl.sendCmdValidateResponse(checkFlightStatus, flight + "/" + Date, logInfo);
            } else if (StatusType.equalsIgnoreCase("AirReturnEntry")) {
                //     2360/09MAY
                String checkFlightStatus = "2" + flight + "/" + Date;
                gl.logCommand(logInfo, checkFlightStatus);
                gl.sendCmdValidateResponse(checkFlightStatus, "GATE RETURN", logInfo);
            } else if (StatusType.equalsIgnoreCase("ReplaceAirReturnRule")) {
                //    2360/09MAY
                String checkFlightStatus = "2" + flight + "/" + Date;
                gl.logCommand(logInfo, checkFlightStatus);
                gl.sendCmdValidateResponse(checkFlightStatus, "OUT","FLIGHT ON-TIME", logInfo);
            } else if (StatusType.equalsIgnoreCase("TeleTypeEntry")) {
                //    2360/09MAY
                String checkFlightStatus = "2" + flight + "/" + Date;
                gl.logCommand(logInfo, checkFlightStatus);
                gl.sendCmdValidateResponse(checkFlightStatus, "IN", logInfo);
            } else if (StatusType.equalsIgnoreCase("AirReturnGroundTime")) {
                //    2360/09MAY
                String checkFlightStatus = "2" + flight + "/" + Date;
                gl.logCommand(logInfo, checkFlightStatus);
                gl.sendCmdValidateResponse(checkFlightStatus, "FRO", logInfo);
            } else if (StatusType.equalsIgnoreCase("TeleTypeProgressOut")) {
                //    2360/09MAY
                String checkFlightStatus = "2" + flight + "/" + Date;
                gl.logCommand(logInfo, checkFlightStatus);
                gl.sendCmdValidateResponse(checkFlightStatus, "L00.01", "OUT", logInfo);
            } else if (StatusType.equalsIgnoreCase("ExclusiveFlightProgressType")
                    || StatusType.equalsIgnoreCase("ExclusiveFlightProgressTypeOFF")) {
                //    2360/09MAY
                String checkFlightStatus = "2" + flight + "/" + Date;
                gl.logCommand(logInfo, checkFlightStatus);
                //gl.sendCmdValidateResponse(checkFlightStatus, "ETD", logInfo);
                gl.sendCmdValidateResponse(checkFlightStatus, "ETD","FLIGHT ON-TIME", logInfo);
            } else if (StatusType.equalsIgnoreCase("FlightMoreDelay")) {

                LocalDate currentDate = LocalDate.now();
                LocalDate olderDate = currentDate.minusDays(20);
                DateTimeFormatter formatter = DateTimeFormatter.ofPattern("ddMMM");
                String OlderDate = olderDate.format(formatter).toUpperCase();

                //    2360/09MAY

                String checkFlightStatus = "2" + flight + "/" + OlderDate;
                gl.logCommand(logInfo, checkFlightStatus);
                gl.sendCmdValidateResponse(checkFlightStatus, "FLIGHT MORE DELAY","INVLD DATE", logInfo);
            } else if (StatusType.equalsIgnoreCase("ETA")) {

                //    2360/09JAN
                String checkFlightStatus = "2" + flight + "/" + Date;
                gl.logCommand(logInfo, checkFlightStatus);
                gl.sendCmdValidateResponse(checkFlightStatus, "ETA", logInfo);
            } else if (StatusType.equalsIgnoreCase("PRE")) {
                //    2360/09JAN
                String checkFlightStatus = "2" + flight + "/" + Date;
                gl.logCommand(logInfo, checkFlightStatus);
                gl.sendCmdValidateResponse(checkFlightStatus, "PRE", logInfo);
            } else if (StatusType.equalsIgnoreCase("Flight_CarrierCode")) {
                //    21031/17NOVPTY-UA
                String checkFlightStatus = "2" + flight + "/" + Date + "-" + pax.getAirline(0);
                gl.logCommand(logInfo, checkFlightStatus);
                gl.sendCmdValidateResponse(checkFlightStatus, "STARNET FLIFO DATA", logInfo);
            }else if (StatusType.equalsIgnoreCase("DelayMessage")) {
                String checkFlightStatus = "2" + flight + "/" + Date ;
                gl.logCommand(logInfo, checkFlightStatus);
                gl.sendCmdValidateResponse(checkFlightStatus, "DLY MSG", logInfo);
            }else if (StatusType.equalsIgnoreCase("Displayhistory")) {
                String checkFlightStatus = "2" + flight + "/" + Date + "*H";
                gl.logCommand(logInfo, checkFlightStatus);
                gl.sendCmdValidateResponse(checkFlightStatus, "DLY MSG", logInfo);
            }

        } catch (AssertionError | Exception e) {
            ExtentReportListener.testStepHandle("FAIL", getDriver(), logInfo, e);
            Assert.fail("This step failed.. so stopping...");
        }
    }



