    public void rebookWithNewCOSAndNewDate(ExtentTest logInfo, String SegmentNumber) {
        try {
            int SegNo = Integer.parseInt(SegmentNumber);

            int SegmentIndex = SegNo + 1;
            Passenger pax = mPassengers.get(getDriverID()).get(0);
            String date = gl.sharesFormatDateFromGUI(pax.getSegmentDate(SegNo) + 2);
            String COS = pax.getCOS();

            if (COS.equalsIgnoreCase("Y"))
                COS = "C";
            else COS = "Y";

            // .2@C@26APR
            String rebookWithNewCOSAndNewDate = "." + SegmentIndex + "@" + COS + "@" + date;
            gl.logCommand(logInfo, rebookWithNewCOSAndNewDate);
            gl.sendCmdValidateResponse(rebookWithNewCOSAndNewDate, "002-OK-", logInfo);
            logInfo.pass("I enter rebook command to change COS and date of the segment");

            //               6P
            String command = "6P";
            gl.logCommand(logInfo,command);
            gl.sendCmdValidateResponse(command,"6P","*",logInfo);

//               ER
            command = "ER";
            gl.logCommand(logInfo,command);
            gl.sendCmdValidateResponse(command,pax.getPnr(),logInfo);

        } catch (AssertionError | Exception e) {
            ExtentReportListener.testStepHandle("FAIL", getDriver(), logInfo, e);
            Assert.fail("This step failed.. so stopping...");
        }
    }


