    public void deleteSegments(ExtentTest logInfo, String segment, String moreToDelete) {
        try {
            // .1XK#.2XK#.3XK

            if (moreToDelete.equalsIgnoreCase("Yes")) {
                mSegments.put(getDriverID(), mSegments.get(getDriverID()) + segment + "#"); //1+2+
            } else {
                String command = "";
                mSegments.put(getDriverID(), mSegments.get(getDriverID()) + segment + "#");
                String segments[] = mSegments.get(getDriverID()).split("#");
                for (String seg : segments)
                    command = command + "." + seg + "XK" + "|";

                command = command.substring(0, command.length() - 1);
                gl.logCommand(logInfo, command);
                gl.sendCmdValidateResponse(command, "SEG", "XK", logInfo);
                mSegments.put(getDriverID(), "");
            }

        } catch (AssertionError | Exception e) {
            ExtentReportListener.testStepHandle("FAIL", getDriver(), logInfo, e);
            Assert.fail("This step failed.. so stopping...");
        }
    }

