    public void enter_T_schedule_facts(ExtentTest logInfo) {
        try {
            //
            Passenger pax = mPassengers.get(getDriverID()).get(0);

            String ArraivalFlightTime = pax.getSegmentArrivalTime(0);
            String DepartFlightTime = pax.getSegmentDepartureTime(0);

            if (DepartFlightTime.length() == 4) {
                DepartFlightTime = "0" + pax.getSegmentDepartureTime(0);
            }
            if (ArraivalFlightTime.length() == 4) {
                ArraivalFlightTime = "0" + pax.getSegmentArrivalTime(0);
            }

            String meridian1 = "";
            if (ArraivalFlightTime.contains("A")) {
                ArraivalFlightTime = ArraivalFlightTime.split("A")[0];
                meridian1 = "A";
            } else {
                ArraivalFlightTime = ArraivalFlightTime.split("P")[0];
                meridian1 = "P";
            }

            int arriveTime = Integer.parseInt(ArraivalFlightTime) + 2;

            String meridian = "";
            if (DepartFlightTime.contains("A")) {
                DepartFlightTime = DepartFlightTime.split("A")[0];
                meridian = "A";
            } else {
                DepartFlightTime = DepartFlightTime.split("P")[0];
                meridian = "P";
            }

            int departTime = Integer.parseInt(ArraivalFlightTime) + 2;

            ArraivalFlightTime = arriveTime + meridian1;
            DepartFlightTime = departTime + meridian;

            //   .T1/0756A123P
            String command = ".T1/" + DepartFlightTime +" "+ ArraivalFlightTime;
            gl.logCommand(logInfo, command);
            gl.sendCopiedCmdValidateResponse2(logInfo, command, "*");
            logInfo.addScreenCaptureFromBase64String(getBase64(getDriver()), "Screenshot");

            gl.sendCmdValidateResponse("6P#ER", ArraivalFlightTime, logInfo);

        } catch (AssertionError | Exception e) {
            ExtentReportListener.testStepHandle("FAIL", getDriver(), logInfo, e);
            Assert.fail("This step failed.. so stopping...");
        }
    }


