    public void dividePNRUsingPaxNumberToDivide(ExtentTest logInfo, String noOfPaxToDivide) {
        try {
            Passenger pax = mPassengers.get(getDriverID()).get(0);
            String Response;

            do
            {
                String command = "D" + noOfPaxToDivide;
                gl.logCommand(logInfo, command);
                gl.sendCmdValidateResponse(command,"SPLIT PARTY", logInfo);
                logInfo.pass("I Divide the PNR");

                gl.logCommand(logInfo, "6P");
                gl.sendCmdValidateResponse("6P", "6P *", logInfo);
                logInfo.pass("I save the divided PNR");

                gl.logCommand(logInfo, "F");
                gl.sendCmdValidateResponse("F", "RECORD FILED","DIVIDED", logInfo);

                Response = isharesPageObjects2.SHARES_RESPONSE.getText();
                String PNR2 = Response.substring(13, 19);           // Stored newly created PNR in map mPnr1
                pax.setPnr2(PNR2);
                logInfo.pass("I Capture the new divided PNR");

                gl.logCommand(logInfo, "6P#ER");
                gl.sendCmdValidateResponse("6P#ER", "6P#ER *", pax.getPnr(), "CHANGES RESTRICTED - COMPLETE PNR DIVIDE AND ER", logInfo);

                gl.sendCmdIfRequired("ER", pax.getPnr(), "SIMULT CHGS TO PNR", logInfo);

                Response = isharesPageObjects2.SHARES_RESPONSE.getText();

                if (isharesPageObjects2.SHARES_RESPONSE.getText().contains("SIMULT CHGS TO PNR")) {

                    gl.logCommand(logInfo, "IR");
                    gl.sendCmdValidateResponse("IR", pax.getPnr(), logInfo);
                }
            }
            while(Response.contains("SIMULT CHGS TO PNR"));


            gl.logCommand(logInfo, "*" + pax.getPnr2());
            gl.sendCmdValidateResponse("*" + pax.getPnr2(), pax.getPnr2(), logInfo);
            logInfo.pass("I save and retrieve divided pnr");


        } catch (AssertionError | Exception e) {

            ExtentReportListener.testStepHandle("FAIL", getDriver(), logInfo, e);
            Assert.fail("This step failed.. so stopping...");
        }
    }


