    public void partialMarriageCancellation(ExtentTest logInfo) {

        try {


            Passenger pax = mPassengers.get(getDriverID()).get(0);
            String originCity = pax.getSegmentOriginCity(0);
            String flight = pax.getSegmentFlight(0);
            String StartDate = gl.sharesFormatDateFromGUI(pax.getSegmentDate(0));
            String destinationCity = pax.getSegmentDestinationCity(0);
            String COS = pax.getCOS();
            String Airline = pax.getAirline(0);
            String SecondSegFlight = pax.getSegmentFlight(1);

            ////0CM360Y09MAYPTYLAXNN1
            String partialmarriagecancellation = "0" + Airline + flight + COS + StartDate + originCity + destinationCity + "NN1";
            gl.logCommand(logInfo, partialmarriagecancellation);
            gl.sendCmdValidateResponse(partialmarriagecancellation, "ETKT ELIGIBLE", logInfo);

            //0CM362Y09MAYLAXPTYNN1
            partialmarriagecancellation = "0" + Airline + SecondSegFlight + COS + StartDate + destinationCity + originCity + "NN1";
            gl.logCommand(logInfo, partialmarriagecancellation);
            gl.sendCmdValidateResponse(partialmarriagecancellation, "ETKT ELIGIBLE", logInfo);


            //*R
            gl.logCommand(logInfo, "*R");
            gl.sendCmdValidateResponse("*R", "NO NAMES", logInfo);

            //X2
            partialmarriagecancellation = "X2";
            gl.logCommand(logInfo, partialmarriagecancellation);
            gl.sendCmdValidateResponse(partialmarriagecancellation, "X2 NEXT REPLACES 2 ", logInfo);

            //*R
            gl.logCommand(logInfo, "*R");
            gl.sendCmdValidateResponse("*R", "NO NAMES", logInfo);

            //X1
            partialmarriagecancellation = "X1";
            gl.logCommand(logInfo, partialmarriagecancellation);
            gl.sendCmdValidateResponse(partialmarriagecancellation, "X1 NEXT REPLACES 1 ", logInfo);

            //*R
            gl.logCommand(logInfo, "*R");
            gl.sendCmdValidateResponse("*R", "NO NAMES", logInfo);

        } catch (AssertionError | Exception e) {
            ExtentReportListener.testStepHandle("FAIL", getDriver(), logInfo, e);
            Assert.fail("This step failed.. so stopping...");

        }

    }

