    public void enterCommandtoBookFlight(ExtentTest logInfo, String segmentStatus, String rowNum) {
        try {

            Passenger pax = mPassengers.get(getDriverID()).get(0);
            int totalPax = mPassengers.get(getDriverID()).size();
            String COS = pax.getCOS();
            String Status = null;


            if (segmentStatus.equalsIgnoreCase("NoStatus"))  // N4Y1
                Status = "";
            else if (segmentStatus.equalsIgnoreCase("PD")) //N2K2PD
                Status = "PD";
            else if (segmentStatus.equalsIgnoreCase("GNN")) //N10Y1GNN
                Status = "GNN";
            else if (segmentStatus.equalsIgnoreCase("PNN")) // N1Y1PNN
                Status = "PNN";
            else if (segmentStatus.equalsIgnoreCase("GPD")) // N10K2GPD
                Status = "PNN";
            else if (segmentStatus.equalsIgnoreCase("PPA")) // N10K2PPA
                Status = "PPA";


            String command = "N" + totalPax + COS + rowNum + Status;
            gl.logCommand(logInfo, command);
            gl.sendCmdValidateResponse(command, "ETKT ELIGIBLE", logInfo);

        } catch (AssertionError | Exception e) {
            ExtentReportListener.testStepHandle("FAIL", getDriver(), logInfo, e);
            Assert.fail("This step failed.. so stopping...");
        }
    }

