    public void flag_Stop_Restrictions_SHARES_entry(ExtentTest logInfo, String newOrigin) {
        try {
//           2S360/02JUNONT-O/754A/103PPTY

            String command = null;
            Passenger pax = mPassengers.get(getDriverID()).get(0);
            String date = gl.sharesFormatDateFromGUI(pax.getSegmentDate(0));
            if (newOrigin.contains("ONT-I")) {
                //2S120/31JANLAX-I/115P/130PPTY
                command = "2S" + pax.getSegmentFlight(0) + "/" + date + pax.getSegmentOriginCity(0) + "-I/" +
                        pax.getSegmentDepartureTime(0) + "/" + pax.getSegmentArrivalTime(0) +
                        pax.getSegmentDestinationCity(0);
                gl.logCommand(logInfo, command);
                gl.sendCmdValidateResponse(command, "*","PREMATURE REQUEST", logInfo);
            } else if (newOrigin.contains("2S_I")) {
                //2S360/DDMMMPTY-I/0200A/0300A LAX
                command = "2S" + pax.getSegmentFlight(0) + "/" + date + pax.getSegmentOriginCity(0) + "-I/0200A/0300A" + pax.getSegmentDestinationCity(0);
                gl.logCommand(logInfo, command);
                gl.sendCmdValidateResponse(command, "CITY ALREADY EXISTS", "PREMATURE REQUEST", logInfo);
            }  else if (newOrigin.contains("2S_T")) {
                //2S787/22DECPTY-T/100P/200PLAX
                command = "2S" + pax.getSegmentFlight(0) + "/" + date + pax.getSegmentOriginCity(0) + "-T/" + pax.getSegmentArrivalTime(0)
                        + "/" + pax.getSegmentDepartureTime(0) + pax.getSegmentDestinationCity(0);
                gl.logCommand(logInfo, command);
                gl.sendCmdValidateResponse(command, "CITY ALREADY EXISTS", "PREMATURE REQUEST", logInfo);
            } else if (newOrigin.contains("2S_O")) {
                //2S150/31JANMEX-O/700A/817APTY
                command = "2S" + pax.getSegmentFlight(0) + "/" + date + pax.getSegmentOriginCity(0) + "-O/" + pax.getSegmentArrivalTime(0)
                        + "/" + pax.getSegmentDepartureTime(0) + pax.getSegmentDestinationCity(0);
                gl.logCommand(logInfo, command);
                gl.sendCmdValidateResponse(command, "*", "PREMATURE REQUEST","CITY ALREADY EXISTS",logInfo);
            } else if (newOrigin.contains("2X")) {
                //2X360/16MAY#PTY/ETD 0700A
                command = "2X" + pax.getSegmentFlight(0) + "/" + date + "|" + pax.getSegmentOriginCity(0) + "/ETD " + pax.getSegmentDepartureTime(0);
                gl.logCommand(logInfo, command);
                gl.sendCmdValidateResponse(command, "FLIFO MSG NOT ON RCD", logInfo);
            }else {
                command = "2S" + pax.getSegmentFlight(0) + "/" + date + newOrigin + "-O/" +
                        pax.getSegmentDepartureTime(0) + "/" + pax.getSegmentArrivalTime(0) +
                        pax.getSegmentOriginCity(0);
                gl.logCommand(logInfo, command);
               // gl.sendCmdValidateResponse(command, "FLAG STOP-ORIGIN-ETA", newOrigin + "/ETD", logInfo);
                gl.sendCmdValidateResponse(command, "FLAG STOP-ORIGIN-ETA", newOrigin + "/ETD","PREMATURE REQUEST", logInfo);
            }


        } catch (AssertionError | Exception e) {
            ExtentReportListener.testStepHandle("FAIL", getDriver(), logInfo, e);
            Assert.fail("This step failed.. so stopping...");
        }
    }


