    public void retrieveAndSaveTicket(ExtentTest logInfo) {

        Passenger pax = mPassengers.get(getDriverID()).get(0);
        int TotalPax = mPassengers.get(getDriverID()).size();

        String[] Tax = {"US", "XT", "T1", "AY", "PA", "FZ"};

        int i = 1; // Segment 1

        try {
            for (int j = 1; j <= TotalPax; j++) {

                pax = mPassengers.get(getDriverID()).get(j - 1);

                String retrieve = "*ET" + j + "." + i;
                gl.logCommand(logInfo,retrieve);
                gl.sendCmdValidateResponse(retrieve, logInfo);

                String response = isharesPageObjects2.SHARES_RESPONSE.getText();
                String ticket = response.substring(49, 63);

                pax.setTicketNumber(ticket);
                System.out.println("Ticket" + i + " -> " + ticket);
                Assert.assertTrue(response.contains("230"));
                logInfo.pass("Ticket number passenger");

                if (j == 1) {
                    for (Passenger passenger : mPassengers.get(getDriverID())) {
                        int k = 0;
                        for (String taxes : Tax) {
                            if (response.contains(taxes)) {
                                pax.setTax(k, taxes);
                                System.out.println("I enter tax " + k + pax.getTax(k));
                                k++;
                            }
                        }
                    }
                }
            }

        } catch (AssertionError | Exception e) {
            ExtentReportListener.testStepHandle("FAIL", getDriver(), logInfo, e);
            Assert.fail("This step failed.. so stopping...");
        }

    }

