    public void searchFlightAvailabilityDifferentFormat(ExtentTest logInfo, String Origin, String Destination) {
        int endFlt = 3;

        Passenger pax = mPassengers.get(getDriverID()).get(0);
        String COS = mPassengers.get(getDriverID()).get(0).getCOS();
        int totalpax = mPassengers.get(getDriverID()).size();
        String airline = mPassengers.get(getDriverID()).get(0).getAirline(0);
        int departuredate = mPassengers.get(getDriverID()).get(0).getSegmentDate(0);  //Getting the departure Date based on feature file input
        int departureEndDate = departuredate + 5;

        displaySeatsAvailabilityForFlightsDifferentFormat(logInfo, Origin, Destination, 0, departuredate);  //Passing 3 for 4th Segment

        for (int j = 1; j <= endFlt; j++) //loop for flight
        {
            String command = "N" + totalpax + COS + j;

            gl.logCommand(logInfo, command);
            gl.sendCmdValidateResponse(command, logInfo);

            String response = isharesPageObjects2.SHARES_RESPONSE.getText();
            gl.checkForErrors(command,response,logInfo);

            if (response.contains("ETKT ELIGIBLE") || response.contains("ADV PAX FLT ARRIVES TERMINAL") || response.contains("SS" + totalpax) || response.contains("NN" + totalpax)) {
                for (Passenger passenger : mPassengers.get(getDriverID())) {
                    passenger.setSegmentFlight(0, response.substring(6, 10).trim());
                    passenger.setSegmentDate(0, departuredate);
                    passenger.setAirline(0, airline);
                    passenger.setCOS(COS);
                }

                System.out.println("Flight number " + response.substring(6, 10));

                int len = response.split("\n")[0].split(" ").length;

                if (airline.equalsIgnoreCase("CM")) {
                    pax.setSegmentDepartureTime(0, response.split("\n")[0].split(" ")[len - 3]);
                    pax.setSegmentArrivalTime(0, response.split("\n")[0].split(" ")[len - 1]);
                } else {
                    pax.setSegmentDepartureTime(0, response.split("\n")[0].split(" ")[len - 3]);
                    pax.setSegmentArrivalTime(0, response.split("\n")[0].split(" ")[len - 1].split("/")[0]);
                }

                break;
            } else if (j == endFlt)  //This is for the case when on a single day no more flights are to check
            {
                j = 1;

                if (departuredate <= departureEndDate)
                    departuredate++;
                else
                    break;

            }

            displaySeatsAvailabilityForFlightsDifferentFormat(logInfo, Origin, Destination, 0, departuredate);

        }

    }

