    public void forecastMessage(ExtentTest logInfo) {
        try {
            Passenger pax = mPassengers.get(getDriverID()).get(0);
            String date = gl.sharesFormatDateFromGUI(pax.getSegmentDate(0));
            String arrivalTime = pax.getSegmentDepartureTime(0);
            String meridian;

            if (arrivalTime.contains("A")) {
                arrivalTime = arrivalTime.split("A")[0];
                meridian = "A";
            } else {
                arrivalTime = arrivalTime.split("P")[0];
                meridian = "P";
            }

            int arriveTime = Integer.parseInt(arrivalTime);

            if (arriveTime / 100 < 10)
                arriveTime = arriveTime + 100;
            else
                arriveTime = arriveTime + 1000;

            String modifiedTime = arriveTime + meridian;

//               2F120/09APR#
//               BOS/AUTH CHG TO 25 BOSLGA LIKELY#
//               LGA/PRBL ARVL LGA 1125A
            String command = "2F" + pax.getSegmentFlight(0) + "/" + date + "|" + "\n"
                    + pax.getSegmentOriginCity(0) + "/AUTH CHG TO 25 " + pax.getSegmentOriginCity(0) + pax.getSegmentDestinationCity(0) + " LIKELY|" + "\n"
                    + pax.getSegmentDestinationCity(0) + "/PRBL ARVL " + pax.getSegmentDestinationCity(0) + modifiedTime;
            gl.logCommand(logInfo, command);
//            gl.sendCmdValidateResponse(command, "*", logInfo);

            isharesPageObjects2.FORMSIZE_DROPDOWN.click();
            isharesPageObjects2.FORMSIZE_SELECT4.click();
            isharesPageObjects2.FORMSIZE_SELECT2_TEXTAREA.click();

            gl.copyCmdToClipboardAndPaste(command, isharesPageObjects2.FORMSIZE_SELECT2_TEXTAREA);
            isharesPageObjects2.SEND_ISHARES.click();

            String response = isharesPageObjects2.SHARES_RESPONSE.getText();
            Assert.assertTrue(response.contains("*") || response.contains("RPLCD"));
            logInfo.addScreenCaptureFromBase64String(getBase64(getDriver()), "Screenshot");

            isharesPageObjects2.FORMSIZE_DROPDOWN.click();
            isharesPageObjects2.FORMSIZE_SELECT1.click();

        } catch (AssertionError | Exception e) {
            ExtentReportListener.testStepHandle("FAIL", getDriver(), logInfo, e);
            Assert.fail("This step failed.. so stopping...");
        }
    }


