    public void addSUDutyCode(ExtentTest logInfo) {
        try {
            Passenger pax = mPassengers.get(getDriverID()).get(0);

            if (globalConstants.testEnv.equalsIgnoreCase("sharesCURL")) {
                //  ZAFIL CM 00F165C8 028 04
                //  ZAFIL CM 00F165C8 024 E2E4`

                String command = "ZAFIL CM 00" + pax.getLniata() + " 028 04";
                gl.logCommand(logInfo, command);
                gl.sendCmdValidateResponse(command, logInfo);

                command = "ZAFIL CM 00" + pax.getLniata() + " 024 E2E4";
                gl.logCommand(logInfo, command);
                gl.sendCmdValidateResponse(command, logInfo);
            } else {
                //  ZAFIL CM E038E7C 24 E2E4 VALDATA-D7D9
                String code = "W" + pax.getLniata() + "*";
                gl.logCommand(logInfo, code);
                gl.sendCmdValidateResponse(code, logInfo);

                String response = isharesPageObjects2.SHARES_RESPONSE.getText();
                String[] Response = response.split("\n");
                String[] SUcode = Response[1].split(" ");
                String dutyCode = SUcode[2];

                String command = "ZAFIL CM " + dutyCode + " 24 E2E4 VALDATA-D7D9";
                gl.logCommand(logInfo, command);
                gl.sendCmdValidateResponse(command, logInfo);
                logInfo.addScreenCaptureFromBase64String(getBase64(getDriver()), "Screenshot");
            }
        } catch (AssertionError | Exception e) {

            ExtentReportListener.testStepHandle("FAIL", getDriver(), logInfo, e);
            Assert.fail("This step failed.. so stopping...");
        }
    }

