    public void addTicketNumberToPax(ExtentTest logInfo,String Response)
    {
        try
        {
            String alphabeticREGEX = "^[A-Z]+/[A-Z]+$";
            Pattern PATTERN = Pattern.compile(alphabeticREGEX);

            String[] responseRows =Response.split("\n");
            String paxName=null;

            Rows:
            for(int i=0;i<responseRows.length;i++)
            {
                if(responseRows[i].contains("230"))
                {
                    for(int j=0;j<responseRows[i].split(" ").length;j++)
                    {
                        String word = responseRows[i].split(" ")[j];
                        if(!StringUtils.isBlank(word) && PATTERN.matcher(word).matches() && !word.contains("*INF") && !word.contains("*INS") && !word.contains("*CHD"))
                        {
                            paxName= word;
                            break Rows;
                        }
                        else if(!StringUtils.isBlank(word) && word.contains("*INF") && PATTERN.matcher(word.substring(0,word.indexOf("*"))).matches() )
                        {
                            paxName= word.substring(0,word.indexOf("*"));
                            break Rows;
                        }
                        else if(!StringUtils.isBlank(word) && word.contains("*CHD") && PATTERN.matcher(word.substring(0,word.indexOf("*"))).matches() )
                        {
                            paxName= word.substring(0,word.indexOf("*"));
                            break Rows;
                        }
                        else if(!StringUtils.isBlank(word) && word.contains("*INS") && PATTERN.matcher(word.substring(0,word.indexOf("*"))).matches() )
                        {
                            paxName= word.substring(0,word.indexOf("*"));
                            break Rows;
                        }
                    }
                }
            }

            String ticketNumber = Response.split("\n")[0].substring(Response.indexOf("230"));

            logInfo.info(MarkupHelper.createLabel("Passenger Name: "+paxName +" || TicketNumber: "+ticketNumber, ExtentColor.PURPLE));

            for(Passenger pax : mPassengers.get(getDriverID()))
            {
                if((pax.getfName()+"/"+pax.getlName()).equalsIgnoreCase(paxName) || (pax.getfName()+"/"+pax.getlName()).contains(paxName))
                {
                    pax.setTicketNumber(ticketNumber);
                    break;
                }
            }

            for(Passenger pax : mPassengers.get(getDriverID()))
            {
                if(pax.getPaxType().equalsIgnoreCase("INF"))
                {
                    if((pax.getAccompaniedPaxDetails().getfName()+"/"+pax.getAccompaniedPaxDetails().getlName()).equalsIgnoreCase(paxName) ||
                            (pax.getAccompaniedPaxDetails().getfName()+"/"+pax.getAccompaniedPaxDetails().getlName()).contains(paxName))
                    {
                        pax.getAccompaniedPaxDetails().setTicketNumber(ticketNumber);
                        break;
                    }
                }
            }
        }
        catch (AssertionError | Exception e) {
            ExtentReportListener.testStepHandle("FAIL", getDriver(), logInfo, e);
            Assert.fail("This step failed.. so stopping...");
        }
    }

    public void enterET1ForETKTUpdates(ExtentTest logInfo) {
        try {

            ArrayList<Passenger> passengers = mPassengers.get(getDriverID());

            int totalSegments = passengers.get(0).getTotalSegments();
            int totalPassengers = mPassengers.get(getDriverID()).size();

            for(Passenger pax : mPassengers.get(getDriverID()))
            {
                if(pax.getPaxType().equalsIgnoreCase("INF"))
                    totalPassengers++;
            }

//            *ET1.1          *ET1.1/FOP ---> Display coupon 1 of ticket 1, unmask credit card number (FS6602)
//            / -->Separator (slash)
//            FOP --> Indicator to override restriction

            int paxIndex =0;
            int ticket=1;
            int segmentsLeft;
 Coupon:    do
            {
                int coupon =1;
                segmentsLeft=totalSegments;

                while(segmentsLeft >0)
                {
                    String command = "*ET" + ticket + "." + coupon;

                    gl.logCommand(logInfo, command);
                    gl.sendCmdValidateResponse(command,"CPN","FARE","INVALID ETKT/COUPON NUMBER",logInfo);

                    if(isharesPageObjects2.SHARES_RESPONSE.getText().contains("INVALID ETKT/COUPON NUMBER"))
                        break Coupon;

                    if(--segmentsLeft>0)
                    {
                        ticket = coupon==4 ? ticket+1 : ticket ;
                        coupon = coupon==4 ? 1 : coupon+1 ;
                    }

                }
                String Response = isharesPageObjects2.SHARES_RESPONSE.getText();
                addTicketNumberToPax(logInfo,Response);

                if(coupon<=4)
                    ticket++;

            }
            while(++paxIndex<totalPassengers);

            for(Passenger pax : mPassengers.get(getDriverID()))
            {
                if(pax.getPaxType().equalsIgnoreCase("INF"))
                {
                    System.out.println("INF: " +pax.getFullName()+"-->"+pax.getTicketNumber());
                    System.out.println("ADULT: "+pax.getAccompaniedPaxDetails().getFullName()+"-->"+pax.getAccompaniedPaxDetails().getTicketNumber());
                }
                else
                {
                    System.out.println(pax.getFullName()+"-->"+pax.getTicketNumber());
                }

            }
        } catch (AssertionError | Exception e) {

            ExtentReportListener.testStepHandle("FAIL", getDriver(), logInfo, e);
            Assert.fail("This step failed.. so stopping...");
        }
    }



