    public void unEvenExchange(ExtentTest logInfo, String segSequence, String RefundType) throws IOException {

        Passenger pax = mPassengers.get(getDriverID()).get(0);

        gl.logCommand(logInfo,saveAndRetrieve);
        gl.sendCmdValidateResponse(saveAndRetrieve, logInfo);

        String retrieve = "ER";
        gl.logCommand(logInfo, "ER");
        gl.sendCmdValidateResponse(retrieve, "PNR MODIFIED", "ETKT/PNR MODIFIED- CHK ITIN", "MODIFY REC", logInfo);

        if(isharesPageObjects2.SHARES_RESPONSE.getText().contains("MODIFY REC")){
            gl.sendCmdIfRequired("6P#ER", pax.getPnr(), logInfo);
        }
        else{
            gl.sendCmdIfRequired(retrieve, pax.getPnr(), logInfo);
        }

        gl.logCommand(logInfo, "T-ETCKPRICE");
        gl.sendCmdValidateResponse("T-ETCKPRICE", "SUM OF TOTAL FARE", logInfo);

        String Response = isharesPageObjects2.SHARES_RESPONSE.getText();
        String TotalAmount = null;
        String[] response = Response.split("\n");

        for (String s : response) {
            if (s.contains("ADD COLLECT") || s.contains("REFUND")) {
                String[] seat = s.split(" ");
                TotalAmount = seat[seat.length - 5].replace("$", "");
                System.out.println(seat[seat.length - 5]);
            }
        }

        System.out.println("tax amount " + TotalAmount);
        String TaxName = pax.getTax(0);

        float Tax = Integer.parseInt(TotalAmount.substring(0, TotalAmount.indexOf(".")));
        float tax = Tax / pax.getfName().length();
        System.out.println("tax: " + tax);

        for (int j = 0; j < mPassengers.get(getDriverID()).size(); j++) {
            pax = mPassengers.get(getDriverID()).get(j);
            String reissue = "";
            // Doing Reissue  T-$UE23022300006271/FVI/OB1262.00/OXCO49.00/XT142.80/AC$5555555555554444/1230/N1234#N3.2#ET - XT , T1, US, UK, A1, AH
            if (RefundType.equalsIgnoreCase("UsingRefund")) {
//                T-$UE23022300011705/FVI/OB2566.00/OXUS22.20/AY5.60/XT101.72/RF$RD*PENALTY$25#N1.1#ET
                reissue = "T-$UE" + pax.getTicketNumber() + "/FVI/OB" + tax + "0/" + TaxName + "142.80" + "/RF$RD*PENALTY$25|N" + (j + 1) + "." + segSequence + "|ET";

            } else if (RefundType.equalsIgnoreCase("XFNIL")) {
//                T-$UE23021844064310/FDB/OB0.00/OX20.00/XT00.50/AC$36003400300044/1130/N969931#@XFNIL#N1.1#ET
                reissue = "T-$UE" + pax.getTicketNumber() + "/FDB/OB" + tax + "0/" + TaxName + "142.80" + "/AC$36003400300044/1130/N969931|@XFNIL|N" + (j + 1) + "." + segSequence + "|ET";

            }else if (RefundType.equalsIgnoreCase("XFNIL_Reissue")) {
//                T-$UE23021885502744/FVI/OB1054.00/OXAH1.25/XT15.00/AC$36143123768083/0626/N675442#@XFNIL#N1.1#ET
                reissue = "T-$UE" + pax.getTicketNumber() + "/FVI/OB" + tax + "0/" + TaxName + "142.80" + "/AC$36143123768083/0626/N675442|@XFNIL|N" + (j + 1) + "." + segSequence + "|ET";

            }else if (RefundType.equalsIgnoreCase("Refund")) {
//                T-$UE23022300022511/FVI/OB688.00/IK1.55/XT101.98/AC$4911830000000/1224/N1234#N1.1#ET
                reissue = "T-$UE" + pax.getTicketNumber() + "/FVI/OB" + tax + "0/" + TaxName + "142.80" + "/AC$4911830000000/1224/N1234|N" + (j + 1) + "." + segSequence + "|ET";
            }else if (RefundType.equalsIgnoreCase("RFRD_XFNIL")) {
//                T-$UE/FCASH/OB1081.00/OXYC5.00/XT1135.00/RF$RD#@XFNIL#ET
                reissue = "T-$UE/FCASH/" + "/OB" + tax + "0/" + TaxName + "XT1135.00/RF$RD#@XFNIL#ET";
            }


            gl.logCommand(logInfo, reissue);
            gl.sendCmdValidateResponse(reissue, "FARE", "SEE ADV PURCHASE", "SIMULT", logInfo);
            logInfo.addScreenCaptureFromBase64String(getBase64(getDriver()), "Screenshot");
            Response = isharesPageObjects2.SHARES_RESPONSE.getText();

            if (Response.contains("SIMULT")) {
                gl.sendCmdValidateResponse("IR", mPassengers.get(getDriverID()).get(0).getPnr(), logInfo);
                logInfo.addScreenCaptureFromBase64String(getBase64(getDriver()), "Screenshot");
                gl.sendCmdValidateResponse(reissue, "FARE", "SEE ADV PURCHASE", logInfo);
                logInfo.addScreenCaptureFromBase64String(getBase64(getDriver()), "Screenshot");
            }

            // Saving the transaction
            gl.logCommand(logInfo, ignoreAndRetrieve);
            gl.sendCmdValidateResponse(ignoreAndRetrieve, mPassengers.get(getDriverID()).get(0).getPnr(), logInfo);

//            gl.logCommand(logInfo,"*" + mOrderNumber.get(getDriverID()));
//            gl.sendCmdValidateResponse("*" + mOrderNumber.get(getDriverID()), mOrderNumber.get(getDriverID()));
//            logInfo.addScreenCaptureFromBase64String(getBase64(getDriver()), "Screenshot");

            gl.logCommand(logInfo, "FR/ALL");
            gl.sendCmdValidateResponse("FR/ALL", logInfo);
//
            gl.logCommand(logInfo, "6P#ER");
            gl.sendCmdValidateResponse("6P#ER", logInfo);

            gl.logCommand(logInfo, endAndretrieve);
            gl.sendCmdValidateResponse(endAndretrieve, logInfo);
            Response = isharesPageObjects2.SHARES_RESPONSE.getText();

            if (Response.contains("SIMULT")) {
                gl.sendCmdValidateResponse("IR", mPassengers.get(getDriverID()).get(0).getPnr(), logInfo);
            }

            gl.logCommand(logInfo, ignoreAndRetrieve);
            gl.sendCmdValidateResponse(ignoreAndRetrieve, mPassengers.get(getDriverID()).get(0).getPnr(), logInfo);
        }

        //Checking PNR history
        gl.logCommand(logInfo, checkPnrHistory);
        gl.sendCmdValidateResponse(checkPnrHistory, "EXCHANGED", logInfo);

        //Check Ticket Status
        gl.logCommand(logInfo, checkTicketStatus);
        gl.sendCmdValidateResponse(checkTicketStatus, "EXCHANGED", logInfo);

    }


