    public void verifySegmentStatus(ExtentTest logInfo, String status) {
        try {
            if (status.equalsIgnoreCase("CM USED")) {
                gl.logCommand(logInfo, "*ET");
                gl.sendCmdValidateResponse("*ET", "CM USED", logInfo);
                logInfo.pass("Verified Segment status");


            } else if (status.equalsIgnoreCase("VOID")) {
                gl.logCommand(logInfo, "*ET");
                gl.sendCmdValidateResponse("*ET", "VOIDED", logInfo);
                logInfo.pass("Verified Segment status");

            } else if (status.equalsIgnoreCase("REVOKE")) {
                gl.logCommand(logInfo, "*ET");
                gl.sendCmdValidateResponse("*ET", "REVOKED", logInfo);
                logInfo.pass("Verified Segment status");

            }else if (status.equalsIgnoreCase("NO_SHOWED")) {
                gl.logCommand(logInfo, "*ET");
                gl.sendCmdValidateResponse("*ET", "NOSHOWED", logInfo);
                logInfo.pass("Verified Segment status");
            }



        } catch (Exception e) {

            ExtentReportListener.testStepHandle("FAIL", getDriver(), logInfo, e);
            Assert.fail("This step failed.. so stopping...");
        }
    }


