    public void enterLA_RCmdForFareQuote(ExtentTest logInfo, String SegmentNumber) {
        try {
            String fareQuote = "LA$R|S" + SegmentNumber;

            gl.logCommand(logInfo, fareQuote);
            gl.sendCmdValidateResponse(fareQuote, "FARE", logInfo);
            logInfo.pass("I enter LA$R|S command");


            String command = "FF";
            gl.logCommand(logInfo, command);
            gl.sendCmdValidateResponse(command, "FARE QUOTE  1 FILED", logInfo);


            gl.logCommand(logInfo, "6P");
            gl.sendCmdValidateResponse("6P", "ETKT/PNR MODIFIED- CHK ITIN", "6P *", logInfo);
            logInfo.pass("I save changes");


            gl.logCommand(logInfo, "ER");
            gl.sendCmdIfRequired("ER", "PNR MODIFIED", logInfo);
            logInfo.pass("I capture divided pnr");

            gl.logCommand(logInfo, "ER");
            gl.sendCmdValidateResponse("ER", "*FQ", logInfo);
            logInfo.pass("I capture divided pnr");


        } catch (AssertionError | Exception e) {

            ExtentReportListener.testStepHandle("FAIL", getDriver(), logInfo, e);
            Assert.fail("This step failed.. so stopping...");
        }
    }

