    public void payBYAmexMultiQuote(ExtentTest logInfo) {
        try {

            String AMEX1 = "T-$343434343434343/1224/N1234|Q1|ET";
            String AMEX2 = "T-$343434343434343/1224/N1234|Q2|ET";
            gl.logCommand(logInfo, AMEX1);
            gl.sendCmdValidateResponse(AMEX1, "CK FOR POSSIBLE FULL/PARTIAL EXISTING ", "CHECK IN REQUIRED", "FIN OR IGN TRANS", logInfo);
            logInfo.pass("Pay by AMEX");

            gl.logCommand(logInfo, AMEX1);
            gl.sendCmdValidateResponse(AMEX1, "FIN OR IGN TRANS", "FARE", logInfo);

            gl.logCommand(logInfo, ignoreAndRetrieve);
            gl.sendCmdValidateResponse(ignoreAndRetrieve, "ETKT", logInfo);

            gl.logCommand(logInfo, AMEX2);
            gl.sendCmdValidateResponse(AMEX2, "CK FOR POSSIBLE FULL/PARTIAL EXISTING ", "CHECK IN REQUIRED", "FIN OR IGN TRANS", logInfo);
            logInfo.pass("Pay by AMEX");

            gl.logCommand(logInfo, AMEX2);
            gl.sendCmdValidateResponse(AMEX2, "FIN OR IGN TRANS", "FARE", logInfo);

            gl.logCommand(logInfo, ignoreAndRetrieve);
            gl.sendCmdValidateResponse(ignoreAndRetrieve, "ETKT", logInfo);

        } catch (AssertionError | Exception e) {
            ExtentReportListener.testStepHandle("FAIL", getDriver(), logInfo, e);
            Assert.fail("This step failed.. so stopping...");
        }
    }





