    public void rebook_command_to_Rebook_class_of_service_1(ExtentTest logInfo, String index) {
        try {
//           .1@B
            //6P#ER
            int Index = Integer.parseInt(index);
            Passenger pax = mPassengers.get(getDriverID()).get(0);

            for (int i = 0; i < pax.getTotalSegments(); i++) {
                if (i == Index) {
                    String command = "." + index + "@B";
                    gl.logCommand(logInfo, command);
                    gl.sendCmdValidateResponse(command, "002-OK-", logInfo);

                    command = "6P#ER";
                    gl.logCommand(logInfo, command);
                    gl.sendCmdValidateResponse(command, pax.getSegmentFlight(0) + "B", "TRANSACT WILL UNSEAT", logInfo);

                    gl.sendCmdIfRequired("ER", pax.getSegmentFlight(0) + "B", logInfo);
                }
            }
        } catch (AssertionError | Exception e) {
            ExtentReportListener.testStepHandle("FAIL", getDriver(), logInfo, e);
            Assert.fail("This step failed.. so stopping...");
        }
    }

    public void manualStoredFareData(ExtentTest logInfo, String entryType) {
        try {

            List<Integer> adtPaxIndexes = new ArrayList<>();

            for (int i = 0; i < mPassengers.get(getDriverID()).size(); i++) {
                if (mPassengers.get(getDriverID()).get(i).getPaxType().equalsIgnoreCase("ADT"))
                    adtPaxIndexes.add(i + 1);
            }

            if (adtPaxIndexes.size() > 0)
                addQuoteForADTForManualStoredFare(logInfo, adtPaxIndexes);

            if (entryType.contains("EndorsementRestrictions")) {
//                FI#E1NON REFUNDABLE
                String command = "FI|E1NON REFUNDABLE";
                gl.logCommand(logInfo, command);
                gl.sendCmdValidateResponse(command, "*", logInfo);
            } else if (entryType.contains("TourCodeOrEmployeeID")) {
//                FI#F98764LAXPTY
                String command = "FI|F98764LAXPTY";
                gl.logCommand(logInfo, command);
                gl.sendCmdValidateResponse(command, "*", logInfo);

//                FI#FIT6ZZ1TOURUSA
                command = "FI|FIT6ZZ1TOURUSA";
                gl.logCommand(logInfo, command);
                gl.sendCmdValidateResponse(command, "*", logInfo);
            }

            enter_FF_ToFileFareQuote(logInfo);

            gl.logCommand(logInfo, "*FQ");
            gl.sendCmdValidateResponse("*FQ", "FARE QUOTE- MANUALPRICE", logInfo);

        } catch (AssertionError | Exception e) {

            ExtentReportListener.testStepHandle("FAIL", getDriver(), logInfo, e);
            Assert.fail("This step failed.. so stopping...");
        }
    }


