    public void cancelOrDeleteSegment(ExtentTest logInfo, String SegmentNumber, String rebookType) {

        try {
            Passenger pax = mPassengers.get(getDriverID()).get(0);
            String command = "";

            if (rebookType.equalsIgnoreCase("DeleteSegment")) {

                command = "X" + SegmentNumber;
                gl.logCommand(logInfo, command);
                gl.sendCmdValidateResponse(command, "NEXT REPLACES", "SEGMENTS CANCELED", logInfo);
                logInfo.pass("I delete the segment");

            } else if (rebookType.equalsIgnoreCase("DeleteMutipleSegment")) {

                for (int i = 1; i <= Integer.parseInt(SegmentNumber); i++) {
                    command = command + "/" + i;

                }
                String DeleteCommand = "X" + command.substring(1);
                gl.logCommand(logInfo, DeleteCommand);
                gl.sendCmdValidateResponse(DeleteCommand, "NEXT REPLACES", "SEGMENTS CANCELED", logInfo);
                logInfo.pass("I delete segment");

            }

        } catch (AssertionError | Exception e) {

            ExtentReportListener.testStepHandle("FAIL", getDriver(), logInfo, e);
            Assert.fail("This step failed.. so stopping...");
        }
    }

