    public void initiateTARAndRestablishLink(ExtentTest logInfo) {
        try {

            Passenger pax = mPassengers.get(getDriverID()).get(0);
            String POS = pax.getPOS();
            String ActivateLANATA = pax.getLniata();

            ArrayList<String> locCode = new ArrayList<>();

//            C-RMR/LAX
            String command = "C-RMR/" + POS;
            gl.logCommand(logInfo, command);
            gl.sendCmdValidateResponse(command, "ACO  RMR  MASTER  RECORD", "PRODUCTION", logInfo);

            String[] rows = isharesPageObjects2.SHARES_RESPONSE.getText().split("\n");

            for (int i = 3; i < rows.length; i++) {
                if (rows[i].contains("PRODUCTION")) {
                    String[] text = rows[i].split(" ");
                    System.out.println("index: " + i + " value: " + text[17]);
                    locCode.add(text[17]);
                }
            }

            for (int i = 0; ; i++) {

                String POSCommand = "W" + ActivateLANATA + "C3" + POS + "CM" + locCode.get(i);
                gl.logCommand(logInfo, POSCommand);
                gl.sendCmdValidateResponse(POSCommand, "AAA CREATED", logInfo);
                gl.sendCmdValidateResponse("BSIB", "B-SINE COMPLETE", logInfo);

//            C:I
                String initiateTAR = "C:I";
                gl.logCommand(logInfo, initiateTAR);
                gl.sendCmdValidateResponse(initiateTAR, "AUTOMATED TAR INITIATED", "AGENT TAR PREV INITIATED", "PLZ BALANCE PREV DAYS TAR AND RE-ENTER", logInfo);
                logInfo.pass("I sign in as ACO");
                logInfo.addScreenCaptureFromBase64String(getBase64(getDriver()), "Screenshot");

                if (isharesPageObjects2.SHARES_RESPONSE.getText().contains("AUTOMATED TAR INITIATED") || isharesPageObjects2.SHARES_RESPONSE.getText().contains("AGENT TAR PREV INITIATED")) {
                    break;
                }
            }

//            C-ON
            String reestablishLinkCmd = "C-ON";
            gl.logCommand(logInfo, reestablishLinkCmd);
            gl.sendCmdValidateResponse(reestablishLinkCmd, "-OK-", logInfo);
            logInfo.pass("I initiate TAR");
            logInfo.addScreenCaptureFromBase64String(getBase64(getDriver()), "Screenshot");

//            C:D
            String command3 = "C:D";
            gl.logCommand(logInfo, command3);
            gl.sendCmdValidateResponse(command3, "SEQ  TICKET NBR", logInfo);
            logInfo.addScreenCaptureFromBase64String(getBase64(getDriver()), "Screenshot");


        } catch (AssertionError | Exception e) {
            ExtentReportListener.testStepHandle("FAIL", getDriver(), logInfo, e);
            Assert.fail("This step failed.. so stopping...");
        }
    }

    public void refundTkt(ExtentTest logInfo, String RefundType) {

        try {

            if (RefundType.equalsIgnoreCase("Refund")) {
                //    T-ETREFUND
                String RefundCmd = "T-ETREFUND";
                gl.logCommand(logInfo, RefundCmd);
                gl.sendCmdValidateResponse(RefundCmd, "OK", logInfo);

            } else if (RefundType.equalsIgnoreCase("RefundWithPenality")) {
                //    T-ETREFUND*12345678/$27
                String AdjustCmd = "T-ETREFUND*12345678/$27";
                gl.logCommand(logInfo, AdjustCmd);
                gl.sendCmdValidateResponse(AdjustCmd, "OK", logInfo);

            }else if (RefundType.equalsIgnoreCase("RefundWithCash")) {
                //   T- ETREFUND*5555555555554444/1225/N231/$809.00
                String AdjustCmd = "T-ETREFUND*5555555555554444/1225/N231/$809.00";
                gl.logCommand(logInfo, AdjustCmd);
                gl.sendCmdValidateResponse(AdjustCmd, "OK", logInfo);
            }else if (RefundType.equalsIgnoreCase("RefundByStationDraft")) {
                //   T-ETREFUND*23022300006422/$2175
                String AdjustCmd = "T-ETREFUND*23022300006422/$2175";
                gl.logCommand(logInfo, AdjustCmd);
                gl.sendCmdValidateResponse(AdjustCmd, "OK", logInfo);
            }else if (RefundType.equalsIgnoreCase("RefundByStationDraft")) {
                String ticketno =  mPassengers.get(getDriverID()).get(0).getTicketNumber();
                //   T-ETREFUND*23022300006422/$2175
                String AdjustCmd = "T-ETREFUND*"+ticketno+"/$2175";
                gl.logCommand(logInfo, AdjustCmd);
                gl.sendCmdValidateResponse(AdjustCmd,"OK",  logInfo);
                gl.waitForProfileLoad();
                gl.sendCmdIfRequired(AdjustCmd,"OK",logInfo);
            }
            else if (RefundType.equalsIgnoreCase("RefundWithDefaultCurrency")) {
                //   T-ETREFUND*4412345678901234/1200/$525.
                String AdjustCmd = "T-ETREFUND*4412345678901234/1200/$525.";
                gl.logCommand(logInfo, AdjustCmd);
                gl.sendCmdValidateResponse(AdjustCmd, "OK", logInfo);
            }else if (RefundType.equalsIgnoreCase("RefundAdjustment")) {
                //   T-ETREFUND*4412345678901234/1200/$1.0
                String AdjustCmd = "T-ETREFUND*4412345678901234/1200/$1.0";
                gl.logCommand(logInfo, AdjustCmd);
                gl.sendCmdValidateResponse(AdjustCmd, "OK", logInfo);
            }

            gl.logCommand(logInfo,"IR");
            gl.sendCmdValidateResponse("IR", "PNR RESTRICTED -VIEW ONLY", logInfo);

        } catch (AssertionError | Exception e) {
            ExtentReportListener.testStepHandle("FAIL", getDriver(), logInfo, e);
            Assert.fail("This step failed.. so stopping...");
        }
    }


