            String date = gl.sharesFormatDateFromGUI(pax.getSegmentDate(0));

            String command = "A" + date + pax.getSegmentOriginCity(0) + pax.getSegmentDestinationCity(0) + "9A/R-UA";
            gl.logCommand(logInfo, command);
            gl.sendCmdValidateResponse(command, "UA", "XR IR OR", pax.getSegmentOriginCity(0), logInfo);
            logInfo.pass("I enter A_R command to check redemption availability");

//                    A30JUNSINPTY7A-CM/SQ/R
            command = "A" + date + pax.getSegmentOriginCity(0) + pax.getSegmentDestinationCity(0) + "7A-CM/SQ/R";
            gl.logCommand(logInfo, command);
            gl.sendCmdValidateResponse(command, "XR IR OR", "NO MORE FOR DISPLAY", pax.getSegmentOriginCity(0), logInfo);
            logInfo.pass("I enter A_R command to check redemption availability");

            //                    A30JUNSINPTY7A-UA/SQ/R
