    public void enterVMMLCommandforMassModifyLegEntry(ExtentTest logInfo, String entry) {
        try {
            String command = null;
            Passenger pax = mPassengers.get(getDriverID()).get(0);

            // String flight = pax.getSegmentFlight(0);
            String date1 = gl.sharesFormatDateFromGUI(pax.getSegmentDate(0));
            String date2 = gl.sharesFormatDateFromGUI(pax.getSegmentDate(0) + 5);

            if (entry.equalsIgnoreCase("VMML471/08NOV-10NOVY/YYZAUL160")) {
                command = "VMML471" + "/" + date1 + "-" + date2 + "Y/YYZAUL160";
            } else if (entry.equalsIgnoreCase("VMMA360/10NOV-12NOV.ALL")) {
                command = "VMMA360" + "/" + date1 + "-" + date2 + ".ALL";
            } else if (entry.equalsIgnoreCase("VMML302/10NOV-15NOV/1234567/.ALLIXLON")) {
                command = "VMML302" + "/" + date1 + "-" + date2 + "/1234567/.ALLIXLON";
            } else if (entry.equalsIgnoreCase("VMML360/08NOV-10NOVY/135/Y/.ALLAVS3-5")) {
                command = "VMML360" + "/" + date1 + "-" + date2 + "/135/Y/.ALLAVS3-5";
            } else if (entry.equalsIgnoreCase("VMMF471/10NOV-12NOVY/YYZPTY")) {
                //String flight = pax.getSegmentFlight(0);
                command = "VMMF471/" + date1 + "-" + date2 + "/YYZPTY" + "\n" +
                        "OFFER SEAT SELECTION";
            } else if (entry.equalsIgnoreCase("VMMR300/11NOV-13NOV/1567/")) {
                command = "VMMR300/" + date1 + "-" + date2 + "/1567/" + "\n" +
                        "WATCH OUT FOR GROUP BOOKINGS";
            } else if (entry.equalsIgnoreCase("VMMH302/10NOV-15NOV/246/QSGPTY")) {
                command = "VMMH302/" + date1 + "-" + date2 + "/246/QSGPTY";
            }
            gl.logCommand(logInfo, command);
            if (command.contains("\n")) {
                gl.sendCopiedCmdValidateResponseFormSize2(logInfo, command, "MASS MODIFICATIONS HAVE BEGUN", "PROTECT IS ON - USE /O TO OVERRIDE");
            } else {
                gl.sendCmdValidateResponse(command, "MASS MODIFICATIONS HAVE BEGUN", "PROTECT IS ON - USE /O TO OVERRIDE", logInfo);
            }
        } catch (AssertionError | Exception e) {
            ExtentReportListener.testStepHandle("FAIL", getDriver(), logInfo, e);
            Assert.fail("This step failed.. so stopping...");
        }
    }

