    public void displaySpecialFunctionNameList(ExtentTest logInfo) {
        try {
            Passenger pax = mPassengers.get(getDriverID()).get(0);

            gl.ignoreTRNS(logInfo);

//                  360/11AUGPTY      The below variable 'fltNoDateOrigin' stores in this format
            String fltNoDateOrigin = pax.getSegmentFlight(0) + "/" + gl.sharesFormatDateFromGUI(pax.getSegmentDate(0)) + pax.getSegmentOriginCity(0);

            List<String> commands = new ArrayList<>();

//            LD360/11AUGPTY-A
            commands.add("LD" + fltNoDateOrigin + "-A");   //Allows the agent to obtain an alphabetized primary and secondary name list

//            LD360/10AUGPTY-QCRC1
            commands.add("LD" + fltNoDateOrigin + "-Q" + pax.getPOS() + "1");

//            LD360/Y10AUGPTY-D
            commands.add("LD" + pax.getSegmentFlight(0) + "/" + pax.getCOS() + gl.sharesFormatDateFromGUI(pax.getSegmentDate(0))
                    + pax.getSegmentOriginCity(0) + "-D");   //Display destination name list of all passengers boarding at Origin for all destinations. (FS3400/FS3401)

//            LD360/10AUGPTY-E
            commands.add("LD" + fltNoDateOrigin + "-E");    //Expanded indicator (Required by Expanded Display)

//            LD360/10AUGPTYLAX-D
            commands.add("LD" + fltNoDateOrigin + pax.getSegmentDestinationCity(0) + "-D");

//            LD360/10AUGPTY-EFQTV
            commands.add("LD" + fltNoDateOrigin + "-EFQTV");

//            LD360/10AUGPTY-EWCHR
            commands.add("LD" + fltNoDateOrigin + "-EWCHR");

//            LD360/10AUGPTY-S
            commands.add("LD" + fltNoDateOrigin + "-S");    //This will facilitate the identification of possible name duplicates

//            LD360/10AUGPTY-D*M
            commands.add("LD" + fltNoDateOrigin + "-D*M");  //option to display all the marketing carrier codes for a specific flight or *cc (cc represents actual carrier code) to display the data marketed by specific codeshare carrier

//            LD446/10AUGPTY-D*UA
            commands.add("LD" + fltNoDateOrigin + "-D*UA");  //Specific codeshare partner display

//            LD360/10AUGPTY-Q*MPTY1
            commands.add("LD" + fltNoDateOrigin + "-Q*M" + pax.getSegmentOriginCity(0) + "1");

//            LD360/10AUGPTY-Q*UAPTY1
            commands.add("LD" + fltNoDateOrigin + "-Q*UA" + pax.getSegmentOriginCity(0) + "1");

//            LC360/10AUGPTY-D
            commands.add("LC" + fltNoDateOrigin + "-D");

//            LD360/10AUGPTY-D
            commands.add("LD" + fltNoDateOrigin + "-D");

//            LF360/10AUGPTY-D
            commands.add("LF" + fltNoDateOrigin + "-D");

//            LG360/10AUGPTY-D
            commands.add("LG" + fltNoDateOrigin + "-D");

//            LH360/10AUGPTY-D
            commands.add("LH" + fltNoDateOrigin + "-D");

//            LI360/10AUGPTY-D
            commands.add("LI" + fltNoDateOrigin + "-D");   // Display an inbound connection list for Consolidated Flight

//            LM360/10AUGPTY-D
            commands.add("LM" + fltNoDateOrigin + "-D");

//            LN360/10AUGPTY-D
            commands.add("LN" + fltNoDateOrigin + "-D");

//            LO360/10AUGPTY-D
            commands.add("LO" + fltNoDateOrigin + "-D");  // Display an outbound connection list for Consolidated Flight

//            LP360/10AUGPTY-D
            commands.add("LP" + fltNoDateOrigin + "-D");

//            LR360/10AUGPTY-D
            commands.add("LR" + fltNoDateOrigin + "-D");

//            LS360/10AUGPTY-D
            commands.add("LS" + fltNoDateOrigin + "-D");

//            LU360/10AUGPTY-D
            commands.add("LU" + fltNoDateOrigin + "-D");

//            LW360/10AUGPTY-D
            commands.add("LW" + fltNoDateOrigin + "-D");

//            LX360/10AUGPTY-D
            commands.add("LX" + fltNoDateOrigin + "-D");

//            LY360/10AUGPTY-D
            commands.add("LY" + fltNoDateOrigin + "-D");

//             L*
            commands.add("L*");

//            LD306/11AUGLAXBOG/PTY-D
            commands.add("LD" + fltNoDateOrigin + pax.getSegmentDestinationCity(0) + "-D");

            for (int i = 0; i < commands.size(); i++) {
                gl.logCommand(logInfo, commands.get(i));
                gl.sendCmdValidateResponse(commands.get(i), "0" + pax.getSegmentFlight(0), "PLACED ON Q", logInfo);
                logInfo.pass("I enter L_ command to display special function name list");
            }

        } catch (AssertionError | Exception e) {

            ExtentReportListener.testStepHandle("FAIL", getDriver(), logInfo, e);
            Assert.fail("This step failed.. so stopping...");
        }
    }

