    public void bestBuyForSpecificSegments(ExtentTest logInfo, String segments) {
        try {
//                LA$R#PADT/CHD08#S1/4
            String command = "LA$R|P";

            for (Passenger pax : mPassengers.get(getDriverID())) {

                if (pax.getPaxType().equalsIgnoreCase("ADT")) {
                    command = command + "ADT";
                } else if (pax.getPaxType().equalsIgnoreCase("CHD")) {
                    command = command + ("CHD" + pax.getDOB());
                }else if (pax.getPaxType().equalsIgnoreCase("INS")) {
                    command = command + ("INS" );
                }

            }

            command = command + "|S" + segments;
            gl.logCommand(logInfo, command);
            gl.sendCmdValidateResponse(command, "USD FARE", "TAX-USD", logInfo);

            String command1 = "FF";
            gl.logCommand(logInfo, command1);
            gl.sendCmdValidateResponse(command1, "FARE QUOTE  1 FILED", logInfo);

            String command2 = "6P";
            gl.logCommand(logInfo, command2);
            gl.sendCmdValidateResponse(command2, "6P *", logInfo);

            String command3 = "ER";
            gl.logCommand(logInfo, command3);
            gl.sendCmdValidateResponse(command3, "*FQ", "FARE QUOTE-AUTO PRICED", logInfo);
            logInfo.pass("I enter LA$R|P_ command to get the best buy fare quote for the passengers for specific segments");

            if (!isharesPageObjects2.SHARES_RESPONSE.getText().contains("FARE QUOTE-AUTO PRICED")) {
                gl.sendCmdValidateResponse("MD", "FARE QUOTE-AUTO PRICED", logInfo);
            }

        } catch (AssertionError | Exception e) {

            ExtentReportListener.testStepHandle("FAIL", getDriver(), logInfo, e);
            Assert.fail("This step failed.. so stopping...");
        }
    }

