    public void captureTheTaxValues(ExtentTest logInfo) {
        String taxValue = null;
        String taxCode = null;
        String tax1 = null;
        String tax2 = null;
        ArrayList<String> taxes = new ArrayList<>();

        try {
            Passenger pax = mPassengers.get(getDriverID()).get(0);

            gl.logCommand(logInfo, ignoreAndRetrieve);
            gl.sendCmdValidateResponse(ignoreAndRetrieve, pax.getPnr(), logInfo);

            String response = isharesPageObjects2.SHARES_RESPONSE.getText();

            if (!response.contains("USD")) {
                gl.sendCmdValidateResponse("MD", logInfo);
            }
            response = isharesPageObjects2.SHARES_RESPONSE.getText();

            String taxValuesLine = null;
            String[] rows = response.split("\n");

            for (int i = 0; i < rows.length; i++) {
                if (rows[i].contains("USD")) {
                    taxValuesLine = rows[i];
                    break;
                }
            }

            String Taxes[] = taxValuesLine.split(" ");

            for (int j = 0; j < Taxes.length; j++) {
                System.out.println("TAX: " + Taxes[j]);
            }

            for (int i = 4; i < Taxes.length - 1; i++) {
                if (!Taxes[i].equalsIgnoreCase("")) {
                    taxCode = Taxes[i].substring(0, 2);
                    System.out.println("TAXCODE: " + taxCode);
                    taxValue = Taxes[i].substring(2);

                    int length = taxValue.length();
                    if (length > 5) {
                        tax1 = taxValue.substring(0, 2);
                        tax2 = taxValue.substring(3);
                        taxes.add(taxCode + tax1 + tax2);
                    } else {
                        tax1 = taxValue.substring(0);
                        taxes.add(taxCode + tax1);
                    }
                }
            }
            pax.setListOfTaxes(taxes);

            for (int k = 0; k < taxes.size(); k++) {
                System.out.println("TAXES: " + taxes.get(k));
            }

        } catch (AssertionError | Exception e) {
            ExtentReportListener.testStepHandle("FAIL", getDriver(), logInfo, e);
            Assert.fail("This step failed.. so stopping...");
        }
    }


