    public void assignShipmentOfDifferentEquipment(ExtentTest logInfo, String status) {

//        6:*A703/8JUNPTY

        Passenger pax = mPassengers.get(getDriverID()).get(0);
        String Origin = pax.getSegmentOriginCity(0);
        int totalPax = mPassengers.get(getDriverID()).size();

        String flight = pax.getSegmentFlight(0);
        String Date = gl.sharesFormatDateFromGUI(pax.getSegmentDate(0));

        try {

            isharesPageObjects2.FORMSIZE_DROPDOWN.click();
            isharesPageObjects2.FORMSIZE_SELECT2.click();
            gl.waitForProfileLoad();
            String command = "6:*A" + flight + "/" + Date + Origin;
            gl.logCommand(logInfo, command);
            gl.sendCmdForForm2ValidateResponse(command, logInfo);
            logInfo.addScreenCaptureFromBase64String(getBase64(getDriver()), "Screenshot");

            String EqpNumber;
            String response = isharesPageObjects2.SHARES_RESPONSE.getText();
            EqpNumber = response.substring(response.indexOf(flight) + 4,response.indexOf(flight) + 10).trim();

            String equipNumbers[] = {"P", "L", "D", "9"};
            String letter = EqpNumber.substring(2);
            int index = 0;

            for (int i = 0; i < equipNumbers.length; i++) {

                if (!equipNumbers[i].equalsIgnoreCase(letter)) {         //if any of the equipNumbers in the array is not equal to the letter then we take that index
                    index = i;
                }
            }

            EqpNumber = EqpNumber.substring(0, 2) + equipNumbers[index];

            String command2 = "6:I*F" + EqpNumber;
            gl.logCommand(logInfo, command2);
            gl.sendCmdForForm2ValidateResponse(command2, logInfo);
            logInfo.addScreenCaptureFromBase64String(getBase64(getDriver()), "Screenshot");
            String FleetNumber;
            if (globalConstants.testEnv.equalsIgnoreCase("sharesCURL")) {
                FleetNumber = isharesPageObjects2.SHARES_RESPONSE.getText().substring(128, 132);
            } else {
                FleetNumber = isharesPageObjects2.SHARES_RESPONSE.getText().substring(130, 134);
            }

            System.out.println("Flight ship index " + FleetNumber);
            String command3 = "6:CA" + Date + "\n"
                    + flight + Origin + FleetNumber;
            gl.logCommand(logInfo, command3);
            isharesPageObjects2.FORMSIZE_SELECT2_TEXTAREA.click();
            gl.copyCmdToClipboardAndPaste(command3, isharesPageObjects2.FORMSIZE_SELECT2_TEXTAREA);
            isharesPageObjects2.SEND_ISHARES.click();
            gl.waitForProfileLoad();
            logInfo.addScreenCaptureFromBase64String(getBase64(getDriver()), "Screenshot");
            response = isharesPageObjects2.SHARES_RESPONSE.getText();
            Assert.assertTrue(response.contains("SHIP NOT ASSIGNED"));

            isharesPageObjects2.FORMSIZE_DROPDOWN.click();
            isharesPageObjects2.FORMSIZE_SELECT1.click();

            if (status.equalsIgnoreCase("Accept")) {
//                    6:CE441/12JULPTY.YES#B
                String command4 = "6:CE" + flight + "/" + Date + Origin + "." + "YES|B";

                gl.logCommand(logInfo, command4);
                gl.sendCmdValidateResponse(command4, "*SHIP ASSIGNED*", logInfo);
                logInfo.addScreenCaptureFromBase64String(getBase64(getDriver()), "Screenshot");
            } else if (status.equalsIgnoreCase("Reject")) {
//                    6:CE441/12JULPTY.NO
                String command4 = "6:CE" + flight + "/" + Date + Origin + "." + "NO";

                gl.logCommand(logInfo, command4);
                gl.sendCmdValidateResponse(command4, "OK", "PENDING SHIP ASSIGN/CHANGE REJECTED", logInfo);
                logInfo.addScreenCaptureFromBase64String(getBase64(getDriver()), "Screenshot");
            } else if (status.equalsIgnoreCase("AcceptChangeGauge")) {
//                   6:CE441/12JULPTY.YES#G
                String command4 = "6:CE" + flight + "/" + Date + Origin + "." + "YES|G";
                gl.logCommand(logInfo, command4);
                gl.sendCmdValidateResponse(command4, "*SHIP ASSIGNED*", logInfo);
                logInfo.addScreenCaptureFromBase64String(getBase64(getDriver()), "Screenshot");
            }
        } catch (AssertionError | Exception e) {
            ExtentReportListener.testStepHandle("FAIL", getDriver(), logInfo, e);
            Assert.fail("This step failed.. so stopping...");
        }
    }



