    public void addRemarkToPnr(ExtentTest logInfo, String RemarkType) {

        try {
            if (RemarkType.equalsIgnoreCase("VIP")) {
                String command = "3OSI CM PAX VIP";
                gl.logCommand(logInfo, command);
                gl.sendCmdValidateResponse(command, command + " *", logInfo);
                logInfo.pass("I add remark to the pnr");

            } else if (RemarkType.equalsIgnoreCase("DeleteRemark")) {
                gl.logCommand(logInfo, "*" + mPassengers.get(getDriverID()).get(0).getPnr());
                gl.sendCmdValidateResponse("*" + mPassengers.get(getDriverID()).get(0).getPnr(), logInfo);

                String response = isharesPageObjects2.SHARES_RESPONSE.getText();
                response = response.substring(response.indexOf("OSI") - 2, response.indexOf("OSI") - 1);

                String command = "3" + response + "@";
                gl.logCommand(logInfo, command);
                gl.sendCmdValidateResponse(command, "NEXT REPLACES GEN FAX", logInfo);
                logInfo.pass("I delete remark to the pnr");

            } else if (RemarkType.equalsIgnoreCase("InvalidRemark")) {
                gl.logCommand(logInfo, "AOSI CM PAX VIP");
                gl.sendCmdValidateResponse("AOSI CM PAX VIP", "INVLD DATE/BRD/OFF", logInfo);
            } else if (RemarkType.equalsIgnoreCase("SVC")) {
                gl.logCommand(logInfo, "5SVC VS///12436C1.AT GATE 23X 03");
                gl.sendCmdValidateResponse("5SVC VS///12436C1.AT GATE 23X 03", "*", logInfo);
            } else if (RemarkType.equalsIgnoreCase("DWR_Add")) {
                Passenger pax = mPassengers.get(getDriverID()).get(0);

                String command = "6:DWR" + pax.getSegmentFlight(0) + "/" + gl.sharesFormatDateFromGUI(pax.getSegmentDate(0))
                        + pax.getSegmentOriginCity(0) + "\n" + "COMMENT ADDED";
                gl.logCommand(logInfo, command);
                gl.sendCopiedCmdValidateResponse2(logInfo, command, "OK - REMARKS ADDED");
            } else if (RemarkType.equalsIgnoreCase("DWR_Modify")) {
                Passenger pax = mPassengers.get(getDriverID()).get(0);

                String command = "6:DWR" + pax.getSegmentFlight(0) + "/" + gl.sharesFormatDateFromGUI(pax.getSegmentDate(0))
                        + pax.getSegmentOriginCity(0) + "|@1" + "\n" + "MODIFIED";
                gl.logCommand(logInfo, command);
                gl.sendCopiedCmdValidateResponse2(logInfo, command, "OK - REMARKS CHANGED");
            } else if (RemarkType.equalsIgnoreCase("OSIREMARKS")) {
                String command = "3OSI CM OSI REMARKS";
                gl.logCommand(logInfo, command);
                gl.sendCmdValidateResponse(command, command + " *", logInfo);
                logInfo.pass("I add remark to the pnr");
            }


            if (RemarkType.equalsIgnoreCase("DeleteRemark")) {

                String pnr = mPassengers.get(getDriverID()).get(0).getPnr();
                gl.logCommand(logInfo, "6P#ER");
                gl.sendCmdValidateResponse("6P#ER", pnr, "6P#ER *", logInfo);

                gl.sendCmdIfRequired("ER", pnr, logInfo);

                String response = isharesPageObjects2.SHARES_RESPONSE.getText();
                if (response.contains("OSI")) {
                    Assert.fail();
                }
            }
        } catch (AssertionError | Exception e) {

            ExtentReportListener.testStepHandle("FAIL", getDriver(), logInfo, e);
            Assert.fail("This step failed.. so stopping...");
        }

    }

