    public String addIncapacitatedMessage(ExtentTest logInfo, String origin, int paxIndex) throws IOException {
//        6:SI444/05MARIAD-ZIG/SHARK

        gl.waitForProfileLoad();
        Passenger pax = mPassengers.get(getDriverID()).get(paxIndex);

        isharesPageObjects2.FORMSIZE_DROPDOWN.click();
        isharesPageObjects2.FORMSIZE_SELECT24.click();
        String cmd = null;
        if (pax.getPaxType().equalsIgnoreCase("ADT") || pax.getPaxType().equalsIgnoreCase("INS")
                || pax.getPaxType().equalsIgnoreCase("NRSA")) {
            cmd = "6:SI" + mPassengers.get(getDriverID()).get(0).getSegmentFlight(0)
                    + "/" + gl.sharesFormatDateFromGUI(mPassengers.get(getDriverID()).get(0).getSegmentDate(0))
                    + origin + "-" + pax.getfName()
                    + "/" + pax.getlName()
                    + "\n" + "B0";
        } else if (pax.getPaxType().equalsIgnoreCase("CHD")) {
            cmd = "6:SI" + mPassengers.get(getDriverID()).get(0).getSegmentFlight(0)
                    + "/" + gl.sharesFormatDateFromGUI(mPassengers.get(getDriverID()).get(0).getSegmentDate(0))
                    + origin + "-" + pax.getfName()
                    + "/" + pax.getlName()
                    + "\n" + "B0C1";

        }else if (pax.getPaxType().equalsIgnoreCase("INF")) {
            cmd = "6:SI" + mPassengers.get(getDriverID()).get(0).getSegmentFlight(0)
                    + "/" + gl.sharesFormatDateFromGUI(mPassengers.get(getDriverID()).get(0).getSegmentDate(0))
                    + origin + "-" + pax.getAccompaniedPaxDetails().getfName()
                    + "/" + pax.getAccompaniedPaxDetails().getlName()
                    + "\n" + "I1B0";
        } else if (pax.getPaxType().equalsIgnoreCase("FQTV")) {
            cmd = "6:SI" + mPassengers.get(getDriverID()).get(0).getSegmentFlight(0)
                    + "/" + gl.sharesFormatDateFromGUI(mPassengers.get(getDriverID()).get(0).getSegmentDate(0))
                    + origin + "-" + pax.getfName()
                    + "/" + pax.getlName()
                    + "\n" + "B0";
        }

        gl.logCommand(logInfo, cmd);
        logInfo.addScreenCaptureFromBase64String(getBase64(getDriver()), "Screenshot");

        System.out.println(cmd);
        return cmd;
    }


