    public void checkQueueList(ExtentTest logInfo, String cmdType, String airport) {

        try {
            String checkQueueList;
            if (cmdType.contains("QCM")) {
                gl.ignoreTRNS(logInfo);
                //   QCM/PTY
                checkQueueList = "QCM/" + airport;
                gl.logCommand(logInfo, checkQueueList);
                if (airport.equals("TLC"))
                    gl.sendCmdValidateResponse(checkQueueList, "INVLD CTY/AIRPORT CODE", logInfo);
                else
                    gl.sendCmdValidateResponse(checkQueueList, "GEN MSG", logInfo);
            } else if (cmdType.contains("QM")) {
                gl.ignoreTRNS(logInfo);
                //   QM/PTY
                checkQueueList = "QM/" + airport;
                gl.logCommand(logInfo, checkQueueList);
                if (airport.equals("TLC"))
                    gl.sendCmdValidateResponse(checkQueueList, "INVLD CTY/AIRPORT CODE", logInfo);
                else
                    gl.sendCmdValidateResponse(checkQueueList, "MSG Q MT", "QD", "REMARKS","CM", logInfo);
            }

        } catch (AssertionError | Exception e) {
            ExtentReportListener.testStepHandle("FAIL", getDriver(), logInfo, e);
            Assert.fail("This step failed.. so stopping...");
        }
    }


