    public void TTYMessageBasicAirlinePnrWithASC(ExtentTest logInfo, String SystemType) {
        try {

            //            Y
            //            CLTYSCM
            //            .MUCRM1A 251335
            //            ASC
            //            MUC1A QFO4ZH
            //            1ERTYU/LLLL
            //            CM0120Y28JULPTYMEXRR1

            Passenger pax = mPassengers.get(getDriverID()).get(0);
            int TotalSegments = mPassengers.get(getDriverID()).get(0).getTotalSegments();
            String totalSegments = String.valueOf(TotalSegments);

            String Line2;   //PTYRMCM
            if (globalConstants.testEnv.equalsIgnoreCase("sharesURL")) {
                Line2 = "PTYRMCM";
            } else {
                Line2 = "CLTYSCM";
            }

            String UniquePnr = GenerateUniquePnr(logInfo);

            String BasicAirlinePnr = "Y" + "\n" +
                    Line2 + "\n" +
                    ".MUCRM1" + SystemType + " 251335" + "\n" +
                    "ASC" + "\n" + "MUC1" + SystemType + " " + UniquePnr + "\n" +
                    GDSPnrTotalPax() + GDSPnrTotalSegments(totalSegments);

            isharesPageObjects2.FORMSIZE_DROPDOWN.click();
            isharesPageObjects2.FORMSIZE_SELECT24.click();

            gl.logCommand(logInfo, BasicAirlinePnr);
            System.out.println("BaseCommand " + BasicAirlinePnr);
            gl.copyCmdToClipboardAndPaste(BasicAirlinePnr, isharesPageObjects2.FORMSIZE_SELECT2_TEXTAREA);

            isharesPageObjects2.SEND_ISHARES.click();
            logInfo.pass("I passed TTY message");
            logInfo.addScreenCaptureFromBase64String(getBase64(getDriver()), "Screenshot");
            gl.waitForProfileLoad();
            String response = isharesPageObjects2.SHARES_RESPONSE.getText();
            gl.logResponse(logInfo, response);
            Assert.assertTrue(response.contains("MESSAGE ACCEPTED"));

            isharesPageObjects2.FORMSIZE_DROPDOWN.click();
            isharesPageObjects2.FORMSIZE_SELECT1.click();

            checkTTYPNR(logInfo, UniquePnr);

            logInfo.pass("I enter TTY message to generate PNR");
            logInfo.addScreenCaptureFromBase64String(getBase64(getDriver()), "Screenshot");

        } catch (AssertionError | Exception e) {

            ExtentReportListener.testStepHandle("FAIL", getDriver(), logInfo, e);
            Assert.fail("This step failed.. so stopping...");
        }
    }

    public void TTYMessageBasicAirlinePnrbyMessageType(ExtentTest logInfo, String SystemType, String MessageType) {
        try {

            //            Y
            //            PTYRMCM
            //           .MUCRM1A 251335
            //            MUC1A SUSUSQ
            //            1JHON/KIM
            //            CM120Y12APRPTYMEXNN1

            int TotalSegments = mPassengers.get(getDriverID()).get(0).getTotalSegments();
            String totalSegments = String.valueOf(TotalSegments);

            String Line2 ;   //PTYRMCM
            if (globalConstants.testEnv.equalsIgnoreCase("sharesURL") || globalConstants.testEnv.equalsIgnoreCase("sharesD3URL")) {
                Line2 = "CLTYSCM";
            } else {
                Line2 = "PTYRMCM";
            }


            String UniquePnr = GenerateUniquePnr(logInfo);
            String BasicAirlinePnr = "";

            if (MessageType.equals("HDQ")){
                BasicAirlinePnr = "Y" + "\n" +
                        "PTYRMCM" + "\n" +
                        "." + MessageType + "RM" + SystemType + " 121224" + "\n" +
                        "HDQ" + SystemType + " " + UniquePnr + "\n" +
                        GDSPnrTotalPax() + GDSPnrTotalSegments(totalSegments);
            } else if (MessageType.equals("InvalidAVS_BB")){
                BasicAirlinePnr = "Y" + "\n" +
                        Line2 + "\n" +
                        ".MUCRM" + SystemType + "\n" +
                        "MUC1A3QQAZ" + "\n" +
                        "MUC"+SystemType+"3QQAZ" + "\n" +
                        GDSPnrTotalPax() + GDSPnrTotalSegments(totalSegments).replace("NN", "SS");
            }
            else {
                BasicAirlinePnr = "Y" + "\n" +
                        Line2 + "\n" +
                        "." + MessageType + "RM" + SystemType + " 251335" + "\n" +
                        MessageType + SystemType + " " + UniquePnr + "\n" +
                        GDSPnrTotalPax() + GDSPnrTotalSegments(totalSegments);
            }

            isharesPageObjects2.FORMSIZE_DROPDOWN.click();
            isharesPageObjects2.FORMSIZE_SELECT24.click();

            gl.logCommand(logInfo, BasicAirlinePnr);
            System.out.println("BaseCommand " + BasicAirlinePnr);
            gl.copyCmdToClipboardAndPaste(BasicAirlinePnr, isharesPageObjects2.FORMSIZE_SELECT2_TEXTAREA);

            isharesPageObjects2.SEND_ISHARES.click();
            gl.waitForProfileLoad();
            logInfo.pass("I passed TTY message");
            logInfo.addScreenCaptureFromBase64String(getBase64(getDriver()), "Screenshot");

            String response = isharesPageObjects2.SHARES_RESPONSE.getText();
            gl.logResponse(logInfo, response);
            Assert.assertTrue(response.contains("MESSAGE ACCEPTED"));

            isharesPageObjects2.FORMSIZE_DROPDOWN.click();
            isharesPageObjects2.FORMSIZE_SELECT1.click();

            if (!MessageType.equals("InvalidAVS_BB")) {

                gl.waitForProfileLoad();
                checkTTYPNR(logInfo, UniquePnr);
            }

            logInfo.pass("I enter TTY message to generate PNR");
            logInfo.addScreenCaptureFromBase64String(getBase64(getDriver()), "Screenshot");

        } catch (AssertionError | Exception e) {

            ExtentReportListener.testStepHandle("FAIL", getDriver(), logInfo, e);
            Assert.fail("This step failed.. so stopping...");
        }
    }



