    public void advancePaxInfo(ExtentTest logInfo) {
        try {
            Passenger pax = mPassengers.get(getDriverID()).get(0);
            int Totalpax = mPassengers.get(getDriverID()).size();

            isharesPageObjects2.FORMSIZE_DROPDOWN.click();
            isharesPageObjects2.FORMSIZE_SELECT1.click();

            for (int i = 1; i <= Totalpax; i++) {

                if (pax.getIsGroupPNR()) {
                    gl.logCommand(logInfo, "*AP" + (i + 1));
                    gl.sendCmdValidateResponse("*AP" + (i + 1), "ADVANCED PASSENGER INFORMATION", logInfo);

                }else if (pax.getIsCorporatePNR()) {
                    gl.logCommand(logInfo, "*AP" + (i + 1));
                    gl.sendCmdValidateResponse("*AP" + (i + 1), "ADVANCED PASSENGER INFORMATION", logInfo);
                }
                else {
                    gl.logCommand(logInfo, "*AP" + i);
                    gl.sendCmdValidateResponse("*AP" + i, "ADVANCED PASSENGER INFORMATION", logInfo);
                }
            }
        } catch (AssertionError | Exception e) {
            ExtentReportListener.testStepHandle("FAIL", getDriver(), logInfo, e);
            Assert.fail("This step failed.. so stopping...");
        }
    }

