    public void sharesCheckinESTA(ExtentTest logInfo, String origin) {
        try {
            Passenger pax = mPassengers.get(getDriverID()).get(0);
            boolean repeatTrns;

            gl.ignoreTRNS(logInfo);

            for (int i = 0; i < mPassengers.get(getDriverID()).size(); i++) {
                repeatTrns = true;
                String BagCount ;

//                ***** Entering Base command *****
                while (repeatTrns) {
                    gl.copyCmdToClipboardAndPaste(addCheckinCmd(origin, i), isharesPageObjects2.FORMSIZE_SELECT2_TEXTAREA);
                    gl.waitForProfileLoad();
                    int BaggageInfo = addCheckinCmd(origin, i).indexOf("\n") + 1;
                    BagCount = addCheckinCmd(origin, i).substring(BaggageInfo);
                    System.out.println(BagCount + "BagCount");

                    isharesPageObjects2.SEND_ISHARES.click();
                    gl.waitForProfileLoad();
                    logInfo.addScreenCaptureFromBase64String(getBase64(getDriver()), "Screenshot");
                    String response = isharesPageObjects2.SHARES_RESPONSE.getText();

                    if (response.contains("NOT OPEN")) {
                        openFlight(logInfo, mPassengers.get(getDriverID()).get(0).getSegmentFlight(0), gl.sharesFormatDateFromGUI(mPassengers.get(getDriverID()).get(0).getSegmentDate(0)), origin);
                        gl.ignoreTRNS(logInfo);
                    } else if (response.contains("PASSENGER DISPLAY") || response.contains("UNABLE TO RETRIEVE FDR-CHK DATA BASE")) {
                        Assert.fail();
                    } else if (response.contains("UNDELIVERED MESSAGES")) {
                        BaggageInfo = addCheckinCmd(origin, i).indexOf("\n") + 1;
                    } else {
                        repeatTrns = false;
                    }

                }

                //***********Multiple item error*************//
                String response = isharesPageObjects2.SHARES_RESPONSE.getText();

                if (response.contains("MULTIPLE ITEMS")) {
                   
                    String response1 = isharesPageObjects2.SHARES_RESPONSE.getText();
                    
                    //Capturing ID for the PNR
                    int index = response1.indexOf(mPassengers.get(getDriverID()).get(0).getPnr());
                    String indexVal = response1.substring((index - 27), (index - 24)).trim();

                    String MultiListCmd = "6:LK-" + indexVal ;

                    gl.logCommand(logInfo, MultiListCmd);
                    gl.copyCmdToClipboardAndPaste(MultiListCmd, isharesPageObjects2.FORMSIZE_SELECT2_TEXTAREA);
                    
                    isharesPageObjects2.SEND_ISHARES.click();
                    gl.waitForProfileLoad();
                    logInfo.addScreenCaptureFromBase64String(getBase64(getDriver()), "Screenshot");
                }


//                    *** PRIMARY DETAILS FOR OTHER PAX ***
                String IncompleteADCInfo;
                if (globalConstants.testEnv.equalsIgnoreCase("sharesCURL")) {
                    IncompleteADCInfo = isharesPageObjects2.SHARES_RESPONSE.getText();
                } else {
                    IncompleteADCInfo = isharesPageObjects2.INPUT_TEXT_AREA_ROWS24.getText();
                }
                System.out.println(IncompleteADCInfo);
                String CompleteADCInfo = add_PrimaryADCESTA(IncompleteADCInfo, i);
                System.out.println(CompleteADCInfo);
                while (!validatePrimaryADCESTA(CompleteADCInfo, logInfo))  //to check Primary details are entered properly or not
                {
                    CompleteADCInfo = reformPrimaryADCESTA(i);

                }
                logInfo.pass("Primary Document Details entered for other PAX");
                logInfo.addScreenCaptureFromBase64String(getBase64(getDriver()), "Screenshot");

                //       **** SECONDARY DOCUMENT DETAILS for other PAX ****
                if (globalConstants.testEnv.equalsIgnoreCase("sharesCURL")) {
                    if (isharesPageObjects2.SHARES_RESPONSE.getText().contains("US DESTINATION ADDRESS")) {
                        String IncompleteDoctypeInfo = isharesPageObjects2.SHARES_RESPONSE.getText();
                        String CompleteDoctypeInfo = add_SecondaryADCESTA(IncompleteDoctypeInfo);
                        System.out.println(CompleteDoctypeInfo + "\n");
                        while (!validateSecondaryADCESTA(CompleteDoctypeInfo, logInfo))  //to check Secondary details are entered properly or not
                        {
                            CompleteDoctypeInfo = reformSecondaryADC();

                        }
                    }
                } else {
                    if (isharesPageObjects2.INPUT_TEXT_AREA_ROWS24.getText().contains("US DESTINATION ADDRESS")) {
                        String IncompleteDoctypeInfo = isharesPageObjects2.INPUT_TEXT_AREA_ROWS24.getText();
                        String CompleteDoctypeInfo = add_SecondaryADCESTA(IncompleteDoctypeInfo);
                        System.out.println(CompleteDoctypeInfo + "\n");
                        while (!validateSecondaryADCESTA(CompleteDoctypeInfo, logInfo))  //to check Secondary details are entered properly or not
                        {
                            CompleteDoctypeInfo = reformSecondaryADC();

                        }
                    }
                }

            }
            mText.put(getDriverID(), isharesPageObjects2.SHARES_RESPONSE.getText());
            isharesPageObjects2.FORMSIZE_DROPDOWN.click();
            isharesPageObjects2.FORMSIZE_SELECT1.click();
        } catch (AssertionError | Exception e) {
            ExtentReportListener.testStepHandle("FAIL", getDriver(), logInfo, e);
            Assert.fail("This step failed.. so stopping...");
        }
    }

    public String add_PrimaryADCESTA(String IncompleteADCInfo, int paxIndex) {

        Passenger pax = mPassengers.get(getDriverID()).get(paxIndex);
        String[] S1 = IncompleteADCInfo.split("\n");
        String baseCommand;
        String fName,lName;

        if (globalConstants.testEnv.equalsIgnoreCase("sharesCURL")) {
            baseCommand = S1[1].substring(1) + "\n" + S1[2];
        } else {
            baseCommand = S1[0] + "\n" + S1[1];

        }

        if(pax.getPaxType().equalsIgnoreCase("INF"))
        {
            fName = pax.getAccompaniedPaxDetails().getfName();
            lName = pax.getAccompaniedPaxDetails().getlName();
        }
        else
        {
            fName = pax.getfName();
            lName = pax.getlName();
        }

        String givenName = fName.toUpperCase() + generateBlankSpace(fName.length()) + "* GIVEN NAMES";
        String lastName = lName.toUpperCase() + generateBlankSpace(lName.length()) + "* LAST NAME";
        String DOB = pax.getDOB() + generateBlankSpace(6) + "* DATE OF BIRTH";   //YYMMDD
        String Gender = "M" + generateBlankSpace(1) + "* GENDER";
        String nationality = pax.getCountryCode() + generateBlankSpace(2) + "* NATIONALITY";
        String countryOfResidence = pax.getCountryCode() + generateBlankSpace(2) + "* COUNTRY OF RESIDENCE";
        String docType = "P" + generateBlankSpace(1) + "* DOCUMENT TYPE";
        String docNumber = pax.getDocNumber() + generateBlankSpace(6) + "* DOCUMENT NUMBER";
        String countryIssuance = pax.getCountryCode() + generateBlankSpace(2) + "* COUNTRY OF ISSUANCE";
        String expDate = "280210" + generateBlankSpace(6) + "* EXPIRATION DATE";  //YYMMDD

        String ADCinfo = baseCommand;

        ADCinfo = ADCinfo + (IncompleteADCInfo.contains("GIVEN NAMES") ? ("\n" + givenName) : "");
        ADCinfo = ADCinfo + (IncompleteADCInfo.contains("LAST NAME") ? ("\n" + lastName) : "");
        ADCinfo = ADCinfo + (IncompleteADCInfo.contains("DATE OF BIRTH") ? ("\n" + DOB) : "");
        ADCinfo = ADCinfo + (IncompleteADCInfo.contains("GENDER") ? ("\n" + Gender) : "");
        ADCinfo = ADCinfo + (IncompleteADCInfo.contains("NATIONALITY") ? ("\n" + nationality) : "");
        ADCinfo = ADCinfo + (IncompleteADCInfo.contains("COUNTRY OF RESIDENCE") ? ("\n" + countryOfResidence) : "");
        ADCinfo = ADCinfo + (IncompleteADCInfo.contains("DOCUMENT TYPE") ? ("\n" + docType) : "");
        ADCinfo = ADCinfo + (IncompleteADCInfo.contains("DOCUMENT NUMBER") ? ("\n" + docNumber) : "");
        ADCinfo = ADCinfo + (IncompleteADCInfo.contains("COUNTRY OF ISSUANCE") ? ("\n" + countryIssuance) : "");
        ADCinfo = ADCinfo + (IncompleteADCInfo.contains("EXPIRATION DATE") ? ("\n" + expDate) : "");
        ADCinfo = ADCinfo + (IncompleteADCInfo.contains("SCR") ? ("\n" + "SCR:") : "");

        return ADCinfo;

    }

    public String reformPrimaryADCESTA(int paxIndex) {

        Passenger pax = mPassengers.get(getDriverID()).get(paxIndex);

        String MissingADCInfo;
        String[] S1;
        String baseCommand;
        String fName,lName;

        if (globalConstants.testEnv.equalsIgnoreCase("sharesCURL")) {
            MissingADCInfo = isharesPageObjects2.SHARES_RESPONSE.getText();
            S1 = MissingADCInfo.split("\n");
            baseCommand = S1[1].substring(1) + "\n" + S1[2];
        } else {
            MissingADCInfo = isharesPageObjects2.INPUT_TEXT_AREA_ROWS24.getText();
            S1 = MissingADCInfo.split("\n");
            baseCommand = S1[0] + "\n" + S1[1];
        }

        if(pax.getPaxType().equalsIgnoreCase("INF"))
        {
            fName = pax.getAccompaniedPaxDetails().getfName();
            lName = pax.getAccompaniedPaxDetails().getlName();
        }
        else
        {
            fName = pax.getfName();
            lName = pax.getlName();
        }

//        ******** Original Set ********
        String givenName = fName.toUpperCase() + generateBlankSpace(fName.length()) + "* GIVEN NAMES";
        String lastName = lName.toUpperCase() + generateBlankSpace(lName.length()) + "* LAST NAME";
        String DOB = pax.getDOB() + generateBlankSpace(6) + "* DATE OF BIRTH";   //YYMMDD
        String Gender = "M" + generateBlankSpace(1) + "* GENDER";
        String nationality = pax.getCountryCode() + generateBlankSpace(2) + "* NATIONALITY";
        String countryOfResidence = pax.getCountryCode() + generateBlankSpace(2) + "* COUNTRY OF RESIDENCE";
        String city = pax.getCountryCode() + generateBlankSpace(2) + "* CITY";
        String docType = "P" + generateBlankSpace(1) + "* DOCUMENT TYPE";
        String docNumber = pax.getDocNumber() + generateBlankSpace(6) + "* DOCUMENT NUMBER";
        String countryIssuance = pax.getCountryCode() + generateBlankSpace(2) + "* COUNTRY OF ISSUANCE";
        String expDate = "280210" + generateBlankSpace(6) + "* EXPIRATION DATE";  //YYMMDD

        String ADCinfo = baseCommand;
        ADCinfo = ADCinfo + (MissingADCInfo.contains("GIVEN NAMES") ? ("\n" + givenName) : "");
        ADCinfo = ADCinfo + (MissingADCInfo.contains("LAST NAME") ? ("\n" + lastName) : "");
        ADCinfo = ADCinfo + (MissingADCInfo.contains("DATE OF BIRTH") ? ("\n" + DOB) : "");
        ADCinfo = ADCinfo + (MissingADCInfo.contains("GENDER") ? ("\n" + Gender) : "");
        ADCinfo = ADCinfo + (MissingADCInfo.contains("NATIONALITY") ? ("\n" + nationality) : "");
        ADCinfo = ADCinfo + (MissingADCInfo.contains("COUNTRY OF RESIDENCE") ? ("\n" + countryOfResidence) : "");
        ADCinfo = ADCinfo + (MissingADCInfo.contains("CITY") ? ("\n" + city) : "");
        ADCinfo = ADCinfo + (MissingADCInfo.contains("DOCUMENT TYPE") ? ("\n" + docType) : "");
        ADCinfo = ADCinfo + (MissingADCInfo.contains("DOCUMENT NUMBER") ? ("\n" + docNumber) : "");
        ADCinfo = ADCinfo + (MissingADCInfo.contains("COUNTRY OF ISSUANCE") ? ("\n" + countryIssuance) : "");
        ADCinfo = ADCinfo + (MissingADCInfo.contains("EXPIRATION DATE") ? ("\n" + expDate) : "");
        ADCinfo = ADCinfo + (MissingADCInfo.contains("SCR") ? ("\n" + "SCR:") : "");

        return ADCinfo;

    }

    public boolean validatePrimaryADCESTA(String ADCInfo, ExtentTest logInfo) throws IOException {

        isharesPageObjects2.INPUT_TEXT_AREA_ROWS24.click();
        isharesPageObjects2.INPUT_TEXT_AREA_ROWS24.sendKeys(Keys.chord(Keys.CONTROL + "a" + Keys.BACK_SPACE));

        gl.copyCmdToClipboardAndPaste(ADCInfo, isharesPageObjects2.FORMSIZE_SELECT2_TEXTAREA);
        isharesPageObjects2.SEND_ISHARES.click();

        gl.waitForProfileLoad();

        String response = isharesPageObjects2.SHARES_RESPONSE.getText();

        if (response.contains("DOCTYPE: P-PASSPORT") || response.contains("US DESTINATION ADDRESS") || response.contains("SEATS ASSIGNED") || response.contains("CABIN STBY") || response.contains("DOCTYPE: A-ALIEN CARD") || response.contains("END OF API COLLECT MODE") || response.contains("BIRTHPLC INFORMATION")) {
            gl.scrollPageDown();
            logInfo.addScreenCaptureFromBase64String(getBase64(getDriver()), "Screenshot");
            return true;
        } else {
            gl.scrollPageDown();
            logInfo.addScreenCaptureFromBase64String(getBase64(getDriver()), "Screenshot");
            return false;
        }

    }

    public String add_SecondaryADCESTA(String IncompleteADCInfo) {
        String[] S1 = IncompleteADCInfo.split("\n");
        String baseCommand;
        if (globalConstants.testEnv.equalsIgnoreCase("sharesCURL")) {
            baseCommand = S1[1].substring(1) + "\n" + S1[2] + "\n" + S1[3];
        } else {
            baseCommand = S1[0] + "\n" + S1[1] + "\n" + S1[2];

        }
        Passenger pax = mPassengers.get(getDriverID()).get(0);

        String streetname = pax.getCountryCode() + generateBlankSpace(3) + "* STREET OR P O BOX";
        String CityName = pax.getCountryCode() + generateBlankSpace(3) + "CITY NAME";
        String stateCode = pax.getCountryCode() + generateBlankSpace(3) + "COUNTY/STATE CODE";
        String postalCode = "38483463" + generateBlankSpace(8) + "POSTAL/ZIP CODE";  //YYMMDD
        String countrycode = pax.getCountryCode() + generateBlankSpace(3) + "COUNTRY CODE";  //YYMMDD


        String ADCinfo = baseCommand;
        ADCinfo = ADCinfo + (IncompleteADCInfo.contains("STREET OR P O BOX") ? ("\n" + streetname) : "");
        ADCinfo = ADCinfo + (IncompleteADCInfo.contains("CITY NAME") ? ("\n" + CityName) : "");
        ADCinfo = ADCinfo + (IncompleteADCInfo.contains("COUNTY/STATE CODE") ? ("\n" + stateCode) : "");
        ADCinfo = ADCinfo + (IncompleteADCInfo.contains("POSTAL/ZIP CODE") ? ("\n" + postalCode) : "");
        ADCinfo = ADCinfo + (IncompleteADCInfo.contains("COUNTRY CODE") ? ("\n" + countrycode) : "");
        ADCinfo = ADCinfo + (IncompleteADCInfo.contains("SCR") ? ("\n" + "SCR:") : "");
//        ADCinfo = ADCinfo + (IncompleteADCInfo.contains("DOCTYPE:") ? ("\n" + "DOCTYPE: P-PASSPORT") : "");

        return ADCinfo;
    }

