    public void sharesCheckinForUnassignedSeats(ExtentTest logInfo, String origin) {
        try {
            boolean repeatTrns;

            gl.ignoreTRNS(logInfo);

            for (int i = 0; i < mPassengers.get(getDriverID()).size(); i++) {
                repeatTrns = true;

//                ***** Entering Base command *****
                while (repeatTrns) {

                    gl.logCommand(logInfo, addCheckinCmdUnassignedSeats(origin, i));
                    gl.copyCmdToClipboardAndPaste(addCheckinCmdUnassignedSeats(origin, i), isharesPageObjects2.FORMSIZE_SELECT2_TEXTAREA);
                    gl.waitForProfileLoad();

                    isharesPageObjects2.SEND_ISHARES.click();
                    gl.waitForProfileLoad();
                    logInfo.addScreenCaptureFromBase64String(getBase64(getDriver()), "Screenshot");
                    String response = isharesPageObjects2.SHARES_RESPONSE.getText();
                    gl.logResponse(logInfo,response);

                    if (response.contains("NOT OPEN")) {
                        openFlight(logInfo, mPassengers.get(getDriverID()).get(0).getSegmentFlight(0), gl.sharesFormatDateFromGUI(mPassengers.get(getDriverID()).get(0).getSegmentDate(0)), origin);
                        gl.ignoreTRNS(logInfo);
                    } else if (response.contains("PASSENGER DISPLAY") || response.contains("UNABLE TO RETRIEVE FDR-CHK DATA BASE")) {
                        Assert.fail();
                    } else {
                        repeatTrns = false;
                    }
                }

                if(isharesPageObjects2.SHARES_RESPONSE.getText().contains("SEATS UNASSIGNED"))
                    logInfo.pass("Checkin done and SEATS UNASSIGNED for: "+mPassengers.get(getDriverID()).get(i).getFullName());
                else
                {
                    logInfo.fail("Checkin couldnt be done and SEATS cant be made UNASSIGNED for: "+mPassengers.get(getDriverID()).get(i).getFullName());
                    Assert.fail();
                }
            }
            mText.put(getDriverID(), isharesPageObjects2.SHARES_RESPONSE.getText());
            isharesPageObjects2.FORMSIZE_DROPDOWN.click();
            isharesPageObjects2.FORMSIZE_SELECT1.click();
        } catch (AssertionError | Exception e) {
            ExtentReportListener.testStepHandle("FAIL", getDriver(), logInfo, e);
            Assert.fail("This step failed.. so stopping...");
        }
    }

    public String addCheckinCmdUnassignedSeats(String origin, int paxIndex) {
        gl.waitForProfileLoad();
        isharesPageObjects2.FORMSIZE_DROPDOWN.click();
        isharesPageObjects2.FORMSIZE_SELECT24.click();

        Passenger pax = mPassengers.get(getDriverID()).get(paxIndex);

        String cmd = null;

        if (pax.getPaxType().equalsIgnoreCase("ADT") || pax.getPaxType().equalsIgnoreCase("Ins")
                || pax.getPaxType().equalsIgnoreCase("NRSA") || pax.getPaxType().equalsIgnoreCase("NRPS")) {
            cmd = "6:" + mPassengers.get(getDriverID()).get(0).getSegmentFlight(0)
                    + "/" + gl.sharesFormatDateFromGUI(mPassengers.get(getDriverID()).get(0).getSegmentDate(0))
                    + origin + "-" + pax.getfName()
                    + "/" + pax.getlName()+"|@";
        } else if (pax.getPaxType().equalsIgnoreCase("CHD")) {
            cmd = "6:" + mPassengers.get(getDriverID()).get(0).getSegmentFlight(0)
                    + "/" + gl.sharesFormatDateFromGUI(mPassengers.get(getDriverID()).get(0).getSegmentDate(0))
                    + origin + "-" + pax.getfName()
                    + "/" + pax.getlName()+"|@";
        } else if (pax.getPaxType().equalsIgnoreCase("Inf")) {

            cmd = "6:" + mPassengers.get(getDriverID()).get(0).getSegmentFlight(0)
                    + "/" + gl.sharesFormatDateFromGUI(mPassengers.get(getDriverID()).get(0).getSegmentDate(0))
                    + origin + "-" + pax.getAccompaniedPaxDetails().getfName()
                    + "/" + pax.getAccompaniedPaxDetails().getlName()+"|@";

        }else if ( pax.getPaxType().equalsIgnoreCase("FQTV")) {
            cmd = "6:" + mPassengers.get(getDriverID()).get(0).getSegmentFlight(0)
                    + "/" + gl.sharesFormatDateFromGUI(mPassengers.get(getDriverID()).get(0).getSegmentDate(0))
                    + origin + "-" + pax.getfName()
                    + "/" + pax.getlName()+"*"+pax.getFFNumber()+"|@";
        }

        return cmd;
    }
    public void changeCOSwith6P(ExtentTest logInfo, String COS, String SegmentNumber) {

        try {
            int segNo = Integer.parseInt(SegmentNumber);
            Passenger pax = mPassengers.get(getDriverID()).get(0);
            String flight = pax.getSegmentFlight(segNo - 1);

            //   .3@J
            String changeCOS = "." + SegmentNumber + "@" + COS;
            gl.logCommand(logInfo, changeCOS);
            gl.sendCmdValidateResponse(changeCOS, "002-OK-", logInfo);

            gl.logCommand(logInfo, "6P");
            gl.sendCmdValidateResponse("6P", "6P", logInfo);
            gl.sendCmdIfRequired("ER", flight, logInfo);

        } catch (AssertionError | Exception e) {
            ExtentReportListener.testStepHandle("FAIL", getDriver(), logInfo, e);
            Assert.fail("This step failed.. so stopping...");
        }
    }

