    public String returnSeatNumber(String economySeatMap,String typeOfSeat)
    {
        String[] economySeatMapLines=economySeatMap.split("\n");
        char number = '0';
        char[] temp=economySeatMapLines[0].toCharArray();

        for(int i=0;i<temp.length;i++)
        {
            char ch = temp[i];
            if(ch==' ')
            {
                temp[i]=number;
            }
            else if(ch!='Y')
            {
                number=temp[i];
            }
        }

        economySeatMapLines[0]=new String(temp);

        String seatDigits1=economySeatMapLines[0];
        String seatDigits2=economySeatMapLines[1];

        int index=-1;
        int seatRow=-1;
        for(int i=2;i<economySeatMapLines.length-1;i++)
        {
            if(economySeatMapLines[i].contains(typeOfSeat) && economySeatMapLines[i].indexOf(typeOfSeat)!=0)
            {
                index=economySeatMapLines[i].indexOf(typeOfSeat);
                seatRow=i;
                break;
            }
        }

        if(index==-1)
            return null;
        else
            return seatDigits1.charAt(index) +String.valueOf(seatDigits2.charAt(index))
                    + economySeatMapLines[seatRow].charAt(0);

    }

    public String returnEconomySeatMap(String rawSeatMap)
    {
        String economySeatMap="";
        // Split the seat map into lines
        String[] seatMapLines = rawSeatMap.split("\n");

        // Find the first occurrence of 'Y'
        int startRow = -1;
        int startColumn = -1;
        int stopColumn =-1;

        for (int i = 0; i < seatMapLines.length; i++)
        {
            String line = seatMapLines[i];

            if(line.contains(mPassengers.get(getDriverID()).get(0).getSegmentFlight(0)))
            {
                startColumn = line.indexOf('Y');
                startRow = i;
                for(int j=startColumn+3;j<seatMapLines[i+1].toCharArray().length;j++)
                {
                    if(seatMapLines[i+1].toCharArray()[j]==' ')
                    {
                        stopColumn=j;
                        break;
                    }
                }

                break; // Stop when the first 'Y' is found
            }
        }

        // If 'Y' is found, extract the horizontal and vertical portions
        if (startRow != -1 && startColumn != -1)
        {

            // Extract vertically from the row where 'Y' was found
            for (int i = startRow; i < seatMapLines.length; i++)
            {
                String line = seatMapLines[i];

                if(line.contains(".-TAKEN"))
                    break;
                else if (line.length() > startColumn && line.length()>=stopColumn)    // Only print the portion of the string starting from 'Y' in each row
                    economySeatMap=economySeatMap+line.substring(startColumn,stopColumn)+"\n";

            }
        }
        return economySeatMap;
    }
