    public void sharesCheckinMultiInitialForCheckinTypes(ExtentTest logInfo, String origin, String checkinType) {
        try {
            Passenger pax = mPassengers.get(getDriverID()).get(0);
            boolean repeatTrns;
            boolean multiInitialCheckin = true;
            String response;

            int totalBag = pax.getTotalBags();
            int Weight = pax.getBaggageWeight();

            gl.ignoreTRNS(logInfo);

            isharesPageObjects2.FORMSIZE_DROPDOWN.click();
            isharesPageObjects2.FORMSIZE_SELECT24.click();

            int x = (int) ((Math.random() * (555555 - 111111)) + 222222);

            //            ############ For Multi Initial pax #############
            for (int i = 0; i < mPassengers.get(getDriverID()).size(); i++) {

                repeatTrns = true;
                Passenger passenger = mPassengers.get(getDriverID()).get(i);

                if (passenger.getIsSameSurname()) {
//                Since for multi initial , only one pax is enough for checkin, all other same surnames will be checkin in

                    //                ***** Entering Base command *****
                    while (repeatTrns && multiInitialCheckin) {

                        String command;

                        if (checkinType.equalsIgnoreCase("ForeSellMultiInitialPax"))
                            command = addForeSellForMultiInitialPassenger(origin, i);
                        else if (checkinType.equalsIgnoreCase("ForeSellMultiInitialPaxWithManualTagBaggage"))
                            command = addForeSellForMultiInitialPaxWithManualTagBaggage(origin, i, totalBag, Weight, x);
                        else if (checkinType.equalsIgnoreCase("GoShowPNRCheckinForAPartyOfTwo"))
                            command=goShowCheckinForAPartyOfTwo(origin, i, totalBag, Weight, x);
                        else if (checkinType.equalsIgnoreCase("GoShowPNRCheckinWithBaggage"))
                            command=goShowPNRCheckinWithBaggage(origin, i, totalBag, Weight, x);
                        else
                            command=addCheckinCmd(origin, i);

                        gl.logCommand(logInfo,command);
                        gl.copyCmdToClipboardAndPaste(command, isharesPageObjects2.FORMSIZE_SELECT2_TEXTAREA);

                        isharesPageObjects2.SEND_ISHARES.click();
                        gl.waitForProfileLoad();
                        logInfo.addScreenCaptureFromBase64String(getBase64(getDriver()), "Screenshot");
                        response = isharesPageObjects2.SHARES_RESPONSE.getText();
                        gl.logResponse(logInfo,response);

                        if (response.contains("NOT OPEN")) {
                            openFlight(logInfo,pax.getSegmentFlight(0), gl.sharesFormatDateFromGUI(pax.getSegmentDate(0)), origin);
                            gl.ignoreTRNS(logInfo);
                        } else if (response.contains("PASSENGER DISPLAY") || response.contains("UNABLE TO RETRIEVE FDR-CHK DATA BASE")) {
                            Assert.fail();
                        } else {
                            repeatTrns = false;
                            multiInitialCheckin = false;
                        }

                    }

                    //**** PRIMARY DOCUMENT DETAILS*****
                    String IncompleteADCInfo;
                    if (globalConstants.testEnv.equalsIgnoreCase("sharesCURL") || globalConstants.testEnv.equalsIgnoreCase("sharesD3URL"))
                        IncompleteADCInfo = isharesPageObjects2.SHARES_RESPONSE.getText();
                    else
                        IncompleteADCInfo = isharesPageObjects2.INPUT_TEXT_AREA_ROWS24.getText();

                    String CompleteADCInfo = add_PrimaryADC(IncompleteADCInfo, i);
                    System.out.println(CompleteADCInfo);

                    while (!validatePrimaryADCMultiInitial(CompleteADCInfo, logInfo, i))  //to check Primary details are entered properly or not
                        CompleteADCInfo = reformPrimaryADC(i);

                    logInfo.pass("Primary Document Details entered for " + passenger.getFullName());

//                   **** SECONDARY DOCUMENT DETAILS  ****

                    if (isharesPageObjects2.SHARES_RESPONSE.getText().contains("DOCTYPE: P-PASSPORT")
                            || isharesPageObjects2.SHARES_RESPONSE.getText().contains("DOCUMENT INFORMATION")) {

                        String IncompleteDoctypeInfo_Adult;
                        if (globalConstants.testEnv.equalsIgnoreCase("sharesCURL")
                                || globalConstants.testEnv.equalsIgnoreCase("sharesD3URL"))
                            IncompleteDoctypeInfo_Adult = isharesPageObjects2.SHARES_RESPONSE.getText();
                        else
                            IncompleteDoctypeInfo_Adult = isharesPageObjects2.INPUT_TEXT_AREA_ROWS24.getText();

                        System.out.println("IncompleteDoctypeInfo_Adult : \n" + IncompleteDoctypeInfo_Adult + "\n");
                        String CompleteDoctypeInfo_Adult = add_SecondaryADC(IncompleteDoctypeInfo_Adult);
                        System.out.println("CompleteDoctypeInfo_Adult : \n" + CompleteDoctypeInfo_Adult + "\n");

                        while (!validateSecondaryADCMultiInitial(CompleteDoctypeInfo_Adult, logInfo, i))
                            CompleteDoctypeInfo_Adult = reformSecondaryADC();

                        logInfo.pass("Secondary Document Details entered for :" + passenger.getFullName());
                    }

                }// end of if

            }

            Assert.assertTrue(isharesPageObjects2.SHARES_RESPONSE.getText().contains("SEATS ASSIGNED"), "Checkin Unsuccessful");
            logInfo.addScreenCaptureFromBase64String(getBase64(getDriver()), "Screenshot");

            mText.put(getDriverID(), isharesPageObjects2.SHARES_RESPONSE.getText());
            isharesPageObjects2.FORMSIZE_DROPDOWN.click();
            isharesPageObjects2.FORMSIZE_SELECT1.click();

        } catch (AssertionError | Exception e) {

            ExtentReportListener.testStepHandle("FAIL", getDriver(), logInfo, e);
            Assert.fail("This step failed.. so stopping...");
        }
    }


