    public void enterAllPassengerDetailsForSameSurnamePax(ExtentTest logInfo) {


        List<Passenger> pax= mPassengers.get(getDriverID());

        String Surname = null;

        for (int i = 0; i < mPassengers.get(getDriverID()).size(); i++) {
            if (mPassengers.get(getDriverID()).get(0).getIsSameSurnameCorporatePNR() || mPassengers.get(getDriverID()).get(0).getIsSameSurnameGroupPNR()
                    || mPassengers.get(getDriverID()).get(0).getIsSameSurname()) {
                Surname = mPassengers.get(getDriverID()).get(0).getfName();
            }
        }


        for (int i = 0; i < pax.size(); i++) {
            String command = null;
            if (pax.get(i).getPaxType().equalsIgnoreCase("INF")) {
                command = "-" +Surname + "/" + pax.get(i).getAccompaniedPaxDetails().getlName()+ "*-INF" + pax.get(i).getlName() + "/" + pax.get(i).getDOB();
            } else if (pax.get(i).getPaxType().equalsIgnoreCase("INS")) {
                command = "-" +Surname + "/" + pax.get(i).getlName()+ "*-INS/" + pax.get(i).getDOB();
            } else if (pax.get(i).getPaxType().equalsIgnoreCase("CHD")) {
                command = "-" +Surname + "/" + pax.get(i).getlName()+ "*-CHD06";
            } else  {
                command = "-" +Surname + "/" + pax.get(i).getlName();
            }

            gl.logCommand(logInfo, command);
            gl.sendCmdValidateResponse(command, command + " *", logInfo);
        }
    }

    public void performMassTransferwithstatus(ExtentTest logInfo, String status) {

        try {
            Passenger pax = mPassengers.get(getDriverID()).get(0);
            String Flight = pax.getSegmentFlight(0);
            String Date = gl.sharesFormatDateFromGUI(pax.getSegmentDate(0));
            String Origin = pax.getSegmentOriginCity(0);
            String AlternateFlight = pax.getSegmentFlight(1);
            String AlternateDate = gl.sharesFormatDateFromGUI(pax.getSegmentDate(1));

//6:MT401/20JANPTY-LAX.472/20JANPTY-LAX#ALL/10
            gl.ignoreTRNS(logInfo);
            String massTransferCmd = "6:MT" + Flight + "/" + Date + Origin
                    + "." + AlternateFlight + "/" + AlternateDate + Origin + "|ALL";

            System.out.println("CMD: " + massTransferCmd);
            gl.logCommand(logInfo, massTransferCmd);
            gl.sendCmdValidateResponse(massTransferCmd, "MOVE FROM FLIGHT", "SHIP NOT ASSIGNED", logInfo);

            if (isharesPageObjects2.SHARES_RESPONSE.getText().contains("SHIP NOT ASSIGNED")) {
                isharesPageObjects2.COMMAND_INPUTAREA_ISHARES.sendKeys(Keys.CONTROL + "a" + Keys.BACK_SPACE);
                openFlight(logInfo, Flight, Date, Origin);
                isharesPageObjects2.FORMSIZE_DROPDOWN.click();
                isharesPageObjects2.FORMSIZE_SELECT1.click();
                gl.waitForProfileLoad();

                gl.logCommand(logInfo, massTransferCmd);
                gl.sendCmdValidateResponse(massTransferCmd, "MOVE FROM FLIGHT  " + AlternateFlight + " TO FLIGHT  " + Flight, logInfo);
            }

            isharesPageObjects2.FORMSIZE_DROPDOWN.click();
            isharesPageObjects2.FORMSIZE_SELECT2.click();
            isharesPageObjects2.FORMSIZE_SELECT2_TEXTAREA.sendKeys(Keys.CONTROL + "a" + Keys.BACK_SPACE);

            System.out.println("Flight Command" + massTransferCmd);
            String deleteAccept = "PLEASE CONFIRM -Y/N- "+status;
            String MassTransfer = massTransferCmd + "\n" + deleteAccept;
            System.out.println("MassTransfer \n" + MassTransfer);

            gl.logCommand(logInfo, MassTransfer);
            gl.sendCopiedCmdValidateResponse2(logInfo, MassTransfer, "ALL PROCESSED", "TRANSFERRED","TRANSFER ABORTED");

            logInfo.pass("I perform mass transfer for all the passengers");


        } catch (AssertionError | Exception e) {

            ExtentReportListener.testStepHandle("FAIL", getDriver(), logInfo, e);
            Assert.fail("This step failed.. so stopping...");
        }
    }


