    public void addSameFirstName(ExtentTest logInfo, String noOfPax) {

        try {
            Faker faker = new Faker();
            String lname = faker.name().firstName().replaceAll("[^a-zA-Z0-9]", "").toUpperCase();

            System.out.println("The new Surname is  : " + lname);

            for (int i = 0; i < Integer.parseInt(noOfPax); i++) {
                if(mPassengers.get(getDriverID()).get(i).getPaxType().equalsIgnoreCase("INF"))
                {
                    mPassengers.get(getDriverID()).get(i).getAccompaniedPaxDetails().setlName(lname);
                    mPassengers.get(getDriverID()).get(i).setIsSameSurname(true);
                }else {
                    mPassengers.get(getDriverID()).get(i).setlName(lname);
                    mPassengers.get(getDriverID()).get(i).setIsSameSurname(true);
                }

            }

        } catch (AssertionError | Exception e) {
            ExtentReportListener.testStepHandle("FAIL", getDriver(), logInfo, e);
            Assert.fail("This step failed.. so stopping...");
        }
    }

    public void SearchForFlightAvailabilityForSelectingTheSecondMarriedSegment(ExtentTest logInfo, String Origin, String Destination) {

        try
        {
            boolean flightFound=false;
            String COS = mPassengers.get(getDriverID()).get(0).getCOS();
            int totalpax = mPassengers.get(getDriverID()).size();
            String airline = mPassengers.get(getDriverID()).get(0).getAirline(0);
            int initialDepartureDate = mPassengers.get(getDriverID()).get(0).getSegmentDate(2); // Store the initial departure date

            int departureEndDate = initialDepartureDate + 5;

            String[] economyClass = {"Y", "H", "B", "M"};
            String[] businessClass = {"C", "D", "J", "R"};


            if (COS.contains("Y") || COS.contains("B") || COS.contains("H") || COS.contains("M") ||
                    COS.contains("W") || COS.contains("K") || COS.contains("Q") ||
                    COS.contains("E") || COS.contains("F"))
            {

                int departuredate = initialDepartureDate; // Reset departure date for each class and destination
                DepartureDate:
                while (departuredate <= departureEndDate) // Iterate through date range
                {
                    displaySeatsAvailabilityForFlightsForValidMarriedSegment(logInfo, Origin, Destination, 2, departuredate);
                    boolean showMore=false;

                    for(int i=0;i<2;i++) {
                        Flight:
                        for (int j = 1; j <= flightIndex.get(getDriverID()).size(); j++)  // Loop for flights
                        {
                            ClassOfService:
                            for (String tcos : economyClass)  // Iterate through all classes in businessClass
                            {
                                COS = tcos;
                                String command;
                                command = "N" + totalpax + COS + flightIndex.get(getDriverID()).get(j - 1);  //N2Y1

                                gl.logCommand(logInfo, command);
                                gl.sendCmdValidateResponse(command, logInfo);

                                String response = isharesPageObjects2.SHARES_RESPONSE.getText();
                                gl.checkForErrors(command, response, logInfo);

                                if (response.contains("ETKT ELIGIBLE") || response.contains("ADV PAX FLT ARRIVES TERMINAL") ||
                                        response.contains("SS" + totalpax) || response.contains("NN" + totalpax)) {
                                    String marriedSegment = "";
                                    String mainSegment = "";

                                    String segmentNumberRegex = "^\\s*[1-9]\\b.*";
                                    Pattern segmentNumberPattern = Pattern.compile(segmentNumberRegex);
                                    String[] rows = response.split("\n");

                                    for (int k = 0; k < rows.length; k++) {
                                        Matcher matcher1 = segmentNumberPattern.matcher(rows[k]);

                                        if (matcher1.find()) {
                                            if (rows[k].contains(Origin))
                                                mainSegment = rows[k];
                                            else if (rows[k].contains(Destination))
                                                marriedSegment = rows[k];
                                        }
                                    }

                                    // Assign flight details to passengers
                                    for (Passenger pax : mPassengers.get(getDriverID())) {

                                        //Main Segment
                                        pax.setSegmentFlight(2, mainSegment.trim().split("\\s+")[1].replaceAll("\\D+", ""));
                                        pax.setSegmentDate(2, departuredate);
                                        pax.setAirline(2, airline);
                                        pax.setCOS(COS);
                                        pax.setSegmentDestinationCity(2, mainSegment.trim().split("\\s+")[4].substring(3, 6));

                                        int len = response.split("\n")[0].split(" ").length;

                                        if (airline.equalsIgnoreCase("CM")) {
                                            pax.setSegmentDepartureTime(0, response.split("\n")[0].split(" ")[len - 3]);
                                            if (pax.getSegmentDepartureTime(0).isEmpty()) {
                                                pax.setSegmentDepartureTime(0, response.split("\n")[0].split(" ")[len - 2]);
                                            }
                                            pax.setSegmentArrivalTime(0, response.split("\n")[0].split(" ")[len - 1]);
                                        } else {
                                            pax.setSegmentDepartureTime(0, response.split("\n")[0].split(" ")[len - 3]);
                                            pax.setSegmentArrivalTime(0, response.split("\n")[0].split(" ")[len - 1].split("/")[0]);
                                        }

                                        //Married Segment
                                        pax.setSegmentFlight(3, marriedSegment.trim().split("\\s+")[1].replaceAll("\\D+", ""));
                                        pax.setSegmentDate(3, departuredate);
                                        pax.setAirline(3, pax.getMarriedSegmentAirline());
                                        pax.setCOS(COS);
                                        pax.setSegmentOriginCity(3, mainSegment.trim().split("\\s+")[4].substring(3, 6));
                                        pax.setSegmentDestinationCity(3, Destination);
                                    }

                                    flightFound = true;
                                    break DepartureDate; // Exit as soon as a flight is booked
                                } else if (showMore)
                                    displayNextSetOfFlights(logInfo, Origin, Destination, 0, departuredate);
                                else
                                    displaySeatsAvailabilityForFlightsForValidMarriedSegment(logInfo, Origin, Destination, 0, departuredate);
                            }
                        }

                        if (i == 0) {
                            logInfo.info(MarkupHelper.createLabel("Could Not Find Any Available Flight in First List, So Displaying More Number Of Available Flights", ExtentColor.BLACK));
                            showMore = true;
                            displayNextSetOfFlights(logInfo, Origin, Destination, 0, departuredate);
                        }
                    }

                    // Move to the next day
                    departuredate++;

                    if (departuredate > departureEndDate) {
                        break; // Exit date loop if all days are checked
                    }

                }// end of while
            }
            else if (COS.contains("C") || COS.contains("J") || COS.contains("D") || COS.contains("R"))
            {

                int departuredate = initialDepartureDate; // Reset departure date for each class and destination
                DepartureDate:
                while (departuredate <= departureEndDate) // Iterate through date range
                {
                    displaySeatsAvailabilityForFlightsForValidMarriedSegment(logInfo, Origin, Destination, 0, departuredate);
                    boolean showMore=false;

                    for(int i=0;i<2;i++)
                    {
                        Flight:
                        for (int j = 1; j <= flightIndex.get(getDriverID()).size(); j++)  // Loop for flights
                        {
                            ClassOfService:
                            for (String tcos : businessClass)  // Iterate through all classes in businessClass
                            {
                                COS = tcos;
                                String command;
                                command = "N" + totalpax + COS + flightIndex.get(getDriverID()).get(j - 1);  //N2Y1

                                gl.logCommand(logInfo, command);
                                gl.sendCmdValidateResponse(command, logInfo);

                                String response = isharesPageObjects2.SHARES_RESPONSE.getText();
                                gl.checkForErrors(command, response, logInfo);

                                if (response.contains("ETKT ELIGIBLE") || response.contains("ADV PAX FLT ARRIVES TERMINAL") ||
                                        response.contains("SS" + totalpax) || response.contains("NN" + totalpax))
                                {
                                    String marriedSegment = "";
                                    String mainSegment = "";

                                    String segmentNumberRegex = "^\\s*[1-9]\\b.*";
                                    Pattern segmentNumberPattern = Pattern.compile(segmentNumberRegex);
                                    String[] rows = response.split("\n");

                                    for (int k = 0; k < rows.length; k++)
                                    {
                                        Matcher matcher1 = segmentNumberPattern.matcher(rows[k]);

                                        while(matcher1.find())
                                        {
                                            if(rows[k].contains("*") && rows[k].contains(Origin))
                                                mainSegment=rows[k];
                                            else if(rows[k].contains("*") && rows[k].contains(Destination))
                                                marriedSegment=rows[k];
                                        }

                                    }

                                    // Assign flight details to passengers
                                    for (Passenger pax : mPassengers.get(getDriverID())) {

                                        //Main Segment
                                        pax.setSegmentFlight(2, mainSegment.substring(6, 10).trim());
                                        pax.setSegmentDate(2, departuredate);
                                        pax.setAirline(2, airline);
                                        pax.setCOS(COS);
                                        pax.setSegmentDestinationCity(2,mainSegment.substring(mainSegment.indexOf("*")-3,mainSegment.indexOf("*")).trim());

                                        int len = response.split("\n")[0].split(" ").length;

                                        if (airline.equalsIgnoreCase("CM")) {
                                            pax.setSegmentDepartureTime(0, response.split("\n")[0].split(" ")[len - 3]);
                                            if (pax.getSegmentDepartureTime(0).isEmpty()) {
                                                pax.setSegmentDepartureTime(0, response.split("\n")[0].split(" ")[len - 2]);
                                            }
                                            pax.setSegmentArrivalTime(0, response.split("\n")[0].split(" ")[len - 1]);
                                        } else {
                                            pax.setSegmentDepartureTime(0, response.split("\n")[0].split(" ")[len - 3]);
                                            pax.setSegmentArrivalTime(0, response.split("\n")[0].split(" ")[len - 1].split("/")[0]);
                                        }

                                        //Married Segment
                                        pax.setSegmentFlight(3,marriedSegment.substring(6,10).trim());
                                        pax.setSegmentDate(3, departuredate);
                                        pax.setAirline(3, pax.getMarriedSegmentAirline());
                                        pax.setCOS(COS);
                                        pax.setSegmentOriginCity(3,marriedSegment.substring(marriedSegment.indexOf("*")-6,marriedSegment.indexOf("*")-3).trim());
                                        pax.setSegmentDestinationCity(3,Destination);
                                    }


                                    flightFound=true;
                                    break DepartureDate; // Exit as soon as a flight is booked
                                }
                                else if(showMore)
                                    displayNextSetOfFlights(logInfo, Origin, Destination, 0, departuredate);
                                else
                                    displaySeatsAvailabilityForFlightsForValidMarriedSegment(logInfo, Origin, Destination, 0, departuredate);
                            }
                        }

                        if(i==0)
                        {
                            logInfo.info(MarkupHelper.createLabel("Could Not Find Any Available Flight in First List, So Displaying More Number Of Available Flights", ExtentColor.BLACK));
                            showMore=true;
                            displayNextSetOfFlights(logInfo, Origin, Destination, 0, departuredate);
                        }

                    }

                    // Move to the next day
                    departuredate++;

                    if (departuredate > departureEndDate) {
                        break; // Exit date loop if all days are checked
                    }

                }// end of while
            }


            if(!flightFound)
            {
                logInfo.info(MarkupHelper.createLabel("No seats available for any destination within the specified range.", ExtentColor.RED));
                mFailureDescription.put(getDriverID(),"No seats available for any destination within the specified range.");
                Assert.fail();
            }


            logInfo.info(MarkupHelper.createLabel("Main Flight: "+mPassengers.get(getDriverID()).get(0).getSegmentFlight(2), ExtentColor.PURPLE));
            logInfo.info(MarkupHelper.createLabel("Married Flight: "+mPassengers.get(getDriverID()).get(0).getSegmentFlight(3), ExtentColor.PURPLE));
            logInfo.info(MarkupHelper.createLabel("Married Segments: "+mPassengers.get(getDriverID()).get(0).getSegmentOriginCity(2)
                    +"->"+mPassengers.get(getDriverID()).get(0).getSegmentDestinationCity(2)+"->"+
                    mPassengers.get(getDriverID()).get(0).getSegmentOriginCity(3)+"->"
                    +mPassengers.get(getDriverID()).get(0).getSegmentDestinationCity(3), ExtentColor.PURPLE));

        }
        catch (AssertionError | Exception e) {

            ExtentReportListener.testStepHandle("FAIL", getDriver(), logInfo, e);
            Assert.fail("This step failed.. so stopping...");
        }

    }


